void PrintSchedulerControlTransition(const SchedulerControlExperimentRow& row,
                                            const std::string& newStatus,
                                            const std::string& newPhase)
{
    std::cout << "Experiment " << row.experimentId << "\n"
              << "Current: status=" << row.status << " phase=" << row.phase << "\n"
              << "Requested: status=" << newStatus << " phase=" << newPhase << "\n";
}

void PrintSchedulerControlApplied(const std::string& action,
                                         long long experimentId,
                                         const std::string& newStatus,
                                         const std::string& newPhase)
{
    std::cout << "SCHEDULER_CONTROL_APPLIED"
              << ",action=" << action
              << ",experiment_id=" << experimentId
              << ",new_status=" << newStatus
              << ",new_phase=" << newPhase;
    if (action == "requeue_inference")
    {
        std::cout
            << ",operator_forced_final_inference_rerun_requested=1";
    }
    std::cout << std::endl;
}

std::optional<std::string> ValidateSchedulerControlTransition(const SchedulerOptions& options,
                                                                     const SchedulerControlExperimentRow& row,
                                                                     std::string& newStatus,
                                                                     std::string& newPhase)
{
    newStatus = row.status;
    newPhase = row.phase;

    if (options.pauseExperimentId.has_value())
    {
        if (row.status != "pending")
            return "pause_requires_pending_status";
        newStatus = "paused";
        return std::nullopt;
    }
    if (options.resumeExperimentId.has_value())
    {
        if (row.status != "paused")
            return "resume_requires_paused_status";
        newStatus = "pending";
        return std::nullopt;
    }
    if (options.cancelExperimentId.has_value())
    {
        if (row.status == "running")
            return "running_experiment_cannot_be_cancelled";
        if (row.status != "pending" && row.status != "paused")
            return "cancel_requires_pending_or_paused_status";
        newStatus = "cancelled";
        return std::nullopt;
    }
    if (options.retryFailedExperimentId.has_value())
    {
        if (row.status != "failed")
            return "retry_requires_failed_status";
        newStatus = "pending";
        newPhase = RetryPhaseForExperiment(row);
        return std::nullopt;
    }
    if (options.requeueAnalysisExperimentId.has_value())
    {
        if (row.status == "running")
            return "running_experiment_cannot_be_requeued";
        if (!ControlModelId(row).has_value())
            return "requeue_analysis_requires_model_id";
        newStatus = "pending";
        newPhase = "analyze";
        return std::nullopt;
    }
    if (options.requeueInferenceExperimentId.has_value())
    {
        if (row.status == "running")
            return "running_experiment_cannot_be_requeued";
        if (!ControlModelId(row).has_value())
            return "requeue_inference_requires_model_id";
        newStatus = "pending";
        newPhase = "infer";
        return std::nullopt;
    }

    return "unknown_scheduler_control_action";
}

void ApplySchedulerControlTransition(pqxx::work& w,
                                            const std::string& action,
                                            const SchedulerControlExperimentRow& row,
                                            const std::string& newStatus,
                                            const std::string& newPhase,
                                            const std::optional<long long>& promotedResumeModelId =
                                                std::nullopt)
{
    std::ostringstream sql;
    sql << "UPDATE experiment SET status = " << w.quote(newStatus)
        << ", phase = " << w.quote(newPhase)
        << ", updated_at = now()";

    if (action == "cancel")
    {
        sql << ", completed_at = now()";
    }
    else if (action == "retry_failed" ||
             action == "requeue_analysis" ||
             action == "requeue_inference")
    {
        sql << ", started_at = NULL"
            << ", worker_started_at = NULL"
            << ", completed_at = NULL"
            << ", exit_code = NULL"
            << ", error_message = NULL"
            << ", worker_pid = NULL"
            << ", worker_process_group_id = NULL"
            << ", worker_process_start_identity = NULL"
            << ", worker_executable = NULL"
            << ", worker_command_line = NULL"
            << ", worker_control_state = 'running'"
            << ", worker_global_pause_request_id = NULL"
            << ", active_scheduler_worker_attempt_id = NULL"
            << ", current_operation = NULL";
    }

    if (action == "requeue_inference")
    {
        sql << ", operator_forced_final_inference_rerun_requested = true";
    }

    if (promotedResumeModelId.has_value())
        sql << ", resume_model_id = " << *promotedResumeModelId;

    sql << " WHERE experiment_id = " << row.experimentId << ";";
    w.exec(sql.str());
}

int RunSchedulerControlCommand(const SchedulerOptions& options)
{
    const std::string action = SchedulerControlActionName(options);
    const long long experimentId = SchedulerControlExperimentId(options);
    if (options.resumeExperimentId.has_value())
    {
        EA::GlobalExperimentControl::ExperimentResumeCommand command;
        command.experimentId = experimentId;
        command.dryRun = options.dryRun;
        command.confirmed = options.yes;
        const auto invocationStarted =
            std::chrono::system_clock::now().time_since_epoch();
        command.invocationIdentity =
            std::string{"pid:"} + std::to_string(::getpid()) +
            ";started_ns:" +
            std::to_string(
                std::chrono::duration_cast<std::chrono::nanoseconds>(
                    invocationStarted)
                    .count()) +
            ";executable:" + options.selfPath;
        return EA::GlobalExperimentControl::RunExperimentResumeCommand(
            LstmDbConnectionString(), command, std::cout, std::cerr);
    }
    const bool willApply = options.yes && !options.dryRun;

    pqxx::connection c{LstmDbConnectionString()};
    pqxx::work w{c};
    if (willApply)
        SetTransactionReadWrite(w);
    if (!RequireSchedulerTables(w))
        return 2;

    std::optional<SchedulerControlExperimentRow> row =
        LoadSchedulerControlExperiment(w, experimentId, willApply);
    if (!row.has_value())
    {
        PrintSchedulerControlRejected(action, experimentId, "experiment_not_found");
        w.commit();
        return 1;
    }

    PrintSchedulerControlAttempt(action, *row);

    std::string newStatus;
    std::string newPhase;
    if (const std::optional<std::string> rejection =
            ValidateSchedulerControlTransition(options, *row, newStatus, newPhase);
        rejection.has_value())
    {
        PrintSchedulerControlRejected(action, experimentId, *rejection);
        w.commit();
        return 1;
    }

    PrintSchedulerControlTransition(*row, newStatus, newPhase);

    RetryCheckpointSelection retryCheckpointSelection;
    if (action == "retry_failed" && row->phase == "train")
    {
        retryCheckpointSelection = SelectRetryTrainingCheckpoint(w, *row);
        PrintRetryCheckpointSelection(experimentId, retryCheckpointSelection);
    }

    if (options.dryRun)
    {
        std::cout << "SCHEDULER_CONTROL_DRY_RUN"
                  << ",action=" << action
                  << ",experiment_id=" << experimentId
                  << ",new_status=" << newStatus
                  << ",new_phase=" << newPhase
                  << std::endl;
        w.commit();
        return 0;
    }

    if (!options.yes)
    {
        std::cout << "Use --yes to apply." << std::endl;
        w.commit();
        return 0;
    }

    ApplySchedulerControlTransition(
        w,
        action,
        *row,
        newStatus,
        newPhase,
        retryCheckpointSelection.promoted
            ? retryCheckpointSelection.selectedResumeModelId
            : std::nullopt);
    PrintSchedulerControlApplied(action, experimentId, newStatus, newPhase);
    w.commit();
    return 0;
}

int RunRetryCheckpointEvalCommand(const SchedulerOptions& options)
{
    if (!options.retryCheckpointEvalId.has_value())
        throw std::invalid_argument("missing checkpoint_eval_id for retry");

    pqxx::connection c{LstmDbConnectionString()};
    pqxx::work w{c};
    if (!options.dryRun)
        SetTransactionReadWrite(w);
    if (!TableExists(w, "experiment_checkpoint_eval"))
    {
        std::cerr << "DATABASE_MIGRATION_REQUIRED"
                  << ",missing=experiment_checkpoint_eval"
                  << ",command=./migrate_lstm_db.sh"
                  << std::endl;
        return 2;
    }

    std::ostringstream selectSql;
    selectSql
        << "SELECT checkpoint_eval_id, COALESCE(parent_experiment_id, experiment_id), "
        << "checkpoint_model_id, checkpoint_epoch, status, phase "
        << "FROM experiment_checkpoint_eval "
        << "WHERE checkpoint_eval_id = $1";
    if (!options.dryRun)
        selectSql << " FOR UPDATE";
    selectSql << ";";
    pqxx::result rows = w.exec_params(selectSql.str(), *options.retryCheckpointEvalId);
    if (rows.empty())
    {
        std::cerr << "CHECKPOINT_EVAL_RETRY_REJECTED"
                  << ",checkpoint_eval_id=" << *options.retryCheckpointEvalId
                  << ",reason=checkpoint_eval_not_found"
                  << std::endl;
        w.commit();
        return 1;
    }

    const long long checkpointEvalId = rows[0][0].as<long long>();
    const long long parentExperimentId = rows[0][1].as<long long>();
    const long long checkpointModelId = rows[0][2].as<long long>();
    const int checkpointEpoch = rows[0][3].as<int>();
    const std::string status = rows[0][4].as<std::string>();
    const std::string phase = rows[0][5].as<std::string>();
    if (status != "failed")
    {
        std::cerr << "CHECKPOINT_EVAL_RETRY_REJECTED"
                  << ",checkpoint_eval_id=" << checkpointEvalId
                  << ",parent_experiment_id=" << parentExperimentId
                  << ",checkpoint_model_id=" << checkpointModelId
                  << ",checkpoint_epoch=" << checkpointEpoch
                  << ",status=" << status
                  << ",phase=" << phase
                  << ",reason=retry_requires_failed_status"
                  << std::endl;
        w.commit();
        return 1;
    }
    if (phase != "infer")
    {
        std::cerr << "CHECKPOINT_EVAL_RETRY_REJECTED"
                  << ",checkpoint_eval_id=" << checkpointEvalId
                  << ",parent_experiment_id=" << parentExperimentId
                  << ",checkpoint_model_id=" << checkpointModelId
                  << ",checkpoint_epoch=" << checkpointEpoch
                  << ",status=" << status
                  << ",phase=" << phase
                  << ",reason=retry_requires_failed_infer_phase"
                  << std::endl;
        w.commit();
        return 1;
    }

    if (!options.dryRun)
    {
        w.exec_params(
            "UPDATE experiment_checkpoint_eval "
            "SET status = 'pending', phase = 'infer', worker_pid = NULL, "
            "started_at = NULL, completed_at = NULL, infer_started_at = NULL, "
            "infer_completed_at = NULL, analyze_started_at = NULL, analyze_completed_at = NULL, "
            "analysis_id = NULL, analysis_log_path = NULL, error_message = NULL, updated_at = now() "
            "WHERE checkpoint_eval_id = $1;",
            checkpointEvalId);
    }
    w.commit();

    std::cout << "CHECKPOINT_EVAL_RETRY_REQUESTED"
              << ",checkpoint_eval_id=" << checkpointEvalId
              << ",parent_experiment_id=" << parentExperimentId
              << ",checkpoint_model_id=" << checkpointModelId
              << ",checkpoint_epoch=" << checkpointEpoch
              << ",model_id=" << checkpointModelId
              << ",inference_scope=checkpoint"
              << ",status=" << (options.dryRun ? "dry_run" : "pending")
              << std::endl;
    return 0;
}

bool HasCheckpointControlCommand(const SchedulerOptions& options)
{
    return options.stopAfterCheckpoint.has_value() ||
           options.clearStopAfterCheckpointExperimentId.has_value() ||
           options.stopAfterCheckpointAllEpoch.has_value() ||
           options.clearStopAfterCheckpointAll ||
           options.enableCheckpointInferExperimentId.has_value() ||
           options.disableCheckpointInferExperimentId.has_value() ||
           options.checkpointInferMinEpoch.has_value() ||
           options.checkpointInferInterval.has_value() ||
           options.enableCheckpointPolicyExperimentId.has_value() ||
           options.disableCheckpointPolicyExperimentId.has_value() ||
           options.setCheckpointPolicy.has_value();
}

long long CheckpointControlExperimentId(const SchedulerOptions& options)
{
    if (options.stopAfterCheckpoint.has_value())
        return options.stopAfterCheckpoint->first;
    if (options.clearStopAfterCheckpointExperimentId.has_value())
        return *options.clearStopAfterCheckpointExperimentId;
    if (options.stopAfterCheckpointAllEpoch.has_value() || options.clearStopAfterCheckpointAll)
        return -1;
    if (options.enableCheckpointInferExperimentId.has_value())
        return *options.enableCheckpointInferExperimentId;
    if (options.disableCheckpointInferExperimentId.has_value())
        return *options.disableCheckpointInferExperimentId;
    if (options.checkpointInferMinEpoch.has_value())
        return options.checkpointInferMinEpoch->first;
    if (options.checkpointInferInterval.has_value())
        return options.checkpointInferInterval->first;
    if (options.enableCheckpointPolicyExperimentId.has_value())
        return *options.enableCheckpointPolicyExperimentId;
    if (options.disableCheckpointPolicyExperimentId.has_value())
        return *options.disableCheckpointPolicyExperimentId;
    if (options.setCheckpointPolicy.has_value())
        return options.setCheckpointPolicy->first;
    throw std::invalid_argument("missing checkpoint control experiment id");
}

int EffectiveCheckpointStopEpoch(int requestedEpoch, int checkpointInterval, int targetEpochs)
{
    if (checkpointInterval <= 0)
        return requestedEpoch;
    int effective = ((requestedEpoch + checkpointInterval - 1) / checkpointInterval) * checkpointInterval;
    if (targetEpochs > 0 && effective > targetEpochs)
        effective = targetEpochs;
    return effective;
}

std::vector<std::string> SplitCommaSeparated(const std::string& value)
{
    std::vector<std::string> parts;
    std::stringstream ss(value);
    std::string part;
    while (std::getline(ss, part, ','))
    {
        if (!part.empty())
            parts.push_back(part);
    }
    return parts;
}

SchedulerOptions ParseCheckpointPolicyUpdateOptions(const std::string& config)
{
    SchedulerOptions update;
    for (const std::string& item : SplitCommaSeparated(config))
    {
        const size_t equals = item.find('=');
        if (equals == std::string::npos || equals == 0 || equals + 1 >= item.size())
            throw std::invalid_argument("--set-checkpoint-policy requires key=value pairs");
        const std::string key = item.substr(0, equals);
        const std::string value = item.substr(equals + 1);
        if (key == "min_leader_score")
        {
            update.checkpointPolicyMinLeaderScore = ParsePositiveFiniteDouble(key, value);
            update.checkpointPolicySetKeys.insert(key);
        }
        else if (key == "min_infer_accuracy")
        {
            update.checkpointPolicyMinInferAccuracy = ParsePositiveFiniteDouble(key, value);
            update.checkpointPolicySetKeys.insert(key);
        }
        else if (key == "top_n")
        {
            update.checkpointPolicyTopN = ParsePositiveInt(key, value);
            update.checkpointPolicySetKeys.insert(key);
        }
        else if (key == "scope")
        {
            update.checkpointPolicyScope = value;
            update.checkpointPolicySetKeys.insert(key);
        }
        else if (key == "stop_mode")
        {
            update.checkpointPolicyStopMode = value;
            update.checkpointPolicySetKeys.insert(key);
        }
        else if (key == "grace_evals")
        {
            update.checkpointPolicyGraceEvals = ParsePositiveInt(key, value);
            update.checkpointPolicySetKeys.insert(key);
        }
        else
            throw std::invalid_argument("unsupported checkpoint policy key '" + key + "'");
    }
    ValidateCheckpointPolicyConfig(update);
    return update;
}

std::string CheckpointPolicyRuleText(const SchedulerOptions& options)
{
    std::ostringstream out;
    bool any = false;
    if (options.checkpointPolicyMinLeaderScore.has_value())
    {
        out << "leader>=" << FormatDouble(*options.checkpointPolicyMinLeaderScore);
        any = true;
    }
    if (options.checkpointPolicyMinInferAccuracy.has_value())
    {
        if (any)
            out << ";";
        out << "infer>=" << FormatDouble(*options.checkpointPolicyMinInferAccuracy);
        any = true;
    }
    if (options.checkpointPolicyTopN.has_value())
    {
        if (any)
            out << ";";
        out << "top_n=" << *options.checkpointPolicyTopN;
        any = true;
    }
    if (!any)
        out << "none";
    out << ";scope=" << options.checkpointPolicyScope
        << ";stop_mode=" << options.checkpointPolicyStopMode
        << ";grace_evals=" << options.checkpointPolicyGraceEvals;
    return out.str();
}

std::string CheckpointPolicyRuleText(const CheckpointPolicyConfig& config)
{
    std::ostringstream out;
    bool any = false;
    if (config.minLeaderScore.has_value())
    {
        out << "leader_score>=" << FormatDouble(*config.minLeaderScore);
        any = true;
    }
    if (config.minInferAccuracy.has_value())
    {
        if (any)
            out << "|";
        out << "infer_accuracy>=" << FormatDouble(*config.minInferAccuracy);
        any = true;
    }
    if (config.topN.has_value())
    {
        if (any)
            out << "|";
        out << "top_n<=" << *config.topN;
        any = true;
    }
    if (!any)
        out << "none";
    out << "|scope=" << config.scope
        << "|stop_mode=" << config.stopMode
        << "|grace_evals=" << config.graceEvals;
    return out.str();
}

CheckpointPolicyConfig LoadCheckpointPolicyControlConfig(
    pqxx::work& w,
    long long experimentId,
    bool hasCheckpointInferEnabled,
    bool hasOpportunisticCheckpointInfer)
{
    std::ostringstream sql;
    sql << "SELECT checkpoint_policy_enabled, "
        << "checkpoint_policy_min_leader_score, checkpoint_policy_min_infer_accuracy, "
        << "checkpoint_policy_top_n, checkpoint_policy_scope, checkpoint_policy_stop_mode, "
        << "checkpoint_policy_grace_evals, checkpoint_interval, target_epochs, current_epoch, "
        << "stop_after_checkpoint_epoch, status, phase, (";
    bool hasInferExpression = false;
    if (hasCheckpointInferEnabled)
    {
        sql << "checkpoint_infer_enabled";
        hasInferExpression = true;
    }
    if (hasOpportunisticCheckpointInfer)
    {
        if (hasInferExpression)
            sql << " OR ";
        sql << "opportunistic_checkpoint_infer";
        hasInferExpression = true;
    }
    if (!hasInferExpression)
        sql << "false";
    sql << ") AS checkpoint_infer_active, checkpoint_policy_revision, "
        << "checkpoint_policy_hash, active_scheduler_worker_attempt_id "
        << "FROM experiment WHERE experiment_id = $1 FOR UPDATE;";

    pqxx::result rows = w.exec_params(sql.str(), experimentId);
    if (rows.empty())
        throw std::runtime_error("checkpoint policy parent experiment disappeared");

    CheckpointPolicyConfig config;
    config.enabled = rows[0][0].as<bool>();
    config.minLeaderScore = OptionalDoubleCell(rows[0], 1);
    config.minInferAccuracy = OptionalDoubleCell(rows[0], 2);
    if (!rows[0][3].is_null())
        config.topN = rows[0][3].as<int>();
    config.scope = rows[0][4].as<std::string>();
    config.stopMode = rows[0][5].as<std::string>();
    config.graceEvals = rows[0][6].as<int>();
    config.checkpointInterval = rows[0][7].as<int>();
    config.targetEpochs = rows[0][8].as<int>();
    if (!rows[0][9].is_null())
        config.currentEpoch = rows[0][9].as<int>();
    if (!rows[0][10].is_null())
        config.stopAfterCheckpointEpoch = rows[0][10].as<int>();
    config.status = rows[0][11].as<std::string>();
    config.phase = rows[0][12].as<std::string>();
    config.checkpointInferEnabled = rows[0][13].as<bool>();
    config.policyRevision = rows[0][14].as<long long>();
    config.persistedPolicyHash = OptionalStringCell(rows[0], 15);
    config.activeTrainingAttemptId = OptionalLongLongCell(rows[0], 16);
    return config;
}

int RunCheckpointControlCommand(const SchedulerOptions& options)
{
    const long long experimentId = CheckpointControlExperimentId(options);
    pqxx::connection c{LstmDbConnectionString()};
    pqxx::work w{c};
    SetTransactionReadWrite(w);
    if (!RequireSchedulerTables(w))
        return 2;
    const bool hasCheckpointInferEnabled = ColumnExists(w, "experiment", "checkpoint_infer_enabled");
    const bool hasOpportunisticCheckpointInfer = ColumnExists(w, "experiment", "opportunistic_checkpoint_infer");
    const bool hasCheckpointPolicyEnabled = ColumnExists(w, "experiment", "checkpoint_policy_enabled");
    if (!ColumnExists(w, "experiment", "stop_after_checkpoint_epoch") ||
        (!hasCheckpointInferEnabled && !hasOpportunisticCheckpointInfer))
    {
        std::cerr << "DATABASE_MIGRATION_REQUIRED,command=./migrate_lstm_db.sh,missing=checkpoint_stop_columns" << std::endl;
        w.commit();
        return 2;
    }
    if ((options.enableCheckpointPolicyExperimentId.has_value() ||
         options.disableCheckpointPolicyExperimentId.has_value() ||
         options.setCheckpointPolicy.has_value()) &&
        !hasCheckpointPolicyEnabled)
    {
        std::cerr << "DATABASE_MIGRATION_REQUIRED,command=./migrate_lstm_db.sh,missing=checkpoint_policy_columns" << std::endl;
        w.commit();
        return 2;
    }

    if (options.stopAfterCheckpointAllEpoch.has_value())
    {
        const int epoch = *options.stopAfterCheckpointAllEpoch;
        pqxx::result updated = w.exec_params(
            "UPDATE experiment "
            "SET stop_after_checkpoint_epoch = $1, updated_at = now() "
            "WHERE status = 'running' AND phase = 'train' "
            "RETURNING experiment_id;",
            epoch);
        w.commit();
        std::cout << "CHECKPOINT_STOP_ALL_REQUESTED"
                  << ",count=" << updated.size()
                  << ",stop_after_checkpoint_epoch=" << epoch
                  << std::endl;
        return 0;
    }

    if (options.clearStopAfterCheckpointAll)
    {
        pqxx::result updated = w.exec(
            "UPDATE experiment "
            "SET stop_after_checkpoint_epoch = NULL, updated_at = now() "
            "WHERE status = 'running' AND phase = 'train' "
            "RETURNING experiment_id;");
        w.commit();
        std::cout << "CHECKPOINT_STOP_ALL_CLEARED"
                  << ",count=" << updated.size()
                  << std::endl;
        return 0;
    }

    pqxx::result rows = w.exec_params(
        "SELECT experiment_id, status, phase, checkpoint_interval, target_epochs "
        "FROM experiment WHERE experiment_id = $1 FOR UPDATE;",
        experimentId);
    if (rows.empty())
    {
        std::cerr << "CHECKPOINT_CONTROL_REJECTED"
                  << ",experiment_id=" << experimentId
                  << ",reason=experiment_not_found"
                  << std::endl;
        w.commit();
        return 1;
    }

    const std::string status = rows[0][1].as<std::string>();
    const std::string phase = rows[0][2].as<std::string>();
    const int checkpointInterval = rows[0][3].as<int>();
    const int targetEpochs = rows[0][4].as<int>();
    if ((options.stopAfterCheckpoint.has_value() ||
         options.clearStopAfterCheckpointExperimentId.has_value()) &&
        (phase != "train" || status != "running"))
    {
        std::cerr << "CHECKPOINT_CONTROL_REJECTED"
                  << ",experiment_id=" << experimentId
                  << ",status=" << status
                  << ",phase=" << phase
                  << ",reason=requires_running_train"
                  << std::endl;
        w.commit();
        return 1;
    }

    if (phase != "train" || (status != "pending" && status != "running" && status != "paused"))
    {
        std::cerr << "CHECKPOINT_CONTROL_REJECTED"
                  << ",experiment_id=" << experimentId
                  << ",status=" << status
                  << ",phase=" << phase
                  << ",reason=requires_train_pending_running_or_paused"
                  << std::endl;
        w.commit();
        return 1;
    }

    if (options.stopAfterCheckpoint.has_value())
    {
        const int requestedEpoch = options.stopAfterCheckpoint->second;
        const int effectiveEpoch = EffectiveCheckpointStopEpoch(requestedEpoch, checkpointInterval, targetEpochs);
        w.exec_params(
            "UPDATE experiment "
            "SET stop_after_checkpoint_epoch = $1, updated_at = now() "
            "WHERE experiment_id = $2;",
            requestedEpoch,
            experimentId);
        w.commit();
        std::cout << "CHECKPOINT_STOP_REQUESTED"
                  << ",experiment_id=" << experimentId
                  << ",stop_after_checkpoint_epoch=" << requestedEpoch
                  << ",effective_epoch=" << effectiveEpoch
                  << std::endl;
        return 0;
    }

    if (options.clearStopAfterCheckpointExperimentId.has_value())
    {
        w.exec_params(
            "UPDATE experiment "
            "SET stop_after_checkpoint_epoch = NULL, updated_at = now() "
            "WHERE experiment_id = $1;",
            experimentId);
        w.commit();
        std::cout << "CHECKPOINT_STOP_CLEARED"
                  << ",experiment_id=" << experimentId
                  << std::endl;
        return 0;
    }

    if (options.enableCheckpointInferExperimentId.has_value() ||
        options.disableCheckpointInferExperimentId.has_value())
    {
        const bool enabled = options.enableCheckpointInferExperimentId.has_value();
        if (!enabled && hasCheckpointPolicyEnabled)
        {
            pqxx::result policyRows = w.exec_params(
                "SELECT checkpoint_policy_enabled FROM experiment WHERE experiment_id = $1;",
                experimentId);
            if (!policyRows.empty() && policyRows[0][0].as<bool>())
            {
                std::cerr << "CHECKPOINT_INFER_REJECTED"
                          << ",experiment_id=" << experimentId
                          << ",reason=disable_checkpoint_policy_first"
                          << std::endl;
                w.commit();
                return 1;
            }
        }
        std::ostringstream sql;
        sql << "UPDATE experiment SET updated_at = now()";
        if (hasCheckpointInferEnabled)
            sql << ", checkpoint_infer_enabled = " << (enabled ? "true" : "false");
        if (hasOpportunisticCheckpointInfer)
            sql << ", opportunistic_checkpoint_infer = " << (enabled ? "true" : "false");
        sql << " WHERE experiment_id = " << experimentId << ";";
        w.exec(sql.str());
        w.commit();
        std::cout << (enabled ? "CHECKPOINT_INFER_ENABLED" : "CHECKPOINT_INFER_DISABLED")
                  << ",experiment_id=" << experimentId
                  << std::endl;
        return 0;
    }

    if (options.checkpointInferMinEpoch.has_value())
    {
        const int epoch = options.checkpointInferMinEpoch->second;
        w.exec_params(
            "UPDATE experiment "
            "SET checkpoint_infer_min_epoch = $1, updated_at = now() "
            "WHERE experiment_id = $2;",
            epoch,
            experimentId);
        w.commit();
        std::cout << "CHECKPOINT_INFER_MIN_EPOCH_SET"
                  << ",experiment_id=" << experimentId
                  << ",epoch=" << epoch
                  << std::endl;
        return 0;
    }

    if (options.checkpointInferInterval.has_value())
    {
        const int interval = options.checkpointInferInterval->second;
        w.exec_params(
            "UPDATE experiment "
            "SET checkpoint_infer_interval = $1, updated_at = now() "
            "WHERE experiment_id = $2;",
            interval,
            experimentId);
        w.commit();
        std::cout << "CHECKPOINT_INFER_INTERVAL_SET"
                  << ",experiment_id=" << experimentId
                  << ",interval=" << interval
                  << std::endl;
        return 0;
    }

    if (options.enableCheckpointPolicyExperimentId.has_value() ||
        options.disableCheckpointPolicyExperimentId.has_value())
    {
        const bool enabled = options.enableCheckpointPolicyExperimentId.has_value();
        CheckpointPolicyConfig config = LoadCheckpointPolicyControlConfig(
            w,
            experimentId,
            hasCheckpointInferEnabled,
            hasOpportunisticCheckpointInfer);
        if (enabled && !config.checkpointInferEnabled)
        {
            std::cerr << "CHECKPOINT_POLICY_REJECTED"
                      << ",experiment_id=" << experimentId
                      << ",reason=checkpoint_infer_not_enabled"
                      << std::endl;
            w.commit();
            return 1;
        }
        const std::optional<std::string> configError =
            CheckpointPolicyConfigurationError(config, enabled);
        if (enabled && configError.has_value())
        {
            std::cerr << "CHECKPOINT_POLICY_REJECTED"
                      << ",experiment_id=" << experimentId
                      << ",reason=" << *configError
                      << std::endl;
            w.commit();
            return 1;
        }
        CheckpointPolicyConfig resultingConfig = config;
        resultingConfig.enabled = enabled;
        const bool changed =
            CheckpointPolicyCanonicalText(config) !=
            CheckpointPolicyCanonicalText(resultingConfig);
        const std::string resultingHash =
            CheckpointPolicySemanticHash(resultingConfig);
        pqxx::result revised = w.exec_params(
            "UPDATE experiment "
            "SET checkpoint_policy_enabled = $1, "
            "checkpoint_policy_revision = checkpoint_policy_revision + "
            "CASE WHEN $2 THEN 1 ELSE 0 END, "
            "checkpoint_policy_hash = $3, updated_at = now() "
            "WHERE experiment_id = $4 "
            "RETURNING checkpoint_policy_revision;",
            enabled,
            changed,
            resultingHash,
            experimentId);
        w.commit();
        std::cout << (enabled ? "CHECKPOINT_POLICY_ENABLED" : "CHECKPOINT_POLICY_DISABLED")
                  << ",experiment_id=" << experimentId
                  << ",policy_revision=" << revised[0][0].as<long long>()
                  << ",policy_hash=" << resultingHash
                  << std::endl;
        return 0;
    }

    if (options.setCheckpointPolicy.has_value())
    {
        SchedulerOptions update = ParseCheckpointPolicyUpdateOptions(options.setCheckpointPolicy->second);
        CheckpointPolicyConfig resultingConfig = LoadCheckpointPolicyControlConfig(
            w,
            experimentId,
            hasCheckpointInferEnabled,
            hasOpportunisticCheckpointInfer);
        if (update.checkpointPolicySetKeys.count("min_leader_score"))
            resultingConfig.minLeaderScore = update.checkpointPolicyMinLeaderScore;
        if (update.checkpointPolicySetKeys.count("min_infer_accuracy"))
            resultingConfig.minInferAccuracy = update.checkpointPolicyMinInferAccuracy;
        if (update.checkpointPolicySetKeys.count("top_n"))
            resultingConfig.topN = update.checkpointPolicyTopN;
        if (update.checkpointPolicySetKeys.count("scope"))
            resultingConfig.scope = update.checkpointPolicyScope;
        if (update.checkpointPolicySetKeys.count("stop_mode"))
            resultingConfig.stopMode = update.checkpointPolicyStopMode;
        if (update.checkpointPolicySetKeys.count("grace_evals"))
            resultingConfig.graceEvals = update.checkpointPolicyGraceEvals;

        const std::optional<std::string> configError =
            CheckpointPolicyConfigurationError(resultingConfig, resultingConfig.enabled);
        if (configError.has_value())
        {
            std::cerr << "CHECKPOINT_POLICY_REJECTED"
                      << ",experiment_id=" << experimentId
                      << ",reason=" << *configError
                      << std::endl;
            w.commit();
            return 1;
        }
        const bool changed =
            CheckpointPolicyCanonicalText(resultingConfig) !=
            CheckpointPolicyCanonicalText(
                LoadCheckpointPolicyControlConfig(
                    w,
                    experimentId,
                    hasCheckpointInferEnabled,
                    hasOpportunisticCheckpointInfer));
        const std::string resultingHash =
            CheckpointPolicySemanticHash(resultingConfig);
        std::ostringstream sql;
        sql << "UPDATE experiment SET updated_at = now(), "
            << "checkpoint_policy_hash = " << w.quote(resultingHash)
            << ", checkpoint_policy_revision = checkpoint_policy_revision + "
            << (changed ? "1" : "0");
        if (update.checkpointPolicySetKeys.count("min_leader_score"))
            sql << ", checkpoint_policy_min_leader_score = " << FormatDouble(*update.checkpointPolicyMinLeaderScore);
        if (update.checkpointPolicySetKeys.count("min_infer_accuracy"))
            sql << ", checkpoint_policy_min_infer_accuracy = " << FormatDouble(*update.checkpointPolicyMinInferAccuracy);
        if (update.checkpointPolicySetKeys.count("top_n"))
            sql << ", checkpoint_policy_top_n = " << *update.checkpointPolicyTopN;
        if (update.checkpointPolicySetKeys.count("scope"))
            sql << ", checkpoint_policy_scope = " << w.quote(update.checkpointPolicyScope);
        if (update.checkpointPolicySetKeys.count("stop_mode"))
            sql << ", checkpoint_policy_stop_mode = " << w.quote(update.checkpointPolicyStopMode);
        if (update.checkpointPolicySetKeys.count("grace_evals"))
            sql << ", checkpoint_policy_grace_evals = " << update.checkpointPolicyGraceEvals;
        sql << " WHERE experiment_id = " << experimentId
            << " RETURNING checkpoint_policy_revision;";
        pqxx::result revised = w.exec(sql.str());
        w.commit();
        std::cout << "CHECKPOINT_POLICY_SET"
                  << ",experiment_id=" << experimentId
                  << ",rules=" << CheckpointPolicyRuleText(resultingConfig)
                  << ",policy_revision=" << revised[0][0].as<long long>()
                  << ",policy_hash=" << resultingHash
                  << std::endl;
        return 0;
    }

    w.commit();
    return 1;
}

std::string QueueSnapshotKey(const QueueSnapshot& snapshot)
{
    std::ostringstream key;
    key << snapshot.pendingTrain << "|"
        << snapshot.pendingInfer << "|"
        << snapshot.pendingAnalyze << "|"
        << snapshot.runningTrain << "|"
        << snapshot.runningInfer << "|"
        << snapshot.runningAnalyze;
    return key.str();
}

void PrintQueueSnapshot(const QueueSnapshot& snapshot,
                        SchedulerEventLogState* logState,
                        bool verbose)
{
    const std::string key = QueueSnapshotKey(snapshot);
    if (!verbose && logState != nullptr && logState->previousQueueKey == key)
        return;

    std::cout << "SCHEDULER_QUEUE"
              << ",pending_train=" << snapshot.pendingTrain
              << ",pending_infer=" << snapshot.pendingInfer
              << ",pending_analyze=" << snapshot.pendingAnalyze
              << ",running_train=" << snapshot.runningTrain
              << ",running_infer=" << snapshot.runningInfer
              << ",running_analyze=" << snapshot.runningAnalyze
              << std::endl;
    if (logState != nullptr)
        logState->previousQueueKey = key;
}

int RunningCountForPhase(const QueueSnapshot& snapshot, const std::string& phase)
{
    if (phase == "train")
        return snapshot.runningTrain;
    if (phase == "infer")
        return snapshot.runningInfer;
    if (phase == "analyze")
        return snapshot.runningAnalyze;
    return 0;
}

void LogSkip(const std::string& phase,
             long long experimentId,
             const std::string& reason,
             SchedulerEventLogState* logState,
             bool verbose)
{
    const std::string key = phase + "|" + std::to_string(experimentId) + "|" + reason;
    if (logState != nullptr)
        logState->currentSkipKeys.insert(key);
    if (!verbose &&
        logState != nullptr &&
        logState->previousSkipKeys.find(key) != logState->previousSkipKeys.end())
    {
        return;
    }

    std::cout << "SCHEDULER_SKIP_" << (phase == "train" ? "TRAIN" : phase == "infer" ? "INFER" : "ANALYZE")
              << ",experiment_id=" << experimentId
              << ",reason=" << reason
              << std::endl;
}

std::string PhaseSchedulingStatsKey(const PhaseSchedulingStats& stats)
{
    std::ostringstream key;
    key << stats.examined << "|"
        << stats.skipped << "|"
        << stats.launched << "|"
        << stats.freeSlots;
    return key.str();
}

void PrintPhaseSchedulingStats(const PhaseSchedulingStats& stats,
                               SchedulerEventLogState* logState,
                               bool verbose)
{
    const std::string key = PhaseSchedulingStatsKey(stats);
    if (!verbose &&
        logState != nullptr &&
        logState->previousPhaseKeys[stats.phase] == key)
    {
        return;
    }

    std::cout << "SCHEDULER_QUEUE_PHASE"
              << ",phase=" << stats.phase
              << ",examined=" << stats.examined
              << ",skipped=" << stats.skipped
              << ",launched=" << stats.launched
              << ",free_slots=" << stats.freeSlots
              << std::endl;
    if (logState != nullptr)
        logState->previousPhaseKeys[stats.phase] = key;
}

int FailInvalidSchedulerPhases(pqxx::work& w)
{
    pqxx::result rows = w.exec(
        "SELECT experiment_id,phase,status,"
        "active_scheduler_worker_attempt_id "
        "FROM experiment "
        "WHERE status IN ('pending', 'running') "
        "AND phase NOT IN ('train', 'infer', 'analyze', 'done') "
        "ORDER BY updated_at ASC, experiment_id ASC;");

    for (const auto& row : rows)
    {
        const long long experimentId = row[0].as<long long>();
        const std::string phase = row[1].as<std::string>();
        if (row[2].as<std::string>() == "running" ||
            !row[3].is_null())
        {
            std::cout << "EXPERIMENT_INVALID_PHASE_DEFERRED"
                      << ",experiment_id=" << experimentId
                      << ",phase=" << phase
                      << ",reason=exact_active_attempt_required"
                      << std::endl;
            continue;
        }
        pqxx::result failed = w.exec_params(
            "UPDATE experiment "
            "SET status = 'failed', "
            "exit_code = -1, "
            "error_message = $1, "
            "completed_at = now(), "
            "updated_at = now() "
            "WHERE experiment_id = $2 "
            "AND status='pending' "
            "AND active_scheduler_worker_attempt_id IS NULL "
            "RETURNING experiment_id;",
            "unknown_scheduler_phase:" + phase,
            experimentId);
        if (failed.size() != 1)
            continue;
        std::cout << "EXPERIMENT_FAILED"
                  << ",experiment_id=" << experimentId
                  << ",phase=" << phase
                  << ",reason=unknown_scheduler_phase"
                  << std::endl;
    }

    return rows.empty() ? 0 : 1;
}

void EnsureLogDir(const std::string& logDir)
{
    std::filesystem::create_directories(logDir);
}

std::string LogPathFor(const SchedulerOptions& options,
                              const ExperimentRow& experiment,
                              const std::string& phase)
{
    std::ostringstream oss;
    oss << options.schedulerLogDir
        << "/experiment_" << experiment.experimentId
        << "_" << EA::CanonicalSymbol::Normalize(experiment.symbol)
        << "_" << phase << ".log";
    return oss.str();
}

std::string BaseModelName(const ExperimentRow& experiment)
{
    std::ostringstream oss;
    oss << EA::CanonicalSymbol::Normalize(experiment.symbol)
        << "-experiment" << experiment.experimentId
        << "_h" << experiment.predictionHorizon
        << "_e" << experiment.targetEpochs;
    return oss.str();
}

struct DiscoveredManagedProcess
{
    int pid = -1;
    int processGroupId = -1;
    std::string executable;
    std::string command;
    std::string processStartIdentity;
};

std::optional<DiscoveredManagedProcess> DiscoverRunningProcessForExperiment(
    const ExperimentRow& experiment,
    const std::string& phase)
{
    FILE* pipe = ::popen("ps -axo pid=,pgid=,command=", "r");
    if (!pipe)
        return std::nullopt;

    const std::string id = std::to_string(experiment.experimentId);
    const std::regex experimentIdentity{
        "(^|[[:space:]])--scheduler-experiment-id(=|[[:space:]]+)" +
        id + "([[:space:]]|$)"};
    const std::regex phaseIdentity{
        phase == "train"
            ? "(^|[[:space:]])--train([[:space:]]|$)"
            : (phase == "infer"
                   ? "(^|[[:space:]])--infer([[:space:]]|$)"
                   : "(^|[[:space:]])--analyze-experiment(=|[[:space:]]+)" +
                         id + "([[:space:]]|$)")};
    char buffer[16384];
    std::optional<DiscoveredManagedProcess> found;
    while (std::fgets(buffer, sizeof(buffer), pipe) != nullptr)
    {
        std::istringstream line{buffer};
        DiscoveredManagedProcess process;
        if (!(line >> process.pid >> process.processGroupId))
            continue;
        std::getline(line, process.command);
        const size_t begin = process.command.find_first_not_of(" \t");
        if (begin != std::string::npos)
            process.command.erase(0, begin);
        const size_t executableEnd =
            process.command.find_first_of(" \t");
        process.executable =
            process.command.substr(0, executableEnd);
        const std::string& command = process.command;
        const std::string executableName =
            std::filesystem::path(process.executable).filename().string();
        if (executableName != "LSTM_Release" &&
            executableName != "LSTM")
            continue;
        if (!std::regex_search(command, phaseIdentity))
            continue;
        if (phase != "analyze" &&
            !std::regex_search(command, experimentIdentity))
            continue;
        if (process.pid <= 1 || process.processGroupId <= 1 ||
            command.find("--schedule-experiments") != std::string::npos)
        {
            continue;
        }
        const auto processStartIdentity =
            EA::GlobalExperimentControl::ReadProcessStartIdentity(process.pid);
        if (!processStartIdentity)
            continue;
        process.processStartIdentity = *processStartIdentity;
        found = std::move(process);
        break;
    }
    ::pclose(pipe);
    return found;
}

std::string ShellDisplayQuote(const std::string& value)
{
    if (value.find_first_of(" \t\n\"'\\$`") == std::string::npos)
        return value;
    std::string quoted = "'";
    for (char c : value)
    {
        if (c == '\'')
            quoted += "'\\''";
        else
            quoted.push_back(c);
    }
    quoted.push_back('\'');
    return quoted;
}

std::string CommandForDisplay(const std::vector<std::string>& argv)
{
    std::ostringstream oss;
    for (size_t i = 0; i < argv.size(); ++i)
    {
        if (i)
            oss << ' ';
        oss << ShellDisplayQuote(argv[i]);
    }
    return oss.str();
}

std::string CommandForProcessObservation(
    const std::vector<std::string>& argv)
{
    std::ostringstream command;
    for (size_t index = 0; index < argv.size(); ++index)
    {
        if (index != 0)
            command << ' ';
        command << argv[index];
    }
    return command.str();
}

void AddCliFlag(std::vector<std::string>& argv, const std::string& optionName)
{
    argv.push_back(optionName);
}

void AddCliOption(std::vector<std::string>& argv,
                         const std::string& optionName,
                         const std::string& value)
{
    if (value.empty())
        throw std::invalid_argument(optionName + " requires a non-empty value");
    argv.push_back(optionName + "=" + value);
}

void AddLstmProfileOptions(std::vector<std::string>& argv,
                           const SchedulerOptions& options)
{
    if (!options.lstmProfileHotspots)
        return;
    AddCliFlag(argv, "--lstm-profile-hotspots");
    if (options.lstmProfileOutputPath.has_value())
        AddCliOption(argv, "--lstm-profile-output", *options.lstmProfileOutputPath);
}

void AddCliPositional(std::vector<std::string>& argv, const std::string& value)
{
    if (value.empty())
        throw std::invalid_argument("positional argument must not be empty");
    argv.push_back(value);
}

void PrintSchedulerExec(const std::vector<std::string>& argv)
{
    std::cout << "SCHEDULER_EXEC: "
              << CommandForDisplay(argv)
              << std::endl;
}

class SchedulerChildLaunchError : public std::runtime_error
{
public:
    SchedulerChildLaunchError(int errorNumber, const std::string& message)
        : std::runtime_error(message), errorNumber_(errorNumber)
    {
    }

    int ErrorNumber() const { return errorNumber_; }

private:
    int errorNumber_ = 0;
};

int SchedulerChildLaunchErrorNumber(const std::exception& error)
{
    const auto* launchError = dynamic_cast<const SchedulerChildLaunchError*>(&error);
    return launchError != nullptr ? launchError->ErrorNumber() : EIO;
}

std::string RequireProcessStartIdentity(pid_t pid);

int CountGlobalWorkerCapacity(
    pqxx::work& transaction,
    const std::string& capacityClass)
{
    return transaction.exec_params(
        "SELECT count(*) FROM experiment_scheduler_worker_attempt "
        "WHERE capacity_class=$1 AND lifecycle_state IN "
        "('reserved','spawned','running','observed',"
        "'identity_ambiguous');",
        capacityClass).one_row()[0].as<int>();
}

std::string GenerateWorkerLaunchIdentity(
    const SchedulerOptions& options,
    const std::string& commandIdentity)
{
    return options.schedulerAuthority.schedulerInvocationId + ":worker:" +
           GenerateSchedulerInvocationNonce() + ":" +
           commandIdentity;
}

std::optional<ReservedWorkerAttempt>
ReserveExperimentWorkerAttempt(
    const SchedulerOptions& options,
    const ExperimentRow& experiment,
    const std::string& phase,
    const std::string& logPath,
    int maximumCapacity,
    bool cancellationOnly = false)
{
    pqxx::connection connection{LstmDbConnectionString()};
    pqxx::work transaction{connection};
    SetTransactionReadWrite(transaction);
    RequireAndRefreshSchedulerAuthority(transaction, options);
    if (!SchedulerLaunchAllowed(
            transaction,
            phase,
            false,
            cancellationOnly))
    {
        transaction.commit();
        return std::nullopt;
    }

    const int used =
        CountGlobalWorkerCapacity(transaction, phase);
    if (!SchedulerWorkerCapacityHasSlot(maximumCapacity, used))
    {
        transaction.commit();
        return std::nullopt;
    }

    pqxx::result lifecycle = transaction.exec_params(
        "SELECT status,phase,active_scheduler_worker_attempt_id,"
        "cancellation_request_id, cancel_after_checkpoint_epoch "
        "FROM experiment WHERE experiment_id=$1;",
        experiment.experimentId);
    if (lifecycle.size() != 1 ||
        lifecycle[0][0].as<std::string>() != "pending" ||
        lifecycle[0][1].as<std::string>() != phase ||
        !lifecycle[0][2].is_null())
    {
        transaction.commit();
        return std::nullopt;
    }
    if (cancellationOnly &&
        (lifecycle[0][3].is_null() ||
         lifecycle[0][4].is_null()))
    {
        transaction.commit();
        return std::nullopt;
    }

    ReservedWorkerAttempt attempt;
    attempt.launchAttemptIdentity =
        GenerateWorkerLaunchIdentity(
            options,
            "experiment:" +
                std::to_string(experiment.experimentId) + ":" +
                phase);
    attempt.experimentId = experiment.experimentId;
    attempt.workerKind = "experiment";
    attempt.phase = phase;
    attempt.capacityClass = phase;
    attempt.logPath = logPath;

    pqxx::result inserted = transaction.exec_params(
        "INSERT INTO experiment_scheduler_worker_attempt("
        "launch_attempt_identity,scheduler_invocation_id,"
        "scheduler_fencing_token,experiment_id,worker_kind,"
        "lifecycle_phase,capacity_class,ownership_origin,"
        "lifecycle_state,canonical_executable_path,"
        "command_identity,log_path) "
        "VALUES($1,$2,$3,$4,'experiment',$5,$5,"
        "'scheduler_launch','reserved',$6,$7,$8) "
        "RETURNING worker_attempt_id;",
        attempt.launchAttemptIdentity,
        options.schedulerAuthority.schedulerInvocationId,
        options.schedulerAuthority.fencingToken,
        experiment.experimentId,
        phase,
        options.selfPath,
        "experiment:" +
            std::to_string(experiment.experimentId) + ":" + phase,
        logPath);
    if (inserted.size() != 1)
        throw std::runtime_error(
            "worker_attempt_reservation_insert_failed");
    attempt.workerAttemptId =
        inserted[0][0].as<long long>();

    const std::string currentOperation =
        EA::ExperimentLifecycle::
            RequireCanonicalCurrentOperationForPhase(phase);
    const std::string logColumn =
        phase == "train"
            ? "train_log_path"
            : (phase == "infer"
                   ? "infer_log_path"
                   : "analysis_log_path");
    const std::string claimSql =
        std::string{
        "UPDATE experiment SET status='running',"
        "started_at=COALESCE(started_at,clock_timestamp()),"
        "worker_started_at=clock_timestamp(),worker_pid=NULL,"
        "worker_process_group_id=NULL,"
        "worker_process_start_identity=NULL,"
        "worker_executable=$1,current_operation=$2,"
        "active_scheduler_worker_attempt_id=$3,"} +
        logColumn + "=$4,updated_at=clock_timestamp() "
        "WHERE experiment_id=$5 AND status='pending' AND phase=$6 "
        "AND active_scheduler_worker_attempt_id IS NULL "
        "RETURNING experiment_id;";
    pqxx::result claimed = transaction.exec_params(
        claimSql,
        options.selfPath,
        currentOperation,
        attempt.workerAttemptId,
        logPath,
        experiment.experimentId,
        phase);
    if (claimed.size() != 1)
        throw std::runtime_error(
            "worker_attempt_lifecycle_claim_failed");
    transaction.commit();
    return attempt;
}

std::optional<ReservedWorkerAttempt>
ReserveCheckpointWorkerAttempt(
    const SchedulerOptions& options,
    const CheckpointEvalRow& eval,
    const std::string& logPath,
    int maximumCapacity)
{
    pqxx::connection connection{LstmDbConnectionString()};
    pqxx::work transaction{connection};
    SetTransactionReadWrite(transaction);
    RequireAndRefreshSchedulerAuthority(transaction, options);
    if (!SchedulerLaunchAllowed(
            transaction, "checkpoint_infer", true, false))
    {
        transaction.commit();
        return std::nullopt;
    }
    if (!SchedulerWorkerCapacityHasSlot(
            maximumCapacity,
            CountGlobalWorkerCapacity(transaction, "infer")))
    {
        transaction.commit();
        return std::nullopt;
    }

    pqxx::result lifecycle = transaction.exec_params(
        "SELECT status,phase,active_scheduler_worker_attempt_id "
        "FROM experiment_checkpoint_eval "
        "WHERE checkpoint_eval_id=$1;",
        eval.checkpointEvalId);
    if (lifecycle.size() != 1 ||
        lifecycle[0][0].as<std::string>() != "pending" ||
        lifecycle[0][1].as<std::string>() != "infer" ||
        !lifecycle[0][2].is_null())
    {
        transaction.commit();
        return std::nullopt;
    }

    ReservedWorkerAttempt attempt;
    attempt.launchAttemptIdentity =
        GenerateWorkerLaunchIdentity(
            options,
            "checkpoint_infer:" +
                std::to_string(eval.checkpointEvalId));
    attempt.experimentId = eval.experiment.experimentId;
    attempt.checkpointEvalId = eval.checkpointEvalId;
    attempt.workerKind = "checkpoint_infer";
    attempt.phase = "infer";
    attempt.capacityClass = "infer";
    attempt.logPath = logPath;
    pqxx::result inserted = transaction.exec_params(
        "INSERT INTO experiment_scheduler_worker_attempt("
        "launch_attempt_identity,scheduler_invocation_id,"
        "scheduler_fencing_token,experiment_id,checkpoint_eval_id,"
        "worker_kind,lifecycle_phase,capacity_class,"
        "ownership_origin,lifecycle_state,"
        "canonical_executable_path,command_identity,log_path) "
        "VALUES($1,$2,$3,$4,$5,'checkpoint_infer','infer','infer',"
        "'scheduler_launch','reserved',$6,$7,$8) "
        "RETURNING worker_attempt_id;",
        attempt.launchAttemptIdentity,
        options.schedulerAuthority.schedulerInvocationId,
        options.schedulerAuthority.fencingToken,
        eval.experiment.experimentId,
        eval.checkpointEvalId,
        options.selfPath,
        "checkpoint_infer:" +
            std::to_string(eval.checkpointEvalId),
        logPath);
    if (inserted.size() != 1)
        throw std::runtime_error(
            "checkpoint_worker_attempt_reservation_insert_failed");
    attempt.workerAttemptId =
        inserted[0][0].as<long long>();

    pqxx::result claimed = transaction.exec_params(
        "UPDATE experiment_checkpoint_eval SET "
        "status='running',phase='infer',worker_pid=NULL,"
        "worker_process_group_id=NULL,"
        "worker_process_start_identity=NULL,worker_executable=$1,"
        "worker_control_state='running',infer_log_path=$2,"
        "active_scheduler_worker_attempt_id=$3,"
        "started_at=COALESCE(started_at,clock_timestamp()),"
        "infer_started_at=COALESCE(infer_started_at,"
        "clock_timestamp()),updated_at=clock_timestamp(),"
        "error_message=NULL "
        "WHERE checkpoint_eval_id=$4 AND status='pending' "
        "AND phase='infer' "
        "AND active_scheduler_worker_attempt_id IS NULL "
        "RETURNING checkpoint_eval_id;",
        options.selfPath,
        logPath,
        attempt.workerAttemptId,
        eval.checkpointEvalId);
    if (claimed.size() != 1)
        throw std::runtime_error(
            "checkpoint_worker_attempt_lifecycle_claim_failed");
    transaction.commit();
    return attempt;
}

[[noreturn]] void ThrowSchedulerChildLaunchError(
    long long experimentId,
    const std::string& phase,
    const std::string& commandLine,
    int errorNumber,
    const std::string& context)
{
    std::cout << SchedulerChildLaunchFailureDiagnostic(
                     experimentId,
                     phase,
                     errorNumber,
                     commandLine)
              << std::endl;
    throw SchedulerChildLaunchError(
        errorNumber,
        context + ": " + std::strerror(errorNumber));
}

pid_t LaunchChildProcess(const std::vector<std::string>& argv,
                         const std::string& logPath,
                         long long experimentId,
                         const std::string& phase,
                         const std::optional<long long>& expectedModelId = std::nullopt,
                         const std::optional<long long>& checkpointEvalId = std::nullopt)
{
    if (argv.empty())
        ThrowSchedulerChildLaunchError(
            experimentId, phase, "", EINVAL, "empty child argv");

    // proc_pidpath supplies the executable identity while `ps ... command=`
    // supplies this argument identity. Persist the observation form, not a
    // shell-escaped display command: the executable path may contain spaces.
    const std::string commandLine =
        CommandForProcessObservation(argv);
    const double launchStartedEpoch =
        std::chrono::duration<double>(
            std::chrono::system_clock::now().time_since_epoch()).count();

    const int fd = ::open(logPath.c_str(), O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0)
    {
        const int openError = errno;
        ThrowSchedulerChildLaunchError(
            experimentId,
            phase,
            commandLine,
            openError,
            "failed to open log file '" + logPath + "'");
    }

    std::vector<char*> childArgv;
    childArgv.reserve(argv.size() + 1);
    for (const auto& arg : argv)
        childArgv.push_back(const_cast<char*>(arg.c_str()));
    childArgv.push_back(nullptr);
    if (argv[0].empty() || argv[0].front() != '/' ||
        ::access(argv[0].c_str(), X_OK) != 0)
    {
        ::close(fd);
        ThrowSchedulerChildLaunchError(
            experimentId,
            phase,
            commandLine,
            EINVAL,
            "canonical absolute executable path required");
    }
    const char* const phaseData = phase.data();
    const size_t phaseLength = phase.size();

    pid_t pid = ::fork();
    if (pid < 0)
    {
        const int forkError = errno;
        ::close(fd);
        ThrowSchedulerChildLaunchError(
            experimentId, phase, commandLine, forkError, "fork failed");
    }

    if (pid == 0)
    {
        if (::setsid() < 0)
        {
            const int childErrno = errno;
            ::dup2(fd, STDOUT_FILENO);
            ::dup2(fd, STDERR_FILENO);
            ::close(fd);
            WriteSchedulerChildExecFailureDiagnostic(
                STDERR_FILENO, experimentId, phaseData, phaseLength, childErrno);
            _exit(127);
        }

        ::signal(SIGHUP, SIG_IGN);
        ::dup2(fd, STDOUT_FILENO);
        ::dup2(fd, STDERR_FILENO);
        ::close(fd);

        ::execv(argv[0].c_str(), childArgv.data());
        const int childErrno = errno;
        WriteSchedulerChildExecFailureDiagnostic(
            STDERR_FILENO, experimentId, phaseData, phaseLength, childErrno);
        _exit(127);
    }

    ::close(fd);
    SchedulerOwnedChild child;
    child.pid = pid;
    child.experimentId = experimentId;
    child.phase = phase;
    child.operation = phase;
    child.commandLine = commandLine;
    child.expectedModelId = expectedModelId;
    child.checkpointEvalId = checkpointEvalId;
    child.logPath = logPath;
    child.launchedAt = EA::RunMetadata::CurrentUtcTimestamp();
    child.launchedEpoch = launchStartedEpoch;
    gSchedulerOwnedChildren.emplace(pid, std::move(child));
    std::cout << "SCHEDULER_CHILD_LAUNCHED"
              << ",experiment_id=" << experimentId
              << ",worker_pid=" << pid
              << ",pid=" << pid
              << ",phase=" << phase
              << ",operation=" << phase
              << ",command_line=" << commandLine
              << ",log_path=" << logPath
              << std::endl;
    return pid;
}

void MarkReservedWorkerAttemptLaunchFailed(
    const SchedulerOptions& options,
    const ReservedWorkerAttempt& attempt,
    const std::string& diagnostic,
    int exitCode = 127)
{
    try
    {
        pqxx::connection connection{LstmDbConnectionString()};
        pqxx::work transaction{connection};
        SetTransactionReadWrite(transaction);
        RequireAndRefreshSchedulerAuthority(transaction, options);
        pqxx::result terminal = transaction.exec_params(
            "UPDATE experiment_scheduler_worker_attempt a SET "
            "lifecycle_state='launch_failed',"
            "completed_at=clock_timestamp(),exit_code=$1,"
            "reconciliation_result='launch_failed',diagnostic=$2 "
            "WHERE a.worker_attempt_id=$3 "
            "AND a.scheduler_invocation_id=$4 "
            "AND a.scheduler_fencing_token=$5 "
            "AND a.lifecycle_state IN ('reserved','spawned') "
            "AND EXISTS ("
            " SELECT 1 FROM experiment e "
            " WHERE $6::bigint IS NULL "
            " AND e.experiment_id=$7 "
            " AND e.status='running' AND e.phase=$8 "
            " AND e.active_scheduler_worker_attempt_id="
            "a.worker_attempt_id "
            " UNION ALL "
            " SELECT 1 FROM experiment_checkpoint_eval ce "
            " WHERE $6::bigint IS NOT NULL "
            " AND ce.checkpoint_eval_id=$6 "
            " AND ce.status='running' AND ce.phase='infer' "
            " AND ce.active_scheduler_worker_attempt_id="
            "a.worker_attempt_id"
            ") RETURNING a.worker_attempt_id;",
            exitCode,
            diagnostic,
            attempt.workerAttemptId,
            options.schedulerAuthority.schedulerInvocationId,
            options.schedulerAuthority.fencingToken,
            attempt.checkpointEvalId,
            attempt.experimentId,
            attempt.phase);
        EA::SchedulerOwnership::RequireAffectedExactlyOne(
            terminal,
            "terminalize_exact_launch_failure_attempt");
        pqxx::result lifecycle;
        if (attempt.checkpointEvalId)
        {
            lifecycle = transaction.exec_params(
                "UPDATE experiment_checkpoint_eval SET "
                "status='failed',worker_pid=NULL,"
                "worker_process_group_id=NULL,"
                "completed_at=clock_timestamp(),error_message=$1,"
                "updated_at=clock_timestamp(),"
                "active_scheduler_worker_attempt_id=NULL "
                "WHERE checkpoint_eval_id=$2 "
                "AND active_scheduler_worker_attempt_id=$3 "
                "AND status='running' AND phase='infer' "
                "RETURNING checkpoint_eval_id;",
                diagnostic,
                *attempt.checkpointEvalId,
                attempt.workerAttemptId);
        }
        else
        {
            lifecycle = transaction.exec_params(
                "UPDATE experiment SET status='failed',"
                "worker_pid=NULL,worker_process_group_id=NULL,"
                "completed_at=clock_timestamp(),exit_code=$1,"
                "error_message=$2,updated_at=clock_timestamp(),"
                "active_scheduler_worker_attempt_id=NULL "
                "WHERE experiment_id=$3 "
                "AND active_scheduler_worker_attempt_id=$4 "
                "AND status='running' AND phase=$5 "
                "RETURNING experiment_id;",
                exitCode,
                diagnostic,
                attempt.experimentId,
                attempt.workerAttemptId,
                attempt.phase);
        }
        EA::SchedulerOwnership::RequireAffectedExactlyOne(
            lifecycle,
            "clear_exact_launch_failure_binding");
        transaction.commit();
    }
    catch (const std::exception& error)
    {
        std::cerr << "SCHEDULER_LAUNCH_FAILURE_PERSIST_FAILED"
                  << ",worker_attempt_id="
                  << attempt.workerAttemptId
                  << ",error=" << error.what()
                  << std::endl;
    }
}

void PersistSpawnedWorkerAttempt(
    const SchedulerOptions& options,
    const ReservedWorkerAttempt& attempt,
    pid_t pid,
    const std::string& processStartIdentity,
    const std::string& commandLine,
    bool requireSchedulerAuthority = true)
{
    pqxx::connection connection{LstmDbConnectionString()};
    pqxx::work transaction{connection};
    SetTransactionReadWrite(transaction);
    if (requireSchedulerAuthority)
        RequireAndRefreshSchedulerAuthority(transaction, options);
    pqxx::result spawned = transaction.exec_params(
        "UPDATE experiment_scheduler_worker_attempt SET "
        "lifecycle_state='spawned',worker_pid=$1,"
        "worker_process_group_id=$1,"
        "worker_process_start_identity=$2,"
        "canonical_executable_path=$3,command_line=$4,"
        "spawned_at=COALESCE(spawned_at,clock_timestamp()),"
        "last_observed_at=clock_timestamp() "
        "WHERE worker_attempt_id=$5 AND scheduler_invocation_id=$6 "
        "AND scheduler_fencing_token=$7 "
        "AND (lifecycle_state='reserved' OR ("
        " lifecycle_state='spawned' AND worker_pid=$1 "
        " AND worker_process_group_id=$1 "
        " AND worker_process_start_identity=$2 "
        " AND canonical_executable_path=$3 "
        " AND command_line=$4)) "
        "RETURNING worker_attempt_id;",
        static_cast<int>(pid),
        processStartIdentity,
        options.selfPath,
        commandLine,
        attempt.workerAttemptId,
        options.schedulerAuthority.schedulerInvocationId,
        options.schedulerAuthority.fencingToken);
    if (spawned.size() != 1)
    {
        if (requireSchedulerAuthority)
            throw SchedulerAuthorityLost(
                "worker_attempt_spawn_persistence_fence_rejected");
        throw std::runtime_error(
            "child_spawn_evidence_persistence_fence_rejected");
    }

    pqxx::result lifecycle;
    if (attempt.checkpointEvalId)
    {
        lifecycle = transaction.exec_params(
            "UPDATE experiment_checkpoint_eval SET "
            "worker_pid=$1,worker_process_group_id=$1,"
            "worker_process_start_identity=$2,worker_executable=$3,"
            "worker_command_line=$4,updated_at=clock_timestamp() "
            "WHERE checkpoint_eval_id=$5 AND status='running' "
            "AND phase='infer' "
            "AND active_scheduler_worker_attempt_id=$6 "
            "RETURNING checkpoint_eval_id;",
            static_cast<int>(pid),
            processStartIdentity,
            options.selfPath,
            commandLine,
            *attempt.checkpointEvalId,
            attempt.workerAttemptId);
    }
    else
    {
        lifecycle = transaction.exec_params(
            "UPDATE experiment SET worker_pid=$1,"
            "worker_process_group_id=$1,"
            "worker_process_start_identity=$2,worker_executable=$3,"
            "worker_command_line=$4,updated_at=clock_timestamp() "
            "WHERE experiment_id=$5 AND status='running' "
            "AND phase=$6 "
            "AND active_scheduler_worker_attempt_id=$7 "
            "RETURNING experiment_id;",
            static_cast<int>(pid),
            processStartIdentity,
            options.selfPath,
            commandLine,
            attempt.experimentId,
            attempt.phase,
            attempt.workerAttemptId);
    }
    if (lifecycle.size() != 1)
        throw std::runtime_error(
            "worker_attempt_spawn_lifecycle_predicate_rejected");
    transaction.commit();
}

pid_t LaunchReservedChildProcess(
    const SchedulerOptions& options,
    const ReservedWorkerAttempt& attempt,
    std::vector<std::string> argv,
    const std::optional<long long>& expectedModelId = std::nullopt)
{
    if (argv.empty() || argv.front() != options.selfPath ||
        argv.front().empty() || argv.front().front() != '/')
    {
        MarkReservedWorkerAttemptLaunchFailed(
            options,
            attempt,
            "canonical_executable_path_required",
            127);
        ThrowSchedulerChildLaunchError(
            attempt.experimentId,
            attempt.phase,
            CommandForDisplay(argv),
            EINVAL,
            "canonical executable path required");
    }
    AddCliOption(
        argv,
        "--scheduler-worker-attempt-id",
        std::to_string(attempt.workerAttemptId));
    const std::string commandLine =
        CommandForProcessObservation(argv);

    const int fd = ::open(
        attempt.logPath.c_str(),
        O_WRONLY | O_CREAT | O_TRUNC,
        0644);
    if (fd < 0)
    {
        const int errorNumber = errno;
        MarkReservedWorkerAttemptLaunchFailed(
            options,
            attempt,
            SchedulerLaunchFailureError(errorNumber),
            127);
        ThrowSchedulerChildLaunchError(
            attempt.experimentId,
            attempt.phase,
            commandLine,
            errorNumber,
            "failed to open scheduler child log");
    }

    int gate[2] = {-1, -1};
    if (::pipe(gate) != 0)
    {
        const int errorNumber = errno;
        ::close(fd);
        MarkReservedWorkerAttemptLaunchFailed(
            options,
            attempt,
            SchedulerLaunchFailureError(errorNumber),
            127);
        ThrowSchedulerChildLaunchError(
            attempt.experimentId,
            attempt.phase,
            commandLine,
            errorNumber,
            "failed to create scheduler child launch gate");
    }
    (void)::fcntl(gate[0], F_SETFD, FD_CLOEXEC);
    (void)::fcntl(gate[1], F_SETFD, FD_CLOEXEC);

    std::vector<char*> childArgv;
    childArgv.reserve(argv.size() + 1);
    for (const auto& argument : argv)
        childArgv.push_back(const_cast<char*>(argument.c_str()));
    childArgv.push_back(nullptr);
    const char* phaseData = attempt.phase.data();
    const size_t phaseLength = attempt.phase.size();

    const pid_t pid = ::fork();
    if (pid < 0)
    {
        const int errorNumber = errno;
        ::close(gate[0]);
        ::close(gate[1]);
        ::close(fd);
        MarkReservedWorkerAttemptLaunchFailed(
            options,
            attempt,
            SchedulerLaunchFailureError(errorNumber),
            127);
        ThrowSchedulerChildLaunchError(
            attempt.experimentId,
            attempt.phase,
            commandLine,
            errorNumber,
            "fork failed");
    }

    if (pid == 0)
    {
        ::close(gate[1]);
        if (::setsid() < 0)
        {
            const int childError = errno;
            ::dup2(fd, STDOUT_FILENO);
            ::dup2(fd, STDERR_FILENO);
            ::close(fd);
            WriteSchedulerChildExecFailureDiagnostic(
                STDERR_FILENO,
                attempt.experimentId,
                phaseData,
                phaseLength,
                childError);
            _exit(127);
        }
        ::signal(SIGHUP, SIG_IGN);
        ::dup2(fd, STDOUT_FILENO);
        ::dup2(fd, STDERR_FILENO);
        ::close(fd);

        try
        {
            const std::string childProcessStartIdentity =
                RequireProcessStartIdentity(::getpid());
            // The child may persist only the exact already-reserved attempt.
            // It cannot refresh the scheduler lease or claim/launch work.
            PersistSpawnedWorkerAttempt(
                options,
                attempt,
                ::getpid(),
                childProcessStartIdentity,
                commandLine,
                false);
        }
        catch (...)
        {
            WriteSchedulerChildExecFailureDiagnostic(
                STDERR_FILENO,
                attempt.experimentId,
                phaseData,
                phaseLength,
                EIO);
            _exit(126);
        }

        char permission = '\0';
        const ssize_t readResult =
            ::read(gate[0], &permission, 1);
        ::close(gate[0]);
        if (readResult != 1 || permission != 'G')
        {
            WriteSchedulerChildExecFailureDiagnostic(
                STDERR_FILENO,
                attempt.experimentId,
                phaseData,
                phaseLength,
                ECANCELED);
            _exit(126);
        }

        ::signal(SIGPIPE, SIG_DFL);
        ::execv(argv.front().c_str(), childArgv.data());
        const int childError = errno;
        WriteSchedulerChildExecFailureDiagnostic(
            STDERR_FILENO,
            attempt.experimentId,
            phaseData,
            phaseLength,
            childError);
        _exit(127);
    }

    ::close(gate[0]);
    ::close(fd);
    if (SchedulerAuthorityTestFailpointEnabled(
            "scheduler_parent_crash_after_child_registration"))
    {
        bool childRegistered = false;
        for (int observation = 0; observation < 500; ++observation)
        {
            pqxx::connection testConnection{
                LstmDbConnectionString()};
            pqxx::read_transaction testTransaction{
                testConnection};
            const pqxx::result registered =
                testTransaction.exec_params(
                    "SELECT 1 FROM "
                    "experiment_scheduler_worker_attempt "
                    "WHERE worker_attempt_id=$1 "
                    "AND lifecycle_state='spawned' "
                    "AND worker_pid=$2 "
                    "AND worker_process_group_id=$2 "
                    "AND worker_process_start_identity IS NOT NULL "
                    "AND canonical_executable_path=$3 "
                    "AND command_line=$4;",
                    attempt.workerAttemptId,
                    static_cast<int>(pid),
                    options.selfPath,
                    commandLine);
            if (registered.size() == 1)
            {
                childRegistered = true;
                break;
            }
            ::usleep(10000);
        }
        if (!childRegistered)
            throw std::runtime_error(
                "test_child_self_registration_not_observed");
        std::cout
            << "SCHEDULER_TEST_PARENT_CRASH_AFTER_CHILD_REGISTRATION"
            << ",worker_attempt_id=" << attempt.workerAttemptId
            << ",worker_pid=" << pid
            << std::endl;
        std::cout.flush();
        std::cerr.flush();
        ::_exit(87);
    }
    try
    {
        pid_t processGroupId = -1;
        for (int attemptNumber = 0;
             attemptNumber < 1000;
             ++attemptNumber)
        {
            processGroupId = ::getpgid(pid);
            if (processGroupId == pid)
                break;
            if (processGroupId < 0 && errno == ESRCH)
                break;
            ::usleep(1000);
        }
        if (processGroupId < 0 || processGroupId != pid)
            throw std::runtime_error(
                "scheduler_child_process_group_identity_mismatch");
        const std::string processStartIdentity =
            RequireProcessStartIdentity(pid);
        PersistSpawnedWorkerAttempt(
            options,
            attempt,
            pid,
            processStartIdentity,
            commandLine);
        const char permission = 'G';
        if (::write(gate[1], &permission, 1) != 1)
            throw std::runtime_error(
                "scheduler_child_launch_gate_write_failed");
        ::close(gate[1]);
    }
    catch (const std::exception& error)
    {
        ::close(gate[1]);
        (void)::waitpid(pid, nullptr, 0);
        MarkReservedWorkerAttemptLaunchFailed(
            options,
            attempt,
            std::string{"spawn_persistence_failed:"} + error.what(),
            126);
        throw;
    }

    SchedulerOwnedChild child;
    child.pid = pid;
    child.workerAttemptId = attempt.workerAttemptId;
    child.experimentId = attempt.experimentId;
    child.phase =
        attempt.workerKind == "checkpoint_infer"
            ? "checkpoint_infer"
            : attempt.phase;
    child.operation = attempt.phase;
    child.commandLine = commandLine;
    child.expectedModelId = expectedModelId;
    child.checkpointEvalId = attempt.checkpointEvalId;
    child.logPath = attempt.logPath;
    child.launchedAt = EA::RunMetadata::CurrentUtcTimestamp();
    child.launchedEpoch =
        std::chrono::duration<double>(
            std::chrono::system_clock::now().time_since_epoch())
            .count();
    gSchedulerOwnedChildren.emplace(pid, std::move(child));
    std::cout << "SCHEDULER_CHILD_LAUNCHED"
              << ",worker_attempt_id=" << attempt.workerAttemptId
              << ",launch_attempt_identity="
              << attempt.launchAttemptIdentity
              << ",experiment_id=" << attempt.experimentId
              << ",worker_pid=" << pid
              << ",phase=" << attempt.phase
              << ",worker_kind=" << attempt.workerKind
              << ",command_line=" << commandLine
              << ",log_path=" << attempt.logPath
              << std::endl;
    return pid;
}

int WaitForChildProcess(pid_t pid)
{
    if (pid <= 0)
        return 1;

    int status = 0;
    if (::waitpid(pid, &status, 0) < 0)
    {
        return 1;
    }

    if (WIFEXITED(status))
        return WEXITSTATUS(status);
    else if (WIFSIGNALED(status))
        return 128 + WTERMSIG(status);
    return 1;
}

[[maybe_unused]] ChildResult RunChild(const std::vector<std::string>& argv, const std::string& logPath)
{
    ChildResult result;
    const pid_t pid = LaunchChildProcess(argv, logPath, -1, "child");
    result.launched = true;
    result.exitCode = WaitForChildProcess(pid);
    gSchedulerOwnedChildren.erase(pid);
    return result;
}

std::vector<std::string> BuildTrainCommand(const SchedulerOptions& options,
                                                  const ExperimentRow& experiment)
{
    // ResolvePersisted already rejected unknown identities. Re-canonicalize
    // here so only an exact supported objective can reach a training child.
    (void)EA::TrainingObjective::ParseSupportedCanonicalText(
        EA::TrainingObjective::CanonicalText(
            experiment.trainingObjective));
    std::vector<std::string> argv;
    argv.push_back(options.selfPath);
    AddCliFlag(argv, "--train");
    AddCliOption(argv, "--log-level", "summary");
    AddCliOption(argv, "--checkpoint-every", std::to_string(experiment.checkpointInterval));
    AddCliOption(argv, "--new-model-name", BaseModelName(experiment));
    AddCliOption(argv, "--donchian20-mode",
                 Donchian20ModeText(experiment.donchian20Mode));
    AddCliOption(argv, "--feature-warmup-scope",
                 EA::FeatureWarmupScopeText(experiment.featureWarmupScope));
    AddCliOption(argv, "--donchian-lookback",
                 std::to_string(experiment.donchianLookback));
    AddCliOption(argv, "--scheduler-experiment-id", std::to_string(experiment.experimentId));
    AddCliOption(
        argv,
        "--training-objective",
        experiment.trainingObjective.objectiveIdentifier);
    AddLstmProfileOptions(argv, options);

    const std::optional<long long> resumeFrom =
        experiment.resumeModelId.has_value() ? experiment.resumeModelId : experiment.lastModelId;
    if (resumeFrom.has_value())
    {
        AddCliOption(argv, "--resume-model-id", std::to_string(*resumeFrom));
        if (experiment.resumeExpandInputWidth)
            AddCliFlag(argv, "--resume-expand-input-width");
        AddCliOption(argv, "--target-epochs", std::to_string(experiment.targetEpochs));
        return argv;
    }

    AddCliOption(argv, "--symbol", experiment.symbol);
    AddCliOption(argv, "--prediction-horizon", std::to_string(experiment.predictionHorizon));
    AddCliOption(argv, "--threshold", FormatDouble(experiment.cNextThreshold));
    AddCliOption(argv, "--epochs", std::to_string(experiment.targetEpochs));
    if (experiment.coreLrMult.has_value())
        AddCliOption(argv, "--core-lr-mult", FormatDouble(*experiment.coreLrMult));
    if (experiment.headLrMult.has_value())
        AddCliOption(argv, "--head-weight-lr-mult", FormatDouble(*experiment.headLrMult));
    AddCliPositional(argv, experiment.trainStart.substr(0, 10));
    AddCliPositional(argv, experiment.trainEnd.substr(0, 10));
    return argv;
}

std::vector<std::string> BuildInferCommand(const SchedulerOptions& options,
                                                  const ExperimentRow& experiment)
{
    if (!experiment.lastModelId.has_value())
        throw std::runtime_error("infer phase has no last_model_id");
    if (!experiment.inferStart.has_value() || !experiment.inferEnd.has_value())
        throw std::runtime_error("infer phase has no infer date range");

    std::vector<std::string> argv;
    argv.push_back(options.selfPath);
    AddCliFlag(argv, "--infer");
    AddCliOption(argv, "--model", std::to_string(*experiment.lastModelId));
    AddCliOption(argv, "--scheduler-experiment-id", std::to_string(experiment.experimentId));
    AddCliOption(argv, "--donchian20-mode",
                 Donchian20ModeText(experiment.donchian20Mode));
    AddCliOption(argv, "--feature-warmup-scope",
                 EA::FeatureWarmupScopeText(experiment.featureWarmupScope));
    AddCliOption(argv, "--donchian-lookback",
                 std::to_string(experiment.donchianLookback));
    AddCliOption(argv, "--log-level", "summary");
    AddLstmProfileOptions(argv, options);
    AddCliPositional(argv, experiment.inferStart->substr(0, 10));
    AddCliPositional(argv, experiment.inferEnd->substr(0, 10));
    return argv;
}

std::vector<std::string> BuildAnalyzeCommand(const SchedulerOptions& options,
                                                    const ExperimentRow& experiment)
{
    std::vector<std::string> argv;
    argv.push_back(options.selfPath);
    AddCliOption(argv, "--analyze-experiment", std::to_string(experiment.experimentId));
    if (options.autoGenerateReports)
        AddCliFlag(argv, "--auto-generate-reports");
    if (options.experimentReportDir != "experiment_reports")
        AddCliOption(argv, "--experiment-report-dir", options.experimentReportDir);
    return argv;
}

std::string CheckpointEvalLogPathFor(const SchedulerOptions& options,
                                     const CheckpointEvalRow& eval,
                                     const std::string& phase)
{
    std::filesystem::path dir{options.schedulerLogDir};
    std::ostringstream name;
    name << "checkpoint_eval_"
         << eval.experiment.experimentId
         << "_epoch" << eval.checkpointEpoch
         << "_model" << eval.checkpointModelId
         << "_" << phase << ".log";
    return (dir / name.str()).string();
}

std::vector<std::string> BuildCheckpointEvalInferCommand(const SchedulerOptions& options,
                                                         const CheckpointEvalRow& eval)
{
    if (!eval.experiment.inferStart.has_value() || !eval.experiment.inferEnd.has_value())
        throw std::runtime_error("checkpoint eval infer has no infer date range");

    std::vector<std::string> argv;
    argv.push_back(options.selfPath);
    AddCliFlag(argv, "--infer");
    AddCliOption(argv, "--model", std::to_string(eval.checkpointModelId));
    AddCliOption(argv, "--scheduler-checkpoint-eval-id", std::to_string(eval.checkpointEvalId));
    AddCliOption(argv, "--donchian20-mode",
                 Donchian20ModeText(eval.experiment.donchian20Mode));
    AddCliOption(argv, "--feature-warmup-scope",
                 EA::FeatureWarmupScopeText(eval.experiment.featureWarmupScope));
    AddCliOption(argv, "--donchian-lookback",
                 std::to_string(eval.experiment.donchianLookback));
    AddCliOption(argv, "--log-level", "summary");
    AddLstmProfileOptions(argv, options);
    AddCliPositional(argv, eval.experiment.inferStart->substr(0, 10));
    AddCliPositional(argv, eval.experiment.inferEnd->substr(0, 10));
    return argv;
}

bool CheckpointEvalTableExists(pqxx::work& w)
{
    return TableExists(w, "experiment_checkpoint_eval");
}

void EnqueueCheckpointEvalRows(pqxx::work& w)
{
    const bool hasCheckpointInferEnabled = ColumnExists(w, "experiment", "checkpoint_infer_enabled");
    const bool hasOpportunisticCheckpointInfer = ColumnExists(w, "experiment", "opportunistic_checkpoint_infer");
    if (!CheckpointEvalTableExists(w) ||
        (!hasCheckpointInferEnabled && !hasOpportunisticCheckpointInfer) ||
        !ColumnExists(w, "model", "experiment_id"))
    {
        return;
    }
    const bool hasParentExperimentId = ColumnExists(w, "experiment_checkpoint_eval", "parent_experiment_id");
    const bool hasSymbol = ColumnExists(w, "experiment_checkpoint_eval", "symbol");
    const bool hasPredictionHorizon = ColumnExists(w, "experiment_checkpoint_eval", "prediction_horizon");

    std::ostringstream candidateSql;
    candidateSql
        << "WITH train_meta AS ("
        << "  SELECT model_id, MAX(round(value)::int) AS completed_epoch "
        << "  FROM matrix "
        << "  WHERE param_name = 'train_config_meta' AND row_idx = 0 AND col_idx = 10 "
        << "  GROUP BY model_id"
        << ") "
        << "SELECT e.experiment_id, tm.completed_epoch, m.model_id, "
        << "       COALESCE(e.checkpoint_infer_interval, NULLIF(e.checkpoint_interval, 0)), "
        << "       e.symbol, e.prediction_horizon "
        << "FROM experiment e "
        << "JOIN model m ON m.experiment_id = e.experiment_id "
        << "JOIN train_meta tm ON tm.model_id = m.model_id "
        << "WHERE ";
    if (hasCheckpointInferEnabled && hasOpportunisticCheckpointInfer)
        candidateSql << "(e.checkpoint_infer_enabled = true OR e.opportunistic_checkpoint_infer = true) ";
    else if (hasCheckpointInferEnabled)
        candidateSql << "e.checkpoint_infer_enabled = true ";
    else
        candidateSql << "e.opportunistic_checkpoint_infer = true ";
    candidateSql
        << "AND e.phase = 'train' "
        << "AND e.status IN ('pending', 'running', 'paused') "
        << "AND COALESCE(m.comment, '') ILIKE '%periodic training checkpoint%' "
        << "AND (e.checkpoint_infer_min_epoch IS NULL OR tm.completed_epoch >= e.checkpoint_infer_min_epoch) "
        << "ORDER BY e.experiment_id ASC, tm.completed_epoch ASC, m.model_id ASC;";

    pqxx::result candidates = w.exec(candidateSql.str());

    for (const auto& row : candidates)
    {
        const long long experimentId = row[0].as<long long>();
        const int epoch = row[1].as<int>();
        const long long modelId = row[2].as<long long>();
        const std::string symbol = row[4].as<std::string>();
        const int horizon = row[5].as<int>();
        const std::optional<int> interval =
            row[3].is_null() ? std::optional<int>{} : std::optional<int>{row[3].as<int>()};
        if (interval.has_value() && *interval > 0 && epoch % *interval != 0)
        {
            std::cout << "CHECKPOINT_EVAL_SKIPPED"
                      << " experiment_id=" << experimentId
                      << " epoch=" << epoch
                      << " reason=interval_mismatch"
                      << std::endl;
            continue;
        }

        std::ostringstream insertSql;
        insertSql << "INSERT INTO experiment_checkpoint_eval (experiment_id";
        if (hasParentExperimentId)
            insertSql << ", parent_experiment_id";
        insertSql << ", checkpoint_epoch, checkpoint_model_id";
        if (hasSymbol)
            insertSql << ", symbol";
        if (hasPredictionHorizon)
            insertSql << ", prediction_horizon";
        insertSql << ") VALUES ($1";
        int param = 2;
        if (hasParentExperimentId)
            insertSql << ", $" << param++;
        insertSql << ", $" << param++ << ", $" << param++;
        if (hasSymbol)
            insertSql << ", $" << param++;
        if (hasPredictionHorizon)
            insertSql << ", $" << param++;
        insertSql << ") ON CONFLICT ";
        if (hasParentExperimentId)
            insertSql << "(parent_experiment_id, checkpoint_model_id, checkpoint_epoch) ";
        else
            insertSql << "(experiment_id, checkpoint_epoch, checkpoint_model_id) ";
        insertSql << "DO NOTHING RETURNING checkpoint_eval_id;";

        pqxx::result inserted;
        if (hasParentExperimentId && hasSymbol && hasPredictionHorizon)
            inserted = w.exec_params(insertSql.str(), experimentId, experimentId, epoch, modelId, symbol, horizon);
        else if (hasParentExperimentId && hasSymbol)
            inserted = w.exec_params(insertSql.str(), experimentId, experimentId, epoch, modelId, symbol);
        else if (hasParentExperimentId && hasPredictionHorizon)
            inserted = w.exec_params(insertSql.str(), experimentId, experimentId, epoch, modelId, horizon);
        else if (hasParentExperimentId)
            inserted = w.exec_params(insertSql.str(), experimentId, experimentId, epoch, modelId);
        else if (hasSymbol && hasPredictionHorizon)
            inserted = w.exec_params(insertSql.str(), experimentId, epoch, modelId, symbol, horizon);
        else if (hasSymbol)
            inserted = w.exec_params(insertSql.str(), experimentId, epoch, modelId, symbol);
        else if (hasPredictionHorizon)
            inserted = w.exec_params(insertSql.str(), experimentId, epoch, modelId, horizon);
        else
            inserted = w.exec_params(insertSql.str(), experimentId, epoch, modelId);
        if (!inserted.empty())
        {
            std::cout << "CHECKPOINT_EVAL_ENQUEUED"
                      << " experiment_id=" << experimentId
                      << " epoch=" << epoch
                      << " model_id=" << modelId
                      << std::endl;
        }
    }
}

CheckpointEvalRow RowToCheckpointEval(const pqxx::row& row)
{
    CheckpointEvalRow eval;
    eval.checkpointEvalId = row[0].as<long long>();
    eval.checkpointEpoch = row[1].as<int>();
    eval.checkpointModelId = row[2].as<long long>();
    eval.status = row[3].as<std::string>();
    eval.phase = row[4].as<std::string>();
    eval.workerPid = row[5].is_null() ? std::optional<int>{} : std::optional<int>{row[5].as<int>()};
    eval.inferLogPath = OptionalStringCell(row, 6);
    eval.analysisLogPath = OptionalStringCell(row, 7);
    eval.experiment.experimentId = row[8].as<long long>();
    eval.experiment.symbol = EA::CanonicalSymbol::Normalize(row[9].as<std::string>());
    eval.experiment.predictionHorizon = row[10].as<int>();
    eval.experiment.cNextThreshold = row[11].as<double>();
    eval.experiment.coreLrMult = OptionalDoubleCell(row, 12);
    eval.experiment.headLrMult = OptionalDoubleCell(row, 13);
    eval.experiment.targetEpochs = row[14].as<int>();
    eval.experiment.checkpointInterval = row[15].as<int>();
    eval.experiment.trainStart = row[16].as<std::string>();
    eval.experiment.trainEnd = row[17].as<std::string>();
    eval.experiment.inferStart = OptionalStringCell(row, 18);
    eval.experiment.inferEnd = OptionalStringCell(row, 19);
    eval.experiment.lastModelId = eval.checkpointModelId;
    eval.experiment.resumeModelId = OptionalLongLongCell(row, 20);
    eval.experiment.trainLogPath = OptionalStringCell(row, 21);
    eval.inferStartedEpoch = row[22].is_null() ? 0.0 : row[22].as<double>();
    eval.experiment.inferLogPath = eval.inferLogPath;
    eval.experiment.analysisLogPath = eval.analysisLogPath;
    if (row.size() > 23 && !row[23].is_null())
        eval.cancellationRequestId = row[23].as<long long>();
    return eval;
}

std::vector<CheckpointEvalRow> LoadCheckpointEvalRows(pqxx::work& w,
                                                      const std::string& status,
                                                      const std::string& phase)
{
    if (!CheckpointEvalTableExists(w))
        return {};
    pqxx::result rows = w.exec_params(
        "SELECT ce.checkpoint_eval_id, ce.checkpoint_epoch, ce.checkpoint_model_id, "
        "ce.status, ce.phase, ce.worker_pid, ce.infer_log_path, ce.analysis_log_path, "
        "e.experiment_id, e.symbol, e.prediction_horizon, e.c_next_threshold, "
        "e.core_lr_mult, e.head_lr_mult, e.target_epochs, e.checkpoint_interval, "
        "e.train_start::text, e.train_end::text, e.infer_start::text, e.infer_end::text, "
        "e.resume_model_id, e.train_log_path, "
        "extract(epoch from COALESCE(ce.infer_started_at, ce.started_at, ce.updated_at))::double precision, "
        "ce.cancellation_request_id "
        "FROM experiment_checkpoint_eval ce "
        "JOIN experiment e ON e.experiment_id = COALESCE(ce.parent_experiment_id, ce.experiment_id) "
        "WHERE ce.status = $1 AND ce.phase = $2 "
        "AND (ce.phase <> 'analyze' OR ce.cancellation_request_id IS NULL) "
        "ORDER BY ce.created_at ASC, ce.checkpoint_eval_id ASC;",
        status,
        phase);

    std::vector<CheckpointEvalRow> evals;
    evals.reserve(rows.size());
    for (const auto& row : rows)
        evals.push_back(RowToCheckpointEval(row));
    return evals;
}

std::optional<CheckpointEvalRow> LoadCheckpointEvalById(pqxx::work& w,
                                                        long long checkpointEvalId)
{
    if (!CheckpointEvalTableExists(w))
        return std::nullopt;
    pqxx::result rows = w.exec_params(
        "SELECT ce.checkpoint_eval_id, ce.checkpoint_epoch, ce.checkpoint_model_id, "
        "ce.status, ce.phase, ce.worker_pid, ce.infer_log_path, ce.analysis_log_path, "
        "e.experiment_id, e.symbol, e.prediction_horizon, e.c_next_threshold, "
        "e.core_lr_mult, e.head_lr_mult, e.target_epochs, e.checkpoint_interval, "
        "e.train_start::text, e.train_end::text, e.infer_start::text, e.infer_end::text, "
        "e.resume_model_id, e.train_log_path, "
        "extract(epoch from COALESCE(ce.infer_started_at, ce.started_at, ce.updated_at))::double precision, "
        "ce.cancellation_request_id "
        "FROM experiment_checkpoint_eval ce "
        "JOIN experiment e ON e.experiment_id = COALESCE(ce.parent_experiment_id, ce.experiment_id) "
        "WHERE ce.checkpoint_eval_id = $1;",
        checkpointEvalId);
    if (rows.empty())
        return std::nullopt;
    return RowToCheckpointEval(rows[0]);
}

std::string ReadFileIfExists(const std::optional<std::string>& path)
{
    if (!path.has_value())
        return {};
    std::ifstream in{*path};
    if (!in)
        return {};
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

std::string ReadFileIfExists(const std::string& path)
{
    std::ifstream in{path};
    if (!in)
        return {};
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

void WriteTextFile(const std::string& path, const std::string& text)
{
    std::ofstream out{path};
    out << text;
}

void AppendTextFile(const std::string& path, const std::string& text)
{
    std::ofstream out{path, std::ios::app};
    out << text;
    out.flush();
}

std::optional<long long> ExtractLastModelId(const std::string& text)
{
    std::regex idRegex{
        "(Saved model with model_id=|Created new model_id=|RESUME_SAVED_NEW_MODEL_ID=|CHECKPOINT_SAVE_DONE[^\\n]*model_id=)([0-9]+)"};
    std::optional<long long> last;
    for (auto it = std::sregex_iterator(text.begin(), text.end(), idRegex);
         it != std::sregex_iterator();
         ++it)
    {
        last = std::stoll((*it)[2].str());
    }
    return last;
}

std::optional<long long> ExtractLastModelIdByRegex(const std::string& text,
                                                          const std::regex& idRegex,
                                                          size_t captureIndex)
{
    std::optional<long long> last;
    for (auto it = std::sregex_iterator(text.begin(), text.end(), idRegex);
         it != std::sregex_iterator();
         ++it)
    {
        last = std::stoll((*it)[captureIndex].str());
    }
    return last;
}

std::optional<long long> ExtractCompletedTrainModelId(const std::string& text)
{
    return ExtractLastModelIdByRegex(
        text,
        std::regex{"(Saved model with model_id=|RESUME_SAVED_NEW_MODEL_ID=)([0-9]+)"},
        2);
}

std::optional<long long> ExtractCheckpointModelId(const std::string& text)
{
    return ExtractLastModelIdByRegex(
        text,
        std::regex{"CHECKPOINT_SAVE_DONE[^\\n]*model_id=([0-9]+)"},
        1);
}

std::string ModelIdSearchPatternDescription()
{
    return "Saved model with model_id=;Created new model_id=;RESUME_SAVED_NEW_MODEL_ID=;CHECKPOINT_SAVE_DONE model_id=";
}

std::string LastLines(const std::string& text, size_t lineCount)
{
    std::vector<std::string> lines;
    std::istringstream input{text};
    std::string line;
    while (std::getline(input, line))
    {
        lines.push_back(line);
        if (lines.size() > lineCount)
            lines.erase(lines.begin());
    }

    std::ostringstream out;
    for (const auto& item : lines)
        out << item << "\n";
    return out.str();
}

void PrintModelIdDetectionWarning(long long experimentId,
                                         const std::string& logPath,
                                         const std::string& logText)
{
    std::cout << "SCHEDULER_MODEL_ID_PARSE_WARNING"
              << ",experiment_id=" << experimentId
              << ",log_path=" << logPath
              << ",patterns=" << ShellDisplayQuote(ModelIdSearchPatternDescription())
              << std::endl;
    std::cout << "SCHEDULER_TRAIN_LOG_TAIL_BEGIN"
              << ",experiment_id=" << experimentId
              << ",lines=50"
              << std::endl;
    std::istringstream tail{LastLines(logText, 50)};
    std::string line;
    while (std::getline(tail, line))
    {
        std::cout << "SCHEDULER_TRAIN_LOG_TAIL"
                  << ",experiment_id=" << experimentId
                  << ",line=" << line
                  << std::endl;
    }
    std::cout << "SCHEDULER_TRAIN_LOG_TAIL_END"
              << ",experiment_id=" << experimentId
              << std::endl;
}

std::optional<double> ExtractLastDouble(const std::string& text, const std::regex& regex)
{
    std::optional<double> value;
    for (auto it = std::sregex_iterator(text.begin(), text.end(), regex);
         it != std::sregex_iterator();
         ++it)
    {
        value = std::stod((*it)[1].str());
    }
    return value;
}

ParsedMetrics ParseMetricsFromLogs(const ExperimentRow& experiment)
{
    ParsedMetrics metrics;
    const std::string trainLog = ReadFileIfExists(experiment.trainLogPath);
    const std::string inferLog = ReadFileIfExists(experiment.inferLogPath);
    const std::string combined = trainLog + "\n" + inferLog;

    metrics.modelId = ExtractLastModelId(combined);
    if (!metrics.modelId.has_value())
        metrics.modelId = experiment.lastModelId;

    metrics.inferAccuracy = ExtractLastDouble(
        inferLog,
        std::regex{"Overall 3-class accuracy:\\s*([0-9]+(?:\\.[0-9]+)?)%"});
    if (metrics.inferAccuracy.has_value())
        metrics.inferAccuracy = *metrics.inferAccuracy / 100.0;

    metrics.validationAccuracy = ExtractLastDouble(
        combined,
        std::regex{"EPOCH_3CLASS_ACCURACY[^\\n]*(?:validation_accuracy|val_accuracy|accuracy)=([0-9]+(?:\\.[0-9]+)?)"});
    metrics.trainAccuracy = ExtractLastDouble(
        combined,
        std::regex{"EPOCH_3CLASS_ACCURACY[^\\n]*(?:train_accuracy)=([0-9]+(?:\\.[0-9]+)?)"});
    metrics.lossLast = ExtractLastDouble(
        combined,
        std::regex{"(?:loss|LOSS)[= :]([0-9]+(?:\\.[0-9]+)?)"});

    const std::optional<double> parsedCompletedEpochs = ExtractLastDouble(
        combined,
        std::regex{"(?:completed_epochs|epochs_trained|RESUME_TARGET_EPOCH)[= ]([0-9]+)"});
    if (parsedCompletedEpochs.has_value())
        metrics.completedEpochs = static_cast<int>(*parsedCompletedEpochs);

    std::regex confusionRegex{
        "Overall 3-class confusion matrix[^\\n]*\\[\\[([0-9]+),\\s*([0-9]+),\\s*([0-9]+)\\],\\s*\\[([0-9]+),\\s*([0-9]+),\\s*([0-9]+)\\],\\s*\\[([0-9]+),\\s*([0-9]+),\\s*([0-9]+)\\]\\]"};
    std::smatch match;
    std::string::const_iterator searchStart = inferLog.cbegin();
    while (std::regex_search(searchStart, inferLog.cend(), match, confusionRegex))
    {
        for (int i = 0; i < 9; ++i)
            metrics.confusion[i / 3][i % 3] = std::stoll(match[i + 1].str());
        metrics.hasConfusion = true;
        searchStart = match.suffix().first;
    }

    std::regex acceptRegex{"ACCEPT_MODEL=(true|false)"};
    for (auto it = std::sregex_iterator(combined.begin(), combined.end(), acceptRegex);
         it != std::sregex_iterator();
         ++it)
    {
        metrics.acceptModel = ((*it)[1].str() == "true");
    }

    std::regex rejectRegex{"REJECT_REASON=([^\\n,]+)"};
    for (auto it = std::sregex_iterator(combined.begin(), combined.end(), rejectRegex);
         it != std::sregex_iterator();
         ++it)
    {
        metrics.rejectReason = (*it)[1].str();
    }

    if (metrics.hasConfusion)
    {
        long long total = 0;
        long long correct = 0;
        for (int actual = 0; actual < 3; ++actual)
        {
            for (int pred = 0; pred < 3; ++pred)
            {
                total += metrics.confusion[actual][pred];
                if (actual == pred)
                    correct += metrics.confusion[actual][pred];
            }
        }
        if (!metrics.inferAccuracy.has_value() && total > 0)
            metrics.inferAccuracy = static_cast<double>(correct) / static_cast<double>(total);
        metrics.acceptRate = metrics.acceptModel.has_value() && *metrics.acceptModel ? 1.0 : 0.0;
        metrics.acceptAccuracy = metrics.inferAccuracy;
    }

    return metrics;
}

bool IsValidInferenceLogText(const std::string& text)
{
    return text.find("Overall 3-class accuracy") != std::string::npos &&
           text.find("Overall 3-class confusion matrix") != std::string::npos &&
           text.find("MODEL_ACCEPTANCE") != std::string::npos;
}

bool HasValidInferenceLogPath(const ExperimentRow& experiment)
{
    if (!experiment.inferLogPath.has_value())
        return false;
    return IsValidInferenceLogText(ReadFileIfExists(experiment.inferLogPath));
}

std::optional<std::string> DiscoverValidInferenceLog(const ExperimentRow& experiment)
{
    if (!experiment.lastModelId.has_value())
        return std::nullopt;

    const std::string modelNeedle = std::to_string(*experiment.lastModelId);
    const std::vector<std::filesystem::path> roots = {
        std::filesystem::current_path(),
        std::filesystem::current_path() / "experiment_logs"};

    for (const auto& root : roots)
    {
        std::error_code ec;
        if (!std::filesystem::exists(root, ec) || !std::filesystem::is_directory(root, ec))
            continue;

        for (const auto& entry : std::filesystem::directory_iterator(root, ec))
        {
            if (ec)
                break;
            if (!entry.is_regular_file(ec))
                continue;

            const std::string filename = entry.path().filename().string();
            if (filename.find(modelNeedle) == std::string::npos ||
                filename.find("infer") == std::string::npos)
            {
                continue;
            }

            const std::string path = entry.path().string();
            if (IsValidInferenceLogText(ReadFileIfExists(path)))
                return path;
        }
    }
    return std::nullopt;
}

bool FileWasModifiedForAttempt(const std::string& path,
                               double attemptStartedEpoch)
{
    std::error_code ec;
    const auto fileTime = std::filesystem::last_write_time(path, ec);
    if (ec)
        return false;
    const auto systemTime = std::chrono::time_point_cast<std::chrono::system_clock::duration>(
        fileTime - std::filesystem::file_time_type::clock::now() +
        std::chrono::system_clock::now());
    const double modifiedEpoch = std::chrono::duration<double>(
        systemTime.time_since_epoch()).count();
    return IsCurrentWorkerAttemptEvidence(modifiedEpoch, attemptStartedEpoch);
}

bool HasValidInferenceLogPathForAttempt(
    const ExperimentRow& experiment,
    double attemptStartedEpoch)
{
    return experiment.inferLogPath.has_value() &&
           FileWasModifiedForAttempt(*experiment.inferLogPath, attemptStartedEpoch) &&
           IsValidInferenceLogText(ReadFileIfExists(experiment.inferLogPath));
}

std::optional<std::string> DiscoverValidInferenceLogForAttempt(
    const ExperimentRow& experiment,
    double attemptStartedEpoch)
{
    if (!experiment.lastModelId.has_value())
        return std::nullopt;

    const std::string experimentNeedle =
        "experiment_" + std::to_string(experiment.experimentId) + "_";
    const std::vector<std::filesystem::path> roots = {
        std::filesystem::current_path(),
        std::filesystem::current_path() / "experiment_logs"};

    for (const auto& root : roots)
    {
        std::error_code ec;
        if (!std::filesystem::exists(root, ec) || !std::filesystem::is_directory(root, ec))
            continue;
        for (const auto& entry : std::filesystem::directory_iterator(root, ec))
        {
            if (ec)
                break;
            if (!entry.is_regular_file(ec))
                continue;
            const std::string filename = entry.path().filename().string();
            if (filename.find(experimentNeedle) == std::string::npos ||
                filename.find("infer") == std::string::npos)
                continue;
            const std::string path = entry.path().string();
            if (FileWasModifiedForAttempt(path, attemptStartedEpoch) &&
                IsValidInferenceLogText(ReadFileIfExists(path)))
                return path;
        }
    }
    return std::nullopt;
}

void ApplyPersistedSymbolToAnalysisExperiment(pqxx::work& w,
                                                     ExperimentRow& experiment,
                                                     const ParsedMetrics& metrics)
{
    const std::optional<long long> modelId =
        metrics.modelId.has_value() ? metrics.modelId : experiment.lastModelId;
    if (!modelId.has_value())
    {
        experiment.symbol = EA::CanonicalSymbol::Normalize(experiment.symbol);
        return;
    }

    const std::optional<std::string> persistedSymbol =
        TryLoadPersistedCanonicalSymbol(w, *modelId);
    if (persistedSymbol.has_value())
    {
        experiment.symbol = *persistedSymbol;
        std::cout << "MODEL_SYMBOL"
                  << ",source=database"
                  << ",model_id=" << *modelId
                  << ",symbol=" << experiment.symbol
                  << std::endl;
        return;
    }

    PrintModelSymbolMissing(*modelId);
    experiment.symbol = EA::CanonicalSymbol::Normalize(experiment.symbol);
    std::cout << "MODEL_SYMBOL"
              << ",source=legacy"
              << ",model_id=" << *modelId
              << ",symbol=" << experiment.symbol
              << ",warning=missing_metadata"
              << std::endl;
}

bool ApplyStructuredInferenceMetrics(pqxx::work& w,
                                            const ExperimentRow& experiment,
                                            ParsedMetrics& metrics)
{
    if (!TableExists(w, "inference_eval_result") ||
        !experiment.lastModelId.has_value() ||
        !experiment.inferStart.has_value() ||
        !experiment.inferEnd.has_value())
    {
        return false;
    }

    pqxx::result rows = w.exec_params(
        "SELECT accuracy, accept_model, COALESCE(reject_reason, ''), completed_epochs "
        "FROM inference_eval_result "
        "WHERE model_id = $1 "
        "AND symbol = $2 "
        "AND prediction_horizon = $3 "
        "AND threshold_logret = $4 "
        "AND from_date = $5 "
        "AND to_date = $6 "
        "AND status = 'completed' "
        "AND inference_scope = 'final' "
        "AND checkpoint_eval_id IS NULL "
        "ORDER BY completed_at DESC LIMIT 1;",
        *experiment.lastModelId,
        experiment.symbol,
        experiment.predictionHorizon,
        experiment.cNextThreshold,
        experiment.inferStart->substr(0, 10),
        experiment.inferEnd->substr(0, 10));
    if (rows.empty())
        return false;

    if (!rows[0][0].is_null())
        metrics.inferAccuracy = rows[0][0].as<double>();
    if (!rows[0][1].is_null())
        metrics.acceptModel = rows[0][1].as<bool>();
    const std::string rejectReason = rows[0][2].as<std::string>();
    if (!rejectReason.empty())
        metrics.rejectReason = rejectReason;
    if (!rows[0][3].is_null())
        metrics.completedEpochs = rows[0][3].as<int>();
    metrics.modelId = experiment.lastModelId;
    metrics.acceptAccuracy = metrics.inferAccuracy;
    metrics.acceptRate = metrics.acceptModel.has_value() && *metrics.acceptModel ? 1.0 : 0.0;
    return true;
}

