void TransitionRecoveredInferenceToAnalyze(pqxx::work& w,
                                                  const ExperimentRow& experiment,
                                                  const std::string& sourceMarker,
                                                  const std::string& reason,
                                                  const std::optional<std::string>& recoveredLogPath = std::nullopt,
                                                  const std::optional<long long>&
                                                      workerAttemptId = std::nullopt,
                                                  bool consumeForcedFinalInferenceRerun = false)
{
    if (recoveredLogPath.has_value())
        UpdateInferLogPath(
            w, experiment, *recoveredLogPath, workerAttemptId);

    std::cout << sourceMarker
              << ",experiment_id=" << experiment.experimentId
              << ",model_id=" << (experiment.lastModelId.has_value() ? std::to_string(*experiment.lastModelId) : "none")
              << ",phase=infer"
              << ",reason=" << reason;
    if (recoveredLogPath.has_value())
        std::cout << ",infer_log_path=" << *recoveredLogPath;
    else if (experiment.inferLogPath.has_value())
        std::cout << ",infer_log_path=" << *experiment.inferLogPath;
    std::cout << std::endl;

    if (consumeForcedFinalInferenceRerun && workerAttemptId)
    {
        const pqxx::result consumed = w.exec(
            "UPDATE experiment e SET "
            "operator_forced_final_inference_rerun_requested=false,"
            "updated_at=clock_timestamp() "
            "FROM experiment_scheduler_worker_attempt a "
            "WHERE e.experiment_id=$1 "
            "AND e.operator_forced_final_inference_rerun_requested "
            "AND e.status='running' AND e.phase='infer' "
            "AND e.active_scheduler_worker_attempt_id=$2 "
            "AND a.worker_attempt_id=$2 "
            "AND a.experiment_id=e.experiment_id "
            "AND a.worker_kind='experiment' "
            "AND a.lifecycle_phase='infer' "
            "AND EXISTS ("
            " SELECT 1 FROM inference_eval_result r "
            " WHERE r.model_id=e.last_model_id "
            " AND r.symbol=e.symbol "
            " AND r.prediction_horizon=e.prediction_horizon "
            " AND abs(r.threshold_logret-e.c_next_threshold)<=1e-7 "
            " AND r.from_date=$3 "
            " AND r.to_date=$4 "
            " AND r.status='completed' "
            " AND r.inference_scope='final' "
            " AND r.checkpoint_eval_id IS NULL "
            " AND r.completed_at>=a.reserved_at"
            ") RETURNING e.experiment_id;",
            pqxx::params{
                experiment.experimentId,
                *workerAttemptId,
                experiment.inferStart->substr(0, 10),
                experiment.inferEnd->substr(0, 10)});
        EA::SchedulerOwnership::RequireAffectedExactlyOne(
            consumed,
            "consume_operator_forced_final_inference_rerun");
        std::cout
            << "SCHEDULER_FORCED_FINAL_INFERENCE_RERUN_CONSUMED"
            << ",experiment_id=" << experiment.experimentId
            << ",worker_attempt_id=" << *workerAttemptId
            << std::endl;
    }

    MarkExperimentPendingPhase(
        w,
        experiment,
        "infer",
        "analyze",
        0,
        workerAttemptId);
    std::cout << "SCHEDULER_ENQUEUE_ANALYZE"
              << ",experiment_id=" << experiment.experimentId
              << ",model_id=" << (experiment.lastModelId.has_value() ? std::to_string(*experiment.lastModelId) : "none")
              << std::endl;
}

bool TransitionAfterTrainModelAvailable(pqxx::work& w,
                                               const ExperimentRow& experiment,
                                               long long modelId,
                                               int exitCode,
                                               const std::string& fromPhase,
                                               const std::optional<long long>&
                                                   workerAttemptId = std::nullopt)
{
    ExperimentRow updatedExperiment = experiment;
    updatedExperiment.lastModelId = modelId;
    pqxx::result modelUpdated = w.exec_params(
        "UPDATE experiment "
        "SET last_model_id = $1, exit_code = $2, error_message = NULL, updated_at = now() "
        "WHERE experiment_id = $3 "
        "AND ($4::bigint IS NULL OR "
        "active_scheduler_worker_attempt_id=$4) "
        "RETURNING experiment_id;",
        modelId,
        exitCode,
        experiment.experimentId,
        workerAttemptId);
    if (workerAttemptId)
        EA::SchedulerOwnership::RequireAffectedExactlyOne(
            modelUpdated, "transition_train_model_exact_attempt");
    std::cout << "EXPERIMENT_LAST_MODEL_ID"
              << ",experiment_id=" << experiment.experimentId
              << ",model_id=" << modelId
              << std::endl;

    if (HasCompletedAnalysisResult(w, updatedExperiment))
    {
        std::cout << "SCHEDULER_SKIP_EXISTING_ANALYSIS"
                  << ",experiment_id=" << experiment.experimentId
                  << ",model_id=" << modelId
                  << std::endl;
        MarkExperimentDone(
            w, updatedExperiment, fromPhase, workerAttemptId);
    }
    else if (HasCompletedInferenceResult(w, updatedExperiment))
    {
        std::cout << "SCHEDULER_SKIP_EXISTING_INFERENCE"
                  << ",experiment_id=" << experiment.experimentId
                  << ",model_id=" << modelId
                  << std::endl;
        MarkExperimentPendingPhase(
            w,
            updatedExperiment,
            fromPhase,
            "analyze",
            exitCode,
            workerAttemptId);
        std::cout << "SCHEDULER_ENQUEUE_ANALYZE"
                  << ",experiment_id=" << experiment.experimentId
                  << ",model_id=" << modelId
                  << std::endl;
    }
    else if (updatedExperiment.inferStart.has_value() && updatedExperiment.inferEnd.has_value())
    {
        MarkExperimentPendingPhase(
            w,
            updatedExperiment,
            fromPhase,
            "infer",
            exitCode,
            workerAttemptId);
        std::cout << "SCHEDULER_ENQUEUE_INFER"
                  << ",experiment_id=" << experiment.experimentId
                  << ",model_id=" << modelId
                  << std::endl;
    }
    else
    {
        MarkExperimentFailed(
            w,
            updatedExperiment,
            "train_completed_missing_inference_range",
            exitCode,
            workerAttemptId);
        return false;
    }
    return true;
}

void RequeueTrainOrphanFromCheckpoint(pqxx::work& w,
                                      const ExperimentRow& experiment,
                                      const QueueResumeMeta& meta,
                                      const std::optional<long long>&
                                          workerAttemptId = std::nullopt)
{
    pqxx::result updated = w.exec_params(
        "UPDATE experiment "
        "SET status = 'pending', phase = 'train', last_model_id = $1, resume_model_id = $1, "
        "exit_code = NULL, error_message = NULL, updated_at = updated_at "
        "WHERE experiment_id = $2 "
        "AND ($3::bigint IS NULL OR "
        "active_scheduler_worker_attempt_id=$3);",
        meta.modelId,
        experiment.experimentId,
        workerAttemptId);
    if (workerAttemptId)
        EA::SchedulerOwnership::RequireAffectedExactlyOne(
            updated, "requeue_train_orphan_exact_attempt");
    std::cout << "SCHEDULER_ORPHAN_RECOVERED"
              << ",experiment_id=" << experiment.experimentId
              << ",resume_model_id=" << meta.modelId
              << ",completed_epochs=" << meta.completedEpochs
              << ",target_epochs=" << experiment.targetEpochs
              << std::endl;
    LogPhaseTransition(experiment.experimentId, "train", "train");
}

bool RecoverTrainOrphanFromModel(pqxx::work& w,
                                 const ExperimentRow& experiment,
                                 long long modelId,
                                 const std::optional<long long>&
                                     workerAttemptId = std::nullopt)
{
    const std::optional<QueueResumeMeta> meta = TryLoadRecoverableModelMeta(w, modelId);
    if (!meta.has_value())
        return false;

    if (meta->symbol != experiment.symbol ||
        meta->predictionHorizon != experiment.predictionHorizon ||
        std::fabs(meta->threshold - experiment.cNextThreshold) > 1e-7 ||
        !SameDate(meta->trainStart, experiment.trainStart) ||
        !SameDate(meta->trainEnd, experiment.trainEnd))
    {
        std::cout << "SCHEDULER_ORPHAN_MODEL_UNUSABLE"
                  << ",experiment_id=" << experiment.experimentId
                  << ",model_id=" << modelId
                  << ",reason=config_mismatch"
                  << std::endl;
        return false;
    }

    if (meta->completedEpochs >= experiment.targetEpochs)
    {
        std::cout << "SCHEDULER_ORPHAN_ADVANCED"
                  << ",experiment_id=" << experiment.experimentId
                  << ",model_id=" << modelId
                  << ",completed_epochs=" << meta->completedEpochs
                  << ",target_epochs=" << experiment.targetEpochs
                  << ",next_phase=" << (experiment.inferStart.has_value() && experiment.inferEnd.has_value() ? "infer" : "none")
                  << std::endl;
        return TransitionAfterTrainModelAvailable(
            w, experiment, modelId, 0, "train", workerAttemptId);
    }

    RequeueTrainOrphanFromCheckpoint(
        w, experiment, *meta, workerAttemptId);
    return true;
}

[[maybe_unused]] bool CompleteTrainPhase(pqxx::work& w,
                               const ExperimentRow& experiment,
                               int exitCode,
                               const std::string& logPath,
                               const std::string& commandDisplay)
{
    const std::string logText = ReadFileIfExists(logPath);
    std::optional<long long> lastModelId = ExtractLastModelId(logText);
    if (!lastModelId.has_value())
        lastModelId = FindLatestModelForExperiment(w, experiment.experimentId);
    const bool success = exitCode == 0 && lastModelId.has_value();
    if (success)
    {
        return TransitionAfterTrainModelAvailable(w, experiment, *lastModelId, exitCode, "train");
    }
    else
    {
        const std::string failureReason = lastModelId.has_value() ? "train_failed" : "train_failed_no_model_id";
        if (exitCode == 0 && !lastModelId.has_value())
            PrintModelIdDetectionWarning(experiment.experimentId, logPath, logText);
        const std::string errorMessage =
            failureReason +
            ";exit_code=" + std::to_string(exitCode) +
            ";command=" + commandDisplay +
            ";model_id_patterns=" + ModelIdSearchPatternDescription();
        w.exec_params(
            "UPDATE experiment "
            "SET status = 'failed', exit_code = $1, error_message = $2, completed_at = now(), updated_at = now() "
            "WHERE experiment_id = $3;",
            exitCode,
            errorMessage,
            experiment.experimentId);
        return false;
    }
}

void LogRunningExperimentPresent(const ExperimentRow& experiment,
                                 const std::string& phase,
                                 SchedulerEventLogState* logState,
                                 bool verbose)
{
    const std::string key = phase + "|" + std::to_string(experiment.experimentId);
    if (logState != nullptr)
        logState->currentRunningPresentKeys.insert(key);
    if (!verbose &&
        logState != nullptr &&
        logState->previousRunningPresentKeys.find(key) != logState->previousRunningPresentKeys.end())
    {
        return;
    }

    if (phase == "infer")
    {
        std::cout << "SCHEDULER_ORPHAN_INFER_STILL_RUNNING"
                  << ",experiment_id=" << experiment.experimentId
                  << ",model_id=" << (experiment.lastModelId.has_value() ? std::to_string(*experiment.lastModelId) : "none")
                  << ",phase=infer"
                  << ",reason=matching_process_exists"
                  << std::endl;
    }
    else
    {
        std::cout << "SCHEDULER_RUNNING_EXPERIMENT_PRESENT"
                  << ",experiment_id=" << experiment.experimentId
                  << ",phase=" << phase
                  << std::endl;
    }
}

[[maybe_unused]] int RecoverOrphanedRunningExperimentsLegacy(
    pqxx::work& w,
    SchedulerEventLogState* logState,
    bool verbose)
{
    int recoveredOrFailed = 0;
    const std::vector<RunningExperimentState> runningExperiments = LoadRunningExperiments(w);
    for (const auto& state : runningExperiments)
    {
        const ExperimentRow& experiment = state.experiment;
        const std::string& phase = state.phase;
        const auto ownedChild = std::find_if(
            gSchedulerOwnedChildren.begin(),
            gSchedulerOwnedChildren.end(),
            [&](const auto& entry) {
                return entry.second.experimentId == experiment.experimentId &&
                       entry.second.phase == phase;
            });
        if (ownedChild != gSchedulerOwnedChildren.end())
        {
            LogRunningExperimentPresent(experiment, phase, logState, verbose);
            continue;
        }
        if (const auto discovered =
                DiscoverRunningProcessForExperiment(experiment, phase);
            discovered)
        {
            PersistExperimentWorkerPid(
                w,
                experiment,
                phase,
                discovered->pid,
                discovered->processGroupId,
                discovered->executable,
                discovered->command,
                discovered->processStartIdentity);
            LogRunningExperimentPresent(experiment, phase, logState, verbose);
            continue;
        }

        pqxx::result cancellation = w.exec_params(
            "SELECT r.cancellation_mode,e.cancel_after_checkpoint_epoch,"
            "e.cancellation_request_id "
            "FROM experiment e JOIN experiment_admin_request r "
            "ON r.request_id=e.cancellation_request_id "
            "WHERE e.experiment_id=$1;",
            experiment.experimentId);
        if (!cancellation.empty())
        {
            const std::string mode =
                cancellation[0][0].as<std::string>();
            if (mode == "after_next_checkpoint" && phase == "train" &&
                !cancellation[0][1].is_null())
            {
                const std::optional<long long> restartModel =
                    FindLatestModelForExperiment(
                        w, experiment.experimentId);
                if (restartModel)
                    w.exec_params(
                        "UPDATE experiment SET status='pending',phase='train',"
                        "worker_pid=NULL,worker_process_group_id=NULL,"
                        "worker_control_state='running',last_model_id=$1,"
                        "current_operation='train',"
                        "error_message='cancellation_worker_restart_required',"
                        "updated_at=now() WHERE experiment_id=$2 "
                        "AND status='running';",
                        *restartModel,
                        experiment.experimentId);
                else
                {
                    w.exec_params(
                        "UPDATE experiment SET status='cancelled',"
                        "worker_pid=NULL,worker_process_group_id=NULL,"
                        "completed_at=now(),cancellation_completed_at=now(),"
                        "error_message='cancelled_missing_worker_no_checkpoint',"
                        "updated_at=now() WHERE experiment_id=$1 "
                        "AND status='running';",
                        experiment.experimentId);
                    w.exec_params(
                        "UPDATE experiment_admin_worker_outcome SET "
                        "outcome_status='partial',"
                        "detail='missing_worker_no_restart_checkpoint',"
                        "updated_at=now() WHERE request_id=$1 "
                        "AND experiment_id=$2 "
                        "AND outcome_status='pending_checkpoint';",
                        cancellation[0][2].as<long long>(),
                        experiment.experimentId);
                }
            }
            else
            {
                w.exec_params(
                    "UPDATE experiment SET status='cancelled',worker_pid=NULL,"
                    "worker_process_group_id=NULL,"
                    "completed_at=COALESCE(completed_at,now()),"
                    "cancellation_completed_at=now(),"
                    "error_message='cancelled_missing_worker',updated_at=now() "
                    "WHERE experiment_id=$1 AND status='running';",
                    experiment.experimentId);
            }
            ++recoveredOrFailed;
            continue;
        }

        bool successfulCompletionRecorded = false;
        if (phase == "infer")
        {
            successfulCompletionRecorded =
                HasCompletedInferenceResultForAttempt(
                    w, experiment, state.attemptStartedEpoch) ||
                HasValidInferenceLogPathForAttempt(
                    experiment, state.attemptStartedEpoch) ||
                DiscoverValidInferenceLogForAttempt(
                    experiment, state.attemptStartedEpoch).has_value();
        }
        else if (phase == "analyze")
        {
            successfulCompletionRecorded =
                HasCompletedAnalysisResultForAttempt(
                    w, experiment, state.attemptStartedEpoch);
        }
        else if (phase == "train")
        {
            successfulCompletionRecorded =
                FindLatestModelForExperimentSince(
                    w,
                    experiment.experimentId,
                    state.attemptStartedEpoch).has_value();
            if (!successfulCompletionRecorded)
            {
                const std::string existingTrainLog = ReadFileIfExists(experiment.trainLogPath);
                std::optional<long long> loggedModelId =
                    ExtractCompletedTrainModelId(existingTrainLog);
                if (!loggedModelId.has_value())
                    loggedModelId = ExtractCheckpointModelId(existingTrainLog);
                successfulCompletionRecorded =
                    loggedModelId.has_value() &&
                    ModelWasCreatedForAttempt(
                        w,
                        *loggedModelId,
                        experiment.experimentId,
                        state.attemptStartedEpoch);
            }
        }

        ++recoveredOrFailed;
        if (ShouldReconcileSchedulerOrphan(
                false,
                false,
                successfulCompletionRecorded))
        {
            std::cout << "SCHEDULER_ORPHAN_DETECTED"
                      << ",experiment_id=" << experiment.experimentId
                      << ",phase=" << phase
                      << ",pid=" << (state.workerPid.has_value() ? std::to_string(*state.workerPid) : "none")
                      << ",ownership=previous_scheduler_or_unknown"
                      << std::endl;
        }

        if (phase == "infer")
        {
            if (HasCompletedInferenceResultForAttempt(
                    w, experiment, state.attemptStartedEpoch))
            {
                TransitionRecoveredInferenceToAnalyze(
                    w,
                    experiment,
                    "SCHEDULER_ORPHAN_RECOVERED_INFERENCE_RESULT",
                    "completed_inference_eval_result");
            }
            else if (HasValidInferenceLogPathForAttempt(
                         experiment, state.attemptStartedEpoch))
            {
                TransitionRecoveredInferenceToAnalyze(
                    w,
                    experiment,
                    "SCHEDULER_ORPHAN_RECOVERED_INFER_LOG",
                    "valid_infer_log_path");
            }
            else if (const std::optional<std::string> discoveredLog =
                         DiscoverValidInferenceLogForAttempt(
                             experiment, state.attemptStartedEpoch);
                     discoveredLog.has_value())
            {
                TransitionRecoveredInferenceToAnalyze(
                    w,
                    experiment,
                    "SCHEDULER_ORPHAN_RECOVERED_INFER_LOG",
                    "discovered_valid_infer_log",
                    discoveredLog);
            }
            else
            {
                const std::string error = "orphaned_running_infer_no_process_no_result";
                MarkExperimentFailed(w, experiment, error);
                std::cout << "SCHEDULER_ORPHAN_MARKED_FAILED"
                          << ",experiment_id=" << experiment.experimentId
                          << ",model_id=" << (experiment.lastModelId.has_value() ? std::to_string(*experiment.lastModelId) : "none")
                          << ",phase=infer"
                          << ",error=" << error
                          << std::endl;
            }
            continue;
        }

        if (phase == "analyze")
        {
            if (HasCompletedAnalysisResultForAttempt(
                    w, experiment, state.attemptStartedEpoch))
            {
                std::cout << "SCHEDULER_ORPHAN_RECOVERED_ANALYSIS"
                          << ",experiment_id=" << experiment.experimentId
                          << ",model_id=" << (experiment.lastModelId.has_value() ? std::to_string(*experiment.lastModelId) : "none")
                          << std::endl;
                MarkExperimentDone(w, experiment, "analyze");
            }
            else
            {
                const std::string error = "orphaned_running_analyze_no_process_no_result";
                MarkExperimentFailed(w, experiment, error);
                std::cout << "SCHEDULER_ORPHAN_MARKED_FAILED"
                          << ",experiment_id=" << experiment.experimentId
                          << ",error=" << error
                          << std::endl;
            }
            continue;
        }

        if (phase != "train")
        {
            const std::string error = "orphaned_running_invalid_phase";
            MarkExperimentFailed(w, experiment, error);
            std::cout << "SCHEDULER_ORPHAN_MARKED_FAILED"
                      << ",experiment_id=" << experiment.experimentId
                      << ",error=" << error
                      << std::endl;
            continue;
        }

        const std::optional<long long> linkedModelId =
            FindLatestModelForExperimentSince(
                w,
                experiment.experimentId,
                state.attemptStartedEpoch);
        if (linkedModelId.has_value())
        {
            std::cout << "SCHEDULER_ORPHAN_RECOVERED_MODEL"
                      << ",experiment_id=" << experiment.experimentId
                      << ",model_id=" << *linkedModelId
                      << ",source=model_experiment_id"
                      << std::endl;
            if (!RecoverTrainOrphanFromModel(w, experiment, *linkedModelId))
            {
                const std::string error = "orphaned_running_train_model_unusable";
                MarkExperimentFailed(w, experiment, error + ";model_id=" + std::to_string(*linkedModelId));
                std::cout << "SCHEDULER_ORPHAN_FAILED"
                          << ",experiment_id=" << experiment.experimentId
                          << ",reason=model_unusable"
                          << std::endl;
            }
            continue;
        }

        const std::string logText = ReadFileIfExists(experiment.trainLogPath);
        std::optional<long long> finalModelId = ExtractCompletedTrainModelId(logText);
        if (finalModelId.has_value() &&
            !ModelWasCreatedForAttempt(
                w,
                *finalModelId,
                experiment.experimentId,
                state.attemptStartedEpoch))
            finalModelId.reset();
        if (finalModelId.has_value())
        {
            std::cout << "SCHEDULER_ORPHAN_RECOVERED_MODEL"
                      << ",experiment_id=" << experiment.experimentId
                      << ",model_id=" << *finalModelId
                      << std::endl;
            if (!RecoverTrainOrphanFromModel(w, experiment, *finalModelId))
            {
                const std::string error = "orphaned_running_train_model_unusable";
                MarkExperimentFailed(w, experiment, error + ";model_id=" + std::to_string(*finalModelId));
                std::cout << "SCHEDULER_ORPHAN_FAILED"
                          << ",experiment_id=" << experiment.experimentId
                          << ",reason=model_unusable"
                          << std::endl;
            }
            continue;
        }

        std::optional<long long> checkpointModelId = ExtractCheckpointModelId(logText);
        if (checkpointModelId.has_value() &&
            !ModelWasCreatedForAttempt(
                w,
                *checkpointModelId,
                experiment.experimentId,
                state.attemptStartedEpoch))
            checkpointModelId.reset();
        if (checkpointModelId.has_value())
        {
            std::cout << "SCHEDULER_ORPHAN_RECOVERED_CHECKPOINT"
                      << ",experiment_id=" << experiment.experimentId
                      << ",checkpoint_model_id=" << *checkpointModelId
                      << std::endl;
            if (!RecoverTrainOrphanFromModel(w, experiment, *checkpointModelId))
            {
                const std::string error = "orphaned_running_train_checkpoint_unusable";
                MarkExperimentFailed(w, experiment, error + ";checkpoint_model_id=" + std::to_string(*checkpointModelId));
                std::cout << "SCHEDULER_ORPHAN_FAILED"
                          << ",experiment_id=" << experiment.experimentId
                          << ",reason=checkpoint_unusable"
                          << std::endl;
            }
            continue;
        }

        const std::string error = "orphaned_running_train_no_process_no_model";
        MarkExperimentFailed(w, experiment, error);
        std::cout << "SCHEDULER_ORPHAN_FAILED"
                  << ",experiment_id=" << experiment.experimentId
                  << ",reason=no_recoverable_checkpoint"
                  << std::endl;
    }
    return recoveredOrFailed;
}

bool CommandHasExactOptionValue(
    const std::string& command,
    const std::string& option,
    long long expectedValue)
{
    const std::string expected = std::to_string(expectedValue);
    size_t position = 0;
    while ((position = command.find(option, position)) !=
           std::string::npos)
    {
        const bool tokenStart =
            position == 0 ||
            std::isspace(
                static_cast<unsigned char>(command[position - 1]));
        size_t valueStart = position + option.size();
        if (tokenStart && valueStart < command.size() &&
            command[valueStart] == '=')
        {
            ++valueStart;
        }
        else if (
            tokenStart && valueStart < command.size() &&
            std::isspace(
                static_cast<unsigned char>(command[valueStart])))
        {
            while (
                valueStart < command.size() &&
                std::isspace(
                    static_cast<unsigned char>(
                        command[valueStart])))
                ++valueStart;
        }
        else
        {
            position += option.size();
            continue;
        }
        const size_t valueEnd = valueStart + expected.size();
        if (command.compare(
                valueStart, expected.size(), expected) == 0 &&
            (valueEnd == command.size() ||
             std::isspace(
                 static_cast<unsigned char>(
                     command[valueEnd]))))
            return true;
        position += option.size();
    }
    return false;
}

bool CommandHasExactToken(
    const std::string& command,
    const std::string& token)
{
    size_t position = 0;
    while ((position = command.find(token, position)) !=
           std::string::npos)
    {
        const bool starts =
            position == 0 ||
            std::isspace(
                static_cast<unsigned char>(command[position - 1]));
        const size_t end = position + token.size();
        if (starts &&
            (end == command.size() ||
             std::isspace(
                 static_cast<unsigned char>(command[end]))))
            return true;
        position += token.size();
    }
    return false;
}

struct LegacyNoPidProcessSearch
{
    bool inspectionSucceeded = false;
    bool matchingCommandObserved = false;
    bool inspectionDenied = false;
    std::optional<int> matchingPid;
};

LegacyNoPidProcessSearch SearchForLegacyNoPidProcess(
    long long experimentId,
    const std::optional<long long>& checkpointEvalId,
    const std::string& phase)
{
    LegacyNoPidProcessSearch result;
    FILE* pipe = ::popen("ps -axo pid=,command=", "r");
    if (pipe == nullptr)
        return result;
    char buffer[32768] = {};
    std::unique_ptr<
        EA::GlobalExperimentControl::ProcessOperations>
        processes =
            EA::GlobalExperimentControl::
                CreateNativeProcessOperations();
    while (std::fgets(buffer, sizeof(buffer), pipe) != nullptr)
    {
        std::istringstream row{buffer};
        int pid = -1;
        if (!(row >> pid))
            continue;
        std::string command;
        std::getline(row, command);
        const bool commandMatches =
            checkpointEvalId
                ? CommandHasExactOptionValue(
                      command,
                      "--scheduler-checkpoint-eval-id",
                      *checkpointEvalId)
                : (CommandHasExactOptionValue(
                       command,
                       "--scheduler-experiment-id",
                       experimentId) &&
                   ((phase == "train" &&
                     CommandHasExactToken(command, "--train")) ||
                    (phase == "infer" &&
                     CommandHasExactToken(command, "--infer")) ||
                    (phase == "analyze" &&
                     CommandHasExactOptionValue(
                         command,
                         "--analyze-experiment",
                         experimentId))));
        if (!commandMatches)
            continue;
        result.matchingCommandObserved = true;
        result.matchingPid = pid;
        const auto observation = processes->Observe(pid);
        if (observation.permissionDenied ||
            (!observation.inspectionSucceeded &&
             observation.exists))
            result.inspectionDenied = true;
        break;
    }
    result.inspectionSucceeded = ::pclose(pipe) == 0;
    return result;
}

int RecoverOrphanedRunningExperiments(
    pqxx::work& transaction,
    const SchedulerOptions& options,
    SchedulerEventLogState* logState,
    bool verbose)
{
    (void)logState;
    (void)verbose;
    RequireAndRefreshSchedulerAuthority(transaction, options);
    pqxx::result attempts = transaction.exec(
        "SELECT worker_attempt_id,lifecycle_state,ownership_origin,"
        "worker_pid,worker_process_group_id,"
        "worker_process_start_identity,canonical_executable_path,"
        "command_line,experiment_id,checkpoint_eval_id,"
        "lifecycle_phase,worker_kind,"
        "extract(epoch from reserved_at)::double precision,"
        "(reserved_at <= clock_timestamp()-make_interval(secs=>"
        + std::to_string(kSchedulerLaunchRecoveryGraceSeconds) +
        ")) AS recovery_ready,"
        "scheduler_invocation_id,scheduler_fencing_token,"
        "capacity_class,command_identity "
        "FROM experiment_scheduler_worker_attempt "
        "WHERE lifecycle_state IN "
        "('reserved','spawned','running','observed',"
        "'identity_ambiguous') "
        "ORDER BY worker_attempt_id FOR UPDATE;");
    const pqxx::row protocol = transaction.exec(
        "SELECT cutover_state,"
        "cutover_completed_at IS NOT NULL AND "
        "cutover_completed_at + "
        "make_interval(secs=>legacy_no_pid_grace_seconds) "
        "<= clock_timestamp() AS legacy_grace_elapsed "
        "FROM experiment_scheduler_protocol "
        "WHERE singleton=true;").one_row();
    const bool cutoverComplete =
        protocol[0].as<std::string>() == "complete";
    const bool legacyGraceElapsed =
        protocol[1].as<bool>();
    const SchedulerProcessAbsenceEvidence schedulerProcesses =
        InspectAllSchedulerDispatchProcesses();
    const bool foreignSchedulerObserved =
        !schedulerProcesses.inspectionSucceeded ||
        std::any_of(
            schedulerProcesses.schedulers.begin(),
            schedulerProcesses.schedulers.end(),
            [](const auto& scheduler) {
                return scheduler.first !=
                       static_cast<int>(::getpid());
            });

    std::unique_ptr<EA::GlobalExperimentControl::ProcessOperations>
        processes =
            EA::GlobalExperimentControl::CreateNativeProcessOperations();
    int reconciled = 0;
    for (const pqxx::row& row : attempts)
    {
        const long long attemptId = row[0].as<long long>();
        const std::string state = row[1].as<std::string>();
        const std::string origin = row[2].as<std::string>();
        const long long experimentId = row[8].as<long long>();
        const std::optional<long long> checkpointEvalId =
            row[9].is_null()
                ? std::nullopt
                : std::optional<long long>{
                      row[9].as<long long>()};
        const std::string phase = row[10].as<std::string>();
        const std::string workerKind =
            row[11].as<std::string>();
        const double attemptStartedEpoch = row[12].as<double>();
        const bool recoveryReady = row[13].as<bool>();
        const std::optional<std::string> attemptSchedulerInvocation =
            row[14].is_null()
                ? std::nullopt
                : std::optional<std::string>{
                      row[14].as<std::string>()};
        const std::optional<long long> attemptFence =
            row[15].is_null()
                ? std::nullopt
                : std::optional<long long>{
                      row[15].as<long long>()};

        if (workerKind == "checkpoint_analyze")
        {
            const bool currentInProcessAttempt =
                attemptSchedulerInvocation ==
                    std::optional<std::string>{
                        options.schedulerAuthority
                            .schedulerInvocationId} &&
                attemptFence ==
                    std::optional<long long>{
                        options.schedulerAuthority.fencingToken};
            if (currentInProcessAttempt)
                continue;
            pqxx::result abandoned = transaction.exec_params(
                "UPDATE experiment_scheduler_worker_attempt a SET "
                "lifecycle_state='abandoned',"
                "completed_at=clock_timestamp(),"
                "last_observed_at=clock_timestamp(),"
                "observed_by_scheduler_invocation_id=$1,"
                "reconciled_at=clock_timestamp(),"
                "reconciled_by_scheduler_invocation_id=$1,"
                "reconciliation_result="
                "'checkpoint_analysis_owner_lost',"
                "diagnostic='stale_in_process_analysis_requeued' "
                "WHERE a.worker_attempt_id=$2 "
                "AND a.worker_kind='checkpoint_analyze' "
                "AND a.lifecycle_state IN ('reserved','running') "
                "AND EXISTS (SELECT 1 "
                " FROM experiment_checkpoint_eval ce "
                " WHERE ce.checkpoint_eval_id=$3 "
                " AND ce.status='running' AND ce.phase='analyze' "
                " AND ce.active_scheduler_worker_attempt_id="
                "a.worker_attempt_id) "
                "RETURNING a.worker_attempt_id;",
                options.schedulerAuthority.schedulerInvocationId,
                attemptId,
                checkpointEvalId);
            if (abandoned.size() == 1)
            {
                pqxx::result requeued = transaction.exec_params(
                    "UPDATE experiment_checkpoint_eval SET "
                    "status='pending',phase='analyze',"
                    "active_scheduler_worker_attempt_id=NULL,"
                    "worker_pid=NULL,worker_process_group_id=NULL,"
                    "error_message="
                    "'checkpoint_analysis_owner_lost_retryable',"
                    "updated_at=clock_timestamp() "
                    "WHERE checkpoint_eval_id=$1 "
                    "AND status='running' AND phase='analyze' "
                    "AND active_scheduler_worker_attempt_id=$2 "
                    "RETURNING checkpoint_eval_id;",
                    *checkpointEvalId,
                    attemptId);
                EA::SchedulerOwnership::RequireAffectedExactlyOne(
                    requeued,
                    "requeue_stale_checkpoint_analysis_attempt");
                ++reconciled;
            }
            continue;
        }

        if (row[3].is_null())
        {
            if (origin == "legacy_unverified")
            {
                bool lifecycleMatches = false;
                if (checkpointEvalId)
                {
                    lifecycleMatches =
                        transaction.exec_params(
                            "SELECT 1 FROM "
                            "experiment_checkpoint_eval "
                            "WHERE checkpoint_eval_id=$1 "
                            "AND status='running' AND phase=$2 "
                            "AND active_scheduler_worker_attempt_id=$3 "
                            "FOR UPDATE;",
                            *checkpointEvalId,
                            phase,
                            attemptId).size() == 1;
                }
                else
                {
                    lifecycleMatches =
                        transaction.exec_params(
                            "SELECT 1 FROM experiment "
                            "WHERE experiment_id=$1 "
                            "AND status='running' AND phase=$2 "
                            "AND active_scheduler_worker_attempt_id=$3 "
                            "FOR UPDATE;",
                            experimentId,
                            phase,
                            attemptId).size() == 1;
                }
                const LegacyNoPidProcessSearch processSearch =
                    SearchForLegacyNoPidProcess(
                        experimentId,
                        checkpointEvalId,
                        phase);
                const bool safeEnvironment =
                    cutoverComplete &&
                    legacyGraceElapsed &&
                    !foreignSchedulerObserved &&
                    processSearch.inspectionSucceeded &&
                    !processSearch.matchingCommandObserved &&
                    !processSearch.inspectionDenied;
                if (safeEnvironment && !lifecycleMatches)
                {
                    pqxx::result detached =
                        transaction.exec_params(
                            "UPDATE "
                            "experiment_scheduler_worker_attempt a SET "
                            "lifecycle_state='abandoned',"
                            "completed_at=clock_timestamp(),"
                            "last_observed_at=clock_timestamp(),"
                            "observed_by_scheduler_invocation_id=$1,"
                            "reconciled_at=clock_timestamp(),"
                            "reconciled_by_scheduler_invocation_id=$1,"
                            "reconciliation_result="
                            "'legacy_no_pid_lifecycle_detached',"
                            "diagnostic="
                            "'exact_lifecycle_binding_absent_after_cutover' "
                            "WHERE a.worker_attempt_id=$2 "
                            "AND a.ownership_origin="
                            "'legacy_unverified' "
                            "AND a.worker_pid IS NULL "
                            "AND a.lifecycle_state="
                            "'identity_ambiguous' "
                            "AND NOT EXISTS (SELECT 1 "
                            " FROM experiment e "
                            " WHERE e.active_scheduler_worker_attempt_id="
                            "a.worker_attempt_id) "
                            "AND NOT EXISTS (SELECT 1 "
                            " FROM experiment_checkpoint_eval ce "
                            " WHERE ce.active_scheduler_worker_attempt_id="
                            "a.worker_attempt_id) "
                            "RETURNING a.worker_attempt_id;",
                            options.schedulerAuthority
                                .schedulerInvocationId,
                            attemptId);
                    if (detached.size() == 1)
                    {
                        ++reconciled;
                        continue;
                    }
                }
                const bool safeToReconcile =
                    lifecycleMatches && safeEnvironment;
                if (!safeToReconcile)
                {
                    std::string diagnostic =
                        !lifecycleMatches
                            ? "legacy_no_pid_lifecycle_no_longer_bound"
                        : !cutoverComplete
                            ? "legacy_no_pid_cutover_incomplete"
                        : !legacyGraceElapsed
                            ? "legacy_no_pid_grace_not_elapsed"
                        : foreignSchedulerObserved
                            ? "legacy_no_pid_scheduler_process_present"
                        : !processSearch.inspectionSucceeded
                            ? "legacy_no_pid_process_search_failed"
                        : processSearch.inspectionDenied
                            ? "legacy_no_pid_process_inspection_denied"
                            : "legacy_no_pid_matching_process_observed";
                    transaction.exec_params(
                        "UPDATE "
                        "experiment_scheduler_worker_attempt SET "
                        "lifecycle_state='identity_ambiguous',"
                        "last_observed_at=clock_timestamp(),"
                        "observed_by_scheduler_invocation_id=$1,"
                        "reconciliation_result="
                        "'legacy_no_pid_unresolved',"
                        "diagnostic=$2 "
                        "WHERE worker_attempt_id=$3 "
                        "AND ownership_origin='legacy_unverified' "
                        "AND worker_pid IS NULL "
                        "AND lifecycle_state='identity_ambiguous';",
                        options.schedulerAuthority
                            .schedulerInvocationId,
                        diagnostic,
                        attemptId);
                    continue;
                }

                pqxx::result terminal =
                    transaction.exec_params(
                        "UPDATE "
                        "experiment_scheduler_worker_attempt a SET "
                        "lifecycle_state='abandoned',"
                        "completed_at=clock_timestamp(),"
                        "last_observed_at=clock_timestamp(),"
                        "observed_by_scheduler_invocation_id=$1,"
                        "reconciled_at=clock_timestamp(),"
                        "reconciled_by_scheduler_invocation_id=$1,"
                        "reconciliation_result="
                        "'legacy_no_pid_proven_absent_after_cutover',"
                        "diagnostic="
                        "'bounded_legacy_no_pid_reconciliation' "
                        "WHERE a.worker_attempt_id=$2 "
                        "AND a.ownership_origin='legacy_unverified' "
                        "AND a.worker_pid IS NULL "
                        "AND a.lifecycle_state='identity_ambiguous' "
                        "AND EXISTS ("
                        " SELECT 1 FROM "
                        "experiment_scheduler_protocol p "
                        " WHERE p.singleton "
                        " AND p.required_generation=$3 "
                        " AND p.cutover_state='complete' "
                        " AND p.cutover_completed_at + "
                        "make_interval(secs=>"
                        "p.legacy_no_pid_grace_seconds) "
                        "<=clock_timestamp()) "
                        "AND EXISTS ("
                        " SELECT 1 FROM experiment e "
                        " WHERE $4::bigint IS NULL "
                        " AND e.experiment_id=$5 "
                        " AND e.status='running' AND e.phase=$6 "
                        " AND e.active_scheduler_worker_attempt_id="
                        "a.worker_attempt_id "
                        " UNION ALL "
                        " SELECT 1 FROM "
                        "experiment_checkpoint_eval ce "
                        " WHERE $4::bigint IS NOT NULL "
                        " AND ce.checkpoint_eval_id=$4 "
                        " AND ce.status='running' AND ce.phase=$6 "
                        " AND ce.active_scheduler_worker_attempt_id="
                        "a.worker_attempt_id"
                        ") RETURNING a.worker_attempt_id;",
                        options.schedulerAuthority
                            .schedulerInvocationId,
                        attemptId,
                        EA::SchedulerOwnership::
                            kProtocolGeneration,
                        checkpointEvalId,
                        experimentId,
                        phase);
                EA::SchedulerOwnership::RequireAffectedExactlyOne(
                    terminal,
                    "terminalize_legacy_no_pid_attempt");
                pqxx::result lifecycle;
                if (checkpointEvalId)
                {
                    lifecycle = transaction.exec_params(
                        "UPDATE experiment_checkpoint_eval SET "
                        "status='failed',completed_at=clock_timestamp(),"
                        "error_message="
                        "'legacy_no_pid_proven_absent_after_cutover',"
                        "active_scheduler_worker_attempt_id=NULL,"
                        "updated_at=clock_timestamp() "
                        "WHERE checkpoint_eval_id=$1 "
                        "AND status='running' AND phase=$2 "
                        "AND active_scheduler_worker_attempt_id=$3 "
                        "RETURNING checkpoint_eval_id;",
                        *checkpointEvalId,
                        phase,
                        attemptId);
                }
                else
                {
                    lifecycle = transaction.exec_params(
                        "UPDATE experiment SET status='failed',"
                        "completed_at=clock_timestamp(),exit_code=-1,"
                        "error_message="
                        "'legacy_no_pid_proven_absent_after_cutover',"
                        "active_scheduler_worker_attempt_id=NULL,"
                        "updated_at=clock_timestamp() "
                        "WHERE experiment_id=$1 "
                        "AND status='running' AND phase=$2 "
                        "AND active_scheduler_worker_attempt_id=$3 "
                        "RETURNING experiment_id;",
                        experimentId,
                        phase,
                        attemptId);
                }
                EA::SchedulerOwnership::RequireAffectedExactlyOne(
                    lifecycle,
                    "clear_legacy_no_pid_lifecycle_binding");
                std::cout
                    << "SCHEDULER_LEGACY_NO_PID_RECONCILED"
                    << ",worker_attempt_id=" << attemptId
                    << ",experiment_id=" << experimentId
                    << ",checkpoint_eval_id="
                    << (checkpointEvalId
                            ? std::to_string(
                                  *checkpointEvalId)
                            : "NULL")
                    << ",result=proven_absent_after_cutover"
                    << std::endl;
                ++reconciled;
                continue;
            }
            if (!recoveryReady)
            {
                transaction.exec_params(
                    "UPDATE experiment_scheduler_worker_attempt SET "
                    "lifecycle_state='identity_ambiguous',"
                    "last_observed_at=clock_timestamp(),"
                    "observed_by_scheduler_invocation_id=$1,"
                    "diagnostic="
                    "'launch_reservation_within_recovery_grace' "
                    "WHERE worker_attempt_id=$2 "
                    "AND lifecycle_state IN "
                    "('reserved','identity_ambiguous');",
                    options.schedulerAuthority
                        .schedulerInvocationId,
                    attemptId);
                continue;
            }

            pqxx::result terminal = transaction.exec_params(
                "UPDATE experiment_scheduler_worker_attempt a SET "
                "lifecycle_state='launch_failed',"
                "completed_at=clock_timestamp(),exit_code=126,"
                "reconciliation_result='never_spawned',"
                "diagnostic='interrupted_launch_never_spawned' "
                "WHERE a.worker_attempt_id=$1 "
                "AND a.lifecycle_state='reserved' "
                "AND EXISTS ("
                " SELECT 1 FROM experiment e "
                " WHERE $2::bigint IS NULL "
                " AND e.experiment_id=$3 "
                " AND e.status='running' AND e.phase=$4 "
                " AND e.active_scheduler_worker_attempt_id="
                "a.worker_attempt_id "
                " UNION ALL "
                " SELECT 1 FROM experiment_checkpoint_eval ce "
                " WHERE $2::bigint IS NOT NULL "
                " AND ce.checkpoint_eval_id=$2 "
                " AND ce.status='running' AND ce.phase='infer' "
                " AND ce.active_scheduler_worker_attempt_id="
                "a.worker_attempt_id"
                ") RETURNING a.worker_attempt_id;",
                attemptId,
                checkpointEvalId,
                experimentId,
                phase);
            if (terminal.empty())
                continue;
            if (checkpointEvalId)
            {
                pqxx::result lifecycle = transaction.exec_params(
                    "UPDATE experiment_checkpoint_eval SET "
                    "status='failed',completed_at=clock_timestamp(),"
                    "error_message='interrupted_launch_never_spawned',"
                    "active_scheduler_worker_attempt_id=NULL,"
                    "updated_at=clock_timestamp() "
                    "WHERE checkpoint_eval_id=$1 "
                    "AND active_scheduler_worker_attempt_id=$2 "
                    "AND status='running' AND phase='infer' "
                    "RETURNING checkpoint_eval_id;",
                    *checkpointEvalId,
                    attemptId);
                EA::SchedulerOwnership::RequireAffectedExactlyOne(
                    lifecycle,
                    "fail_never_spawned_checkpoint_attempt");
            }
            else
            {
                pqxx::result lifecycle = transaction.exec_params(
                    "UPDATE experiment SET status='failed',"
                    "completed_at=clock_timestamp(),exit_code=126,"
                    "error_message='interrupted_launch_never_spawned',"
                    "active_scheduler_worker_attempt_id=NULL,"
                    "updated_at=clock_timestamp() "
                    "WHERE experiment_id=$1 "
                    "AND active_scheduler_worker_attempt_id=$2 "
                    "AND status='running' AND phase=$3 "
                    "RETURNING experiment_id;",
                    experimentId,
                    attemptId,
                    phase);
                EA::SchedulerOwnership::RequireAffectedExactlyOne(
                    lifecycle,
                    "fail_never_spawned_experiment_attempt");
            }
            std::cout << "SCHEDULER_INTERRUPTED_LAUNCH_RECONCILED"
                      << ",worker_attempt_id=" << attemptId
                      << ",result=never_spawned"
                      << std::endl;
            ++reconciled;
            continue;
        }

        const int pid = row[3].as<int>();
        const EA::GlobalExperimentControl::ProcessObservation
            observation = processes->Observe(pid);
        if (!observation.inspectionSucceeded)
        {
            transaction.exec_params(
                "UPDATE experiment_scheduler_worker_attempt SET "
                "lifecycle_state='identity_ambiguous',"
                "last_observed_at=clock_timestamp(),"
                "observed_by_scheduler_invocation_id=$1,"
                "diagnostic='process_identity_inspection_failed' "
                "WHERE worker_attempt_id=$2;",
                options.schedulerAuthority.schedulerInvocationId,
                attemptId);
            continue;
        }

        if (observation.exists)
        {
            bool identityMatches =
                !row[4].is_null() &&
                !row[5].is_null() &&
                !row[6].is_null() &&
                observation.pid == pid &&
                observation.processGroupId == row[4].as<int>() &&
                observation.processStartIdentity ==
                    row[5].as<std::string>() &&
                CanonicalizeObservedExecutable(
                    observation.executable) ==
                    row[6].as<std::string>();
            if (origin != "legacy_unverified")
            {
                identityMatches =
                    identityMatches &&
                    CommandHasExactOptionValue(
                        observation.commandLine,
                        "--scheduler-worker-attempt-id",
                        attemptId);
            }
            if (workerKind == "checkpoint_infer")
            {
                identityMatches =
                    identityMatches && checkpointEvalId &&
                    CommandHasExactToken(
                        observation.commandLine, "--infer") &&
                    CommandHasExactOptionValue(
                        observation.commandLine,
                        "--scheduler-checkpoint-eval-id",
                        *checkpointEvalId);
            }
            else if (phase == "train")
            {
                identityMatches =
                    identityMatches &&
                    CommandHasExactToken(
                        observation.commandLine, "--train") &&
                    CommandHasExactOptionValue(
                        observation.commandLine,
                        "--scheduler-experiment-id",
                        experimentId);
            }
            else if (phase == "infer")
            {
                identityMatches =
                    identityMatches &&
                    CommandHasExactToken(
                        observation.commandLine, "--infer") &&
                    CommandHasExactOptionValue(
                        observation.commandLine,
                        "--scheduler-experiment-id",
                        experimentId);
            }
            else if (phase == "analyze")
            {
                identityMatches =
                    identityMatches &&
                    CommandHasExactOptionValue(
                        observation.commandLine,
                        "--analyze-experiment",
                        experimentId);
            }

            transaction.exec_params(
                "UPDATE experiment_scheduler_worker_attempt SET "
                "lifecycle_state=$1,last_observed_at=clock_timestamp(),"
                "observed_by_scheduler_invocation_id=$2,"
                "reconciliation_result=$3,diagnostic=$4 "
                "WHERE worker_attempt_id=$5;",
                identityMatches ? "observed"
                                : "identity_ambiguous",
                options.schedulerAuthority.schedulerInvocationId,
                identityMatches ? "valid_process_observed"
                                : "identity_mismatch",
                identityMatches
                    ? "live_worker_observed_without_relaunch"
                    : "pid_reuse_or_worker_identity_mismatch",
                attemptId);
            std::cout
                << (identityMatches
                        ? "SCHEDULER_PRIOR_WORKER_OBSERVED"
                        : "SCHEDULER_WORKER_IDENTITY_AMBIGUOUS")
                << ",worker_attempt_id=" << attemptId
                << ",experiment_id=" << experimentId
                << ",pid=" << pid
                << ",capacity_consumed=1"
                << std::endl;
            continue;
        }

        // A missing process is destructive evidence only when the exact
        // durable attempt still owns the lifecycle row.
        bool lifecycleMatches = false;
        bool lifecycleAlreadyCompletedAnalyze = false;
        if (checkpointEvalId)
        {
            pqxx::result lifecycle = transaction.exec_params(
                "SELECT 1 FROM experiment_checkpoint_eval "
                "WHERE checkpoint_eval_id=$1 AND status='running' "
                "AND phase='infer' "
                "AND active_scheduler_worker_attempt_id=$2 "
                "FOR UPDATE;",
                *checkpointEvalId,
                attemptId);
            lifecycleMatches = lifecycle.size() == 1;
        }
        else
        {
            // Final analysis persists its durable result and advances the
            // experiment before the scheduler terminalizes the attempt.
            // Keep that exact bound crash window eligible for result recovery.
            pqxx::result lifecycle = transaction.exec_params(
                "SELECT status,phase FROM experiment "
                "WHERE experiment_id=$1 "
                "AND ((status='running' AND phase=$2) "
                " OR ($2='analyze' AND status='completed' "
                "     AND phase='done')) "
                "AND active_scheduler_worker_attempt_id=$3 "
                "FOR UPDATE;",
                experimentId,
                phase,
                attemptId);
            lifecycleMatches = lifecycle.size() == 1;
            lifecycleAlreadyCompletedAnalyze =
                lifecycleMatches &&
                lifecycle[0][0].as<std::string>() == "completed" &&
                lifecycle[0][1].as<std::string>() == "done";
        }
        if (!lifecycleMatches)
        {
            transaction.exec_params(
                "UPDATE experiment_scheduler_worker_attempt a SET "
                "lifecycle_state='failed',"
                "completed_at=clock_timestamp(),"
                "reconciliation_result='lifecycle_predicate_changed',"
                "diagnostic='process_missing_lifecycle_no_longer_owned' "
                "WHERE a.worker_attempt_id=$1 "
                "AND a.lifecycle_state IN "
                "('reserved','spawned','running','observed',"
                "'identity_ambiguous') "
                "AND NOT EXISTS (SELECT 1 FROM experiment e "
                " WHERE e.active_scheduler_worker_attempt_id="
                "a.worker_attempt_id) "
                "AND NOT EXISTS (SELECT 1 "
                " FROM experiment_checkpoint_eval ce "
                " WHERE ce.active_scheduler_worker_attempt_id="
                "a.worker_attempt_id);",
                attemptId);
            ++reconciled;
            continue;
        }

        bool completedEvidence = false;
        if (checkpointEvalId)
        {
            std::vector<CheckpointEvalRow> evaluations =
                LoadCheckpointEvalRows(
                    transaction, "running", "infer");
            const auto evaluation = std::find_if(
                evaluations.begin(),
                evaluations.end(),
                [&](const CheckpointEvalRow& value) {
                    return value.checkpointEvalId ==
                           *checkpointEvalId;
                });
            if (evaluation != evaluations.end())
            {
                const auto resultId =
                    FindCompletedCheckpointInferenceResultIdForAttempt(
                        transaction,
                        *evaluation,
                        attemptStartedEpoch);
                if (resultId)
                {
                    AdvanceCheckpointEvalToAnalyze(
                        transaction,
                        *evaluation,
                        *resultId,
                        ColumnExists(
                            transaction,
                            "experiment_checkpoint_eval",
                            "infer_completed_at"),
                        attemptId);
                    completedEvidence = true;
                }
            }
            if (!completedEvidence)
            {
                transaction.exec_params(
                    "UPDATE experiment_checkpoint_eval SET "
                    "status='failed',worker_pid=NULL,"
                    "worker_process_group_id=NULL,"
                    "completed_at=clock_timestamp(),"
                    "error_message='worker_process_missing_no_result',"
                    "updated_at=clock_timestamp() "
                    "WHERE checkpoint_eval_id=$1 "
                    "AND active_scheduler_worker_attempt_id=$2 "
                    "AND status='running' AND phase='infer';",
                    *checkpointEvalId,
                    attemptId);
            }
        }
        else
        {
            const bool forcedFinalInferenceRerun =
                phase == "infer" &&
                OperatorForcedFinalInferenceRerunRequested(
                    transaction, experimentId);
            pqxx::result experimentRows = transaction.exec_params(
                "SELECT experiment_id,symbol,prediction_horizon,"
                "c_next_threshold,core_lr_mult,head_lr_mult,"
                "target_epochs,checkpoint_interval,"
                "train_start::text,train_end::text,"
                "infer_start::text,infer_end::text,last_model_id,"
                "resume_model_id,train_log_path,infer_log_path,"
                "analysis_log_path,donchian20_mode,feature_warmup_scope,donchian_lookback,feature_ablation_mask,resume_expand_input_width,training_objective_canonical,training_objective_hash "
                "FROM experiment WHERE experiment_id=$1;",
                experimentId);
            if (experimentRows.size() == 1)
            {
                ExperimentRow experiment =
                    RowToExperiment(experimentRows[0]);
                if (phase == "infer" &&
                    HasCompletedInferenceResultForAttempt(
                        transaction,
                        experiment,
                        attemptStartedEpoch,
                        forcedFinalInferenceRerun))
                {
                    TransitionRecoveredInferenceToAnalyze(
                        transaction,
                        experiment,
                        "SCHEDULER_WORKER_RESULT_RECOVERED",
                        "completed_inference_result",
                        std::nullopt,
                        attemptId,
                        forcedFinalInferenceRerun);
                    completedEvidence = true;
                }
                else if (
                    phase == "analyze" &&
                    HasCompletedAnalysisResultForAttempt(
                        transaction,
                        experiment,
                        attemptStartedEpoch))
                {
                    if (!lifecycleAlreadyCompletedAnalyze)
                    {
                        MarkExperimentDone(
                            transaction,
                            experiment,
                            "analyze",
                            attemptId);
                    }
                    completedEvidence = true;
                }
                else if (phase == "train")
                {
                    const auto modelId =
                        FindLatestModelForExperimentSince(
                            transaction,
                            experimentId,
                            attemptStartedEpoch);
                    if (modelId)
                    {
                        completedEvidence =
                            RecoverTrainOrphanFromModel(
                                transaction,
                                experiment,
                                *modelId,
                                attemptId);
                    }
                }
            }
            if (!completedEvidence)
            {
                transaction.exec_params(
                    "UPDATE experiment SET status='failed',"
                    "worker_pid=NULL,worker_process_group_id=NULL,"
                    "completed_at=clock_timestamp(),exit_code=-1,"
                    "error_message=$4,"
                    "updated_at=clock_timestamp() "
                    "WHERE experiment_id=$1 "
                    "AND active_scheduler_worker_attempt_id=$2 "
                    "AND status='running' AND phase=$3;",
                    experimentId,
                    attemptId,
                    phase,
                    forcedFinalInferenceRerun
                        ? "forced_final_inference_rerun_missing_attempt_result;worker_process_missing_no_result"
                        : "worker_process_missing_no_result");
            }
        }

        pqxx::result terminal = transaction.exec_params(
            "UPDATE experiment_scheduler_worker_attempt a SET "
            "lifecycle_state=$1,completed_at=clock_timestamp(),"
            "last_observed_at=clock_timestamp(),"
            "observed_by_scheduler_invocation_id=$2,"
            "reconciliation_result=$3,diagnostic=$4 "
            "WHERE a.worker_attempt_id=$5 "
            "AND a.lifecycle_state IN "
            "('spawned','running','observed',"
            "'identity_ambiguous') "
            "AND EXISTS ("
            " SELECT 1 FROM experiment e "
            " WHERE $6::bigint IS NULL "
            " AND e.experiment_id=$7 "
            " AND e.active_scheduler_worker_attempt_id="
            "a.worker_attempt_id "
            " UNION ALL "
            " SELECT 1 FROM experiment_checkpoint_eval ce "
            " WHERE $6::bigint IS NOT NULL "
            " AND ce.checkpoint_eval_id=$6 "
            " AND ce.active_scheduler_worker_attempt_id="
            "a.worker_attempt_id"
            ") RETURNING a.worker_attempt_id;",
            completedEvidence ? "completed" : "failed",
            options.schedulerAuthority.schedulerInvocationId,
            completedEvidence
                ? "process_missing_result_recovered"
                : "process_missing_no_result",
            "exact_process_identity_absent",
            attemptId,
            checkpointEvalId,
            experimentId);
        EA::SchedulerOwnership::RequireAffectedExactlyOne(
            terminal,
            "terminalize_reconciled_exact_attempt");
        pqxx::result cleared;
        if (checkpointEvalId)
        {
            cleared = transaction.exec_params(
                "UPDATE experiment_checkpoint_eval SET "
                "active_scheduler_worker_attempt_id=NULL "
                "WHERE checkpoint_eval_id=$1 "
                "AND active_scheduler_worker_attempt_id=$2 "
                "RETURNING checkpoint_eval_id;",
                *checkpointEvalId,
                attemptId);
        }
        else
        {
            cleared = transaction.exec_params(
                "UPDATE experiment SET "
                "active_scheduler_worker_attempt_id=NULL "
                "WHERE experiment_id=$1 "
                "AND active_scheduler_worker_attempt_id=$2 "
                "RETURNING experiment_id;",
                experimentId,
                attemptId);
        }
        EA::SchedulerOwnership::RequireAffectedExactlyOne(
            cleared,
            "clear_reconciled_exact_attempt_binding");
        std::cout << "SCHEDULER_WORKER_RECONCILED"
                  << ",worker_attempt_id=" << attemptId
                  << ",experiment_id=" << experimentId
                  << ",result="
                  << (completedEvidence
                          ? "completed_evidence"
                          : "failed_no_result")
                  << std::endl;
        ++reconciled;
    }
    return reconciled;
}

[[maybe_unused]] void CompleteInferPhase(pqxx::work& w,
                               const ExperimentRow& experiment,
                               int exitCode,
                               const std::string& commandDisplay)
{
    if (!experiment.lastModelId.has_value())
    {
        MarkExperimentFailed(w, experiment, "infer_missing_last_model_id", -1);
        return;
    }

    if (exitCode == 0)
    {
        if (HasCompletedAnalysisResult(w, experiment))
        {
            std::cout << "SCHEDULER_SKIP_EXISTING_ANALYSIS"
                      << ",experiment_id=" << experiment.experimentId
                      << ",model_id=" << *experiment.lastModelId
                      << std::endl;
            MarkExperimentDone(w, experiment, "infer");
        }
        else
        {
            MarkExperimentPendingPhase(w, experiment, "infer", "analyze", exitCode);
            std::cout << "SCHEDULER_ENQUEUE_ANALYZE"
                      << ",experiment_id=" << experiment.experimentId
                      << ",model_id=" << *experiment.lastModelId
                      << std::endl;
        }
    }
    else
    {
        const std::string errorMessage =
            "infer_failed;exit_code=" + std::to_string(exitCode) +
            ";command=" + commandDisplay;
        MarkExperimentFailed(w, experiment, errorMessage, exitCode);
    }
}

const char* SchedulerSignalName(int signalNumber)
{
    switch (signalNumber)
    {
        case SIGHUP: return "SIGHUP";
        case SIGINT: return "SIGINT";
        case SIGQUIT: return "SIGQUIT";
        case SIGILL: return "SIGILL";
        case SIGABRT: return "SIGABRT";
        case SIGFPE: return "SIGFPE";
        case SIGKILL: return "SIGKILL";
        case SIGSEGV: return "SIGSEGV";
        case SIGPIPE: return "SIGPIPE";
        case SIGALRM: return "SIGALRM";
        case SIGTERM: return "SIGTERM";
#ifdef SIGBUS
        case SIGBUS: return "SIGBUS";
#endif
        default: return "UNKNOWN";
    }
}

std::string ObservedChildError(const SchedulerOwnedChild& child,
                               int exitCode,
                               const std::optional<int>& signalNumber,
                               bool coreDumped)
{
    std::ostringstream error;
    if (signalNumber.has_value())
    {
        error << "child_signal_" << *signalNumber
              << ";phase=" << child.phase
              << ";signal=" << *signalNumber
              << ";signal_name=" << SchedulerSignalName(*signalNumber)
              << ";core_dumped=" << (coreDumped ? 1 : 0);
    }
    else
    {
        error << "child_exit_code_" << exitCode
              << ";phase=" << child.phase
              << ";exit_code=" << exitCode;
    }
    return error.str();
}

void PersistObservedExitFields(pqxx::work& w,
                               const SchedulerOwnedChild& child,
                               int exitCode,
                               const std::string& error,
                               bool preserveSuccessState)
{
    pqxx::result updated = w.exec_params(
        "UPDATE experiment SET exit_code = $1, error_message = $2, worker_pid = NULL, updated_at = now() "
        "WHERE experiment_id = $3 AND (worker_pid = $4 OR worker_pid IS NULL) "
        "AND status <> 'running' "
        "AND active_scheduler_worker_attempt_id=$5 "
        "RETURNING experiment_id;",
        exitCode,
        preserveSuccessState && exitCode == 0 ? std::optional<std::string>{} : std::optional<std::string>{error},
        child.experimentId,
        static_cast<int>(child.pid),
        child.workerAttemptId);
    EA::SchedulerOwnership::RequireAffectedExactlyOne(
        updated, "persist_observed_exit_fields");
}

void PersistObservedExperimentChild(pqxx::work& w,
                                    const SchedulerOwnedChild& child,
                                    int exitCode,
                                    const std::optional<int>& signalNumber,
                                    bool coreDumped)
{
    pqxx::result rows = w.exec_params(
        "SELECT experiment_id, symbol, prediction_horizon, c_next_threshold, "
        "core_lr_mult, head_lr_mult, target_epochs, checkpoint_interval, "
        "train_start::text, train_end::text, infer_start::text, infer_end::text, "
        "last_model_id, resume_model_id, train_log_path, infer_log_path, analysis_log_path, "
        "e.donchian20_mode,e.feature_warmup_scope,e.donchian_lookback,e.feature_ablation_mask,e.resume_expand_input_width,e.training_objective_canonical,e.training_objective_hash,e.status,e.phase,e.worker_pid,e.cancellation_request_id,"
        "r.cancellation_mode,e.cancel_after_checkpoint_epoch "
        "FROM experiment e LEFT JOIN experiment_admin_request r "
        "ON r.request_id=e.cancellation_request_id "
        "WHERE e.experiment_id = $1 "
        "AND e.active_scheduler_worker_attempt_id=$2;",
        child.experimentId,
        child.workerAttemptId);
    if (rows.empty())
        return;

    ExperimentRow experiment = RowToExperiment(rows[0]);
    const std::string status = rows[0][24].as<std::string>();
    const std::string phase = rows[0][25].as<std::string>();
    const std::optional<int> workerPid = rows[0][26].is_null()
        ? std::nullopt
        : std::optional<int>{rows[0][26].as<int>()};
    const std::optional<long long> cancellationRequestId =
        rows[0][27].is_null()
            ? std::nullopt
            : std::optional<long long>{rows[0][27].as<long long>()};
    const std::optional<std::string> cancellationMode =
        rows[0][28].is_null()
            ? std::nullopt
            : std::optional<std::string>{rows[0][28].as<std::string>()};
    const std::optional<int> cancellationCheckpoint =
        rows[0][29].is_null()
            ? std::nullopt
            : std::optional<int>{rows[0][29].as<int>()};
    const std::string error = ObservedChildError(child, exitCode, signalNumber, coreDumped);

    if (status != "running" || phase != child.phase ||
        (workerPid.has_value() && *workerPid != child.pid))
    {
        PersistObservedExitFields(w, child, exitCode, error, true);
        std::cout << "SCHEDULER_CHILD_RESULT_ALREADY_PERSISTED"
                  << ",experiment_id=" << child.experimentId
                  << ",phase=" << child.phase
                  << ",pid=" << child.pid
                  << ",status=" << status
                  << ",database_phase=" << phase
                  << ",exit_code=" << exitCode
                  << std::endl;
        return;
    }

    if (cancellationRequestId)
    {
        if (cancellationMode == "after_next_checkpoint" &&
            child.phase == "train" && cancellationCheckpoint)
        {
            const std::optional<long long> restartModel =
                FindLatestModelForExperiment(w, child.experimentId);
            if (restartModel)
                w.exec_params(
                    "UPDATE experiment SET status='pending',phase='train',"
                    "worker_pid=NULL,worker_process_group_id=NULL,"
                    "worker_control_state='running',last_model_id=$1,"
                    "current_operation='train',"
                    "error_message=$2,updated_at=now() "
                    "WHERE experiment_id=$3 AND status='running' "
                    "AND phase='train' "
                    "AND active_scheduler_worker_attempt_id=$4;",
                    *restartModel,
                    error,
                    child.experimentId,
                    child.workerAttemptId);
            else
            {
                w.exec_params(
                    "UPDATE experiment SET status='cancelled',"
                    "worker_pid=NULL,worker_process_group_id=NULL,"
                    "completed_at=now(),cancellation_completed_at=now(),"
                    "error_message='cancelled_missing_worker_no_checkpoint',"
                    "updated_at=now() WHERE experiment_id=$1 "
                    "AND status='running' AND phase='train' "
                    "AND active_scheduler_worker_attempt_id=$2;",
                    child.experimentId,
                    child.workerAttemptId);
                w.exec_params(
                    "UPDATE experiment_admin_worker_outcome SET "
                    "outcome_status='partial',"
                    "detail='worker_exited_before_checkpoint_no_restart_model',"
                    "updated_at=now() WHERE request_id=$1 "
                    "AND experiment_id=$2 "
                    "AND outcome_status='pending_checkpoint';",
                    *cancellationRequestId,
                    child.experimentId);
            }
        }
        else
        {
            w.exec_params(
                "UPDATE experiment SET status='cancelled',"
                "worker_pid=NULL,worker_process_group_id=NULL,"
                "completed_at=COALESCE(completed_at,now()),"
                "cancellation_completed_at=now(),exit_code=$1,"
                "error_message='cancelled_by_global_request',updated_at=now() "
                "WHERE experiment_id=$2 AND status='running' "
                "AND phase=$3 "
                "AND active_scheduler_worker_attempt_id=$4;",
                exitCode,
                child.experimentId,
                child.phase,
                child.workerAttemptId);
        }
        return;
    }

    if (child.phase == "analyze" &&
        HasCompletedAnalysisResultForAttempt(
            w, experiment, child.launchedEpoch))
    {
        MarkExperimentDone(
            w, experiment, "analyze", child.workerAttemptId);
        PersistObservedExitFields(w, child, exitCode, error, true);
        return;
    }

    if (child.phase == "infer")
    {
        const bool forcedFinalInferenceRerun =
            OperatorForcedFinalInferenceRerunRequested(
                w, experiment.experimentId);
        if (HasCompletedInferenceResultForAttempt(
                w,
                experiment,
                child.launchedEpoch,
                forcedFinalInferenceRerun))
        {
            TransitionRecoveredInferenceToAnalyze(
                w,
                experiment,
                "SCHEDULER_CHILD_RESULT_PERSISTED",
                "completed_inference_eval_result",
                std::nullopt,
                child.workerAttemptId,
                forcedFinalInferenceRerun);
            PersistObservedExitFields(w, child, exitCode, error, true);
            return;
        }
        if (!forcedFinalInferenceRerun &&
            HasValidInferenceLogPathForAttempt(
                experiment, child.launchedEpoch))
        {
            TransitionRecoveredInferenceToAnalyze(
                w,
                experiment,
                "SCHEDULER_CHILD_RESULT_PERSISTED",
                "valid_infer_log_path",
                std::nullopt,
                child.workerAttemptId);
            PersistObservedExitFields(w, child, exitCode, error, true);
            return;
        }
        if (!forcedFinalInferenceRerun)
        {
            if (const std::optional<std::string> discoveredLog =
                DiscoverValidInferenceLogForAttempt(
                    experiment, child.launchedEpoch);
                discoveredLog.has_value())
            {
                TransitionRecoveredInferenceToAnalyze(
                    w,
                    experiment,
                    "SCHEDULER_CHILD_RESULT_PERSISTED",
                    "discovered_valid_infer_log",
                    discoveredLog,
                    child.workerAttemptId);
                PersistObservedExitFields(w, child, exitCode, error, true);
                return;
            }
        }
        if (forcedFinalInferenceRerun)
        {
            MarkExperimentFailed(
                w,
                experiment,
                "forced_final_inference_rerun_missing_attempt_result;" +
                    error,
                exitCode,
                child.workerAttemptId);
            return;
        }
    }

    if (child.phase == "train")
    {
        if (const std::optional<long long> modelId =
                FindLatestModelForExperimentSince(
                    w,
                    experiment.experimentId,
                    child.launchedEpoch);
            modelId.has_value() &&
            (!child.expectedModelId.has_value() || *modelId != *child.expectedModelId))
        {
            (void)TransitionAfterTrainModelAvailable(
                w,
                experiment,
                *modelId,
                exitCode,
                "train",
                child.workerAttemptId);
            PersistObservedExitFields(w, child, exitCode, error, true);
            return;
        }
    }

    MarkExperimentFailed(
        w, experiment, error, exitCode, child.workerAttemptId);
}

void AdvanceCheckpointEvalToAnalyze(pqxx::work& w,
                                    const CheckpointEvalRow& eval,
                                    long long inferenceResultId,
                                    bool hasInferCompletedAt,
                                    const std::optional<long long>&
                                        workerAttemptId);

void PersistObservedCheckpointChild(pqxx::work& w,
                                    const SchedulerOwnedChild& child,
                                    int exitCode,
                                    const std::optional<int>& signalNumber,
                                    bool coreDumped)
{
    if (!child.checkpointEvalId.has_value())
        return;
    const std::string error = ObservedChildError(child, exitCode, signalNumber, coreDumped);
    CheckpointEvalRow eval;
    eval.checkpointEvalId = *child.checkpointEvalId;
    eval.experiment.experimentId = child.experimentId;
    eval.checkpointModelId = child.expectedModelId.value_or(-1);
    const std::optional<long long> resultId =
        FindCompletedCheckpointInferenceResultIdForAttempt(
            w, eval, child.launchedEpoch);

    if (resultId.has_value())
    {
        const bool hasInferCompletedAt =
            ColumnExists(w, "experiment_checkpoint_eval", "infer_completed_at");
        pqxx::result cancellation = w.exec_params(
            "SELECT cancellation_request_id FROM experiment_checkpoint_eval "
            "WHERE checkpoint_eval_id=$1 "
            "AND active_scheduler_worker_attempt_id=$2;",
            *child.checkpointEvalId,
            child.workerAttemptId);
        if (!cancellation.empty() && !cancellation[0][0].is_null())
        {
            std::ostringstream sql;
            sql << "UPDATE experiment_checkpoint_eval SET status='completed',"
                << "phase='done',worker_pid=NULL,completed_at=now(),"
                << "updated_at=now(),error_message=NULL";
            if (hasInferCompletedAt)
                sql << ",infer_completed_at=now()";
            sql << " WHERE checkpoint_eval_id=$1 "
                << "AND active_scheduler_worker_attempt_id=$2 "
                << "RETURNING checkpoint_eval_id;";
            pqxx::result completed = w.exec_params(
                sql.str(),
                *child.checkpointEvalId,
                child.workerAttemptId);
            EA::SchedulerOwnership::RequireAffectedExactlyOne(
                completed,
                "complete_cancellation_checkpoint_exact_attempt");
        }
        else
        {
            AdvanceCheckpointEvalToAnalyze(
                w,
                eval,
                *resultId,
                hasInferCompletedAt,
                child.workerAttemptId);
        }
        if (exitCode != 0)
        {
            w.exec_params(
                "UPDATE experiment_checkpoint_eval SET error_message = $1, updated_at = now() "
                "WHERE checkpoint_eval_id = $2 "
                "AND active_scheduler_worker_attempt_id=$3;",
                error,
                *child.checkpointEvalId,
                child.workerAttemptId);
        }
        return;
    }
    w.exec_params(
        "UPDATE experiment_checkpoint_eval SET status = 'failed', worker_pid = NULL, completed_at = now(), "
        "updated_at = now(), error_message = $1 WHERE checkpoint_eval_id = $2 "
        "AND status = 'running' AND phase = 'infer' "
        "AND active_scheduler_worker_attempt_id=$3;",
        error,
        *child.checkpointEvalId,
        child.workerAttemptId);
}

void PersistUnexpectedChildStatus(pqxx::work& w,
                                  const SchedulerOwnedChild& child,
                                  int rawStatus)
{
    const std::string error =
        "child_abnormal_wait_status;phase=" + child.phase +
        ";raw_status=" + std::to_string(rawStatus);
    if (child.checkpointEvalId.has_value())
    {
        w.exec_params(
            "UPDATE experiment_checkpoint_eval SET status = 'failed', worker_pid = NULL, "
            "completed_at = now(), updated_at = now(), error_message = $1 "
            "WHERE checkpoint_eval_id = $2 AND status = 'running' "
            "AND phase='infer' "
            "AND active_scheduler_worker_attempt_id=$3;",
            error,
            *child.checkpointEvalId,
            child.workerAttemptId);
        return;
    }
    w.exec_params(
        "UPDATE experiment SET status = 'failed', exit_code = -1, error_message = $1, "
        "worker_pid = NULL, completed_at = now(), updated_at = now() "
        "WHERE experiment_id = $2 AND status = 'running' "
        "AND phase=$4 "
        "AND (worker_pid = $3 OR worker_pid IS NULL) "
        "AND active_scheduler_worker_attempt_id=$5;",
        error,
        child.experimentId,
        static_cast<int>(child.pid),
        child.phase,
        child.workerAttemptId);
}

void FinalizeObservedWorkerAttempt(
    pqxx::work& transaction,
    const SchedulerOwnedChild& child,
    const SchedulerOptions& options,
    int exitCode,
    const std::optional<int>& signalNumber,
    const std::string& diagnostic)
{
    if (!child.workerAttemptId)
        return;
    bool lifecycleFailed = true;
    if (child.checkpointEvalId)
    {
        pqxx::result lifecycle = transaction.exec_params(
            "SELECT status FROM experiment_checkpoint_eval "
            "WHERE checkpoint_eval_id=$1;",
            *child.checkpointEvalId);
        lifecycleFailed =
            lifecycle.size() != 1 ||
            lifecycle[0][0].as<std::string>() == "failed";
    }
    else
    {
        pqxx::result lifecycle = transaction.exec_params(
            "SELECT status FROM experiment WHERE experiment_id=$1;",
            child.experimentId);
        lifecycleFailed =
            lifecycle.size() != 1 ||
            lifecycle[0][0].as<std::string>() == "failed";
    }
    pqxx::result terminal = transaction.exec_params(
        "UPDATE experiment_scheduler_worker_attempt a SET "
        "lifecycle_state=$1,completed_at=clock_timestamp(),"
        "last_observed_at=clock_timestamp(),exit_code=$2,"
        "signal_number=$3,reconciliation_result='parent_observed_exit',"
        "diagnostic=$4 "
        "WHERE a.worker_attempt_id=$5 "
        "AND a.scheduler_invocation_id=$6 "
        "AND a.scheduler_fencing_token=$7 "
        "AND a.worker_pid=$8 "
        "AND a.lifecycle_state IN "
        "('spawned','running','observed') "
        "AND EXISTS ("
        " SELECT 1 FROM experiment e "
        " WHERE $9::bigint IS NULL "
        " AND e.experiment_id=$10 "
        " AND e.active_scheduler_worker_attempt_id="
        "a.worker_attempt_id "
        " UNION ALL "
        " SELECT 1 FROM experiment_checkpoint_eval ce "
        " WHERE $9::bigint IS NOT NULL "
        " AND ce.checkpoint_eval_id=$9 "
        " AND ce.active_scheduler_worker_attempt_id="
        "a.worker_attempt_id"
        ") RETURNING a.worker_attempt_id;",
        lifecycleFailed ? "failed" : "completed",
        exitCode,
        signalNumber,
        diagnostic,
        *child.workerAttemptId,
        options.schedulerAuthority.schedulerInvocationId,
        options.schedulerAuthority.fencingToken,
        static_cast<int>(child.pid),
        child.checkpointEvalId,
        child.experimentId);
    EA::SchedulerOwnership::RequireAffectedExactlyOne(
        terminal, "finalize_reaped_exact_worker_attempt");
    pqxx::result lifecycleCleared;
    if (child.checkpointEvalId)
    {
        lifecycleCleared = transaction.exec_params(
            "UPDATE experiment_checkpoint_eval SET "
            "active_scheduler_worker_attempt_id=NULL "
            "WHERE checkpoint_eval_id=$1 "
            "AND active_scheduler_worker_attempt_id=$2 "
            "RETURNING checkpoint_eval_id;",
            *child.checkpointEvalId,
            *child.workerAttemptId);
    }
    else
    {
        lifecycleCleared = transaction.exec_params(
            "UPDATE experiment SET "
            "active_scheduler_worker_attempt_id=NULL "
            "WHERE experiment_id=$1 "
            "AND active_scheduler_worker_attempt_id=$2 "
            "RETURNING experiment_id;",
            child.experimentId,
            *child.workerAttemptId);
    }
    EA::SchedulerOwnership::RequireAffectedExactlyOne(
        lifecycleCleared,
        "clear_reaped_exact_worker_attempt_binding");
}

bool ObserveTerminalCheckpointStopAttempt(
    pqxx::work& transaction,
    const SchedulerOwnedChild& child,
    const SchedulerOptions& options,
    const ObservedChildStatus& observed)
{
    if (!child.workerAttemptId ||
        child.checkpointEvalId ||
        child.phase != "train" ||
        (observed.kind != ChildStatusKind::Exited &&
         observed.kind != ChildStatusKind::Signaled))
    {
        return false;
    }

    EA::SchedulerOwnership::ExactAttemptExpectation expected;
    expected.workerAttemptId = *child.workerAttemptId;
    expected.experimentId = child.experimentId;
    expected.workerKind = "experiment";
    expected.lifecyclePhase = "train";
    expected.capacityClass = "train";
    expected.schedulerInvocationId =
        options.schedulerAuthority.schedulerInvocationId;
    expected.schedulerFencingToken =
        options.schedulerAuthority.fencingToken;
    expected.requireCompleteProcessIdentity = true;
    const auto terminal =
        EA::SchedulerOwnership::LockAndVerifyExactTerminalAttempt(
            transaction,
            expected,
            "completed",
            "checkpoint_stop_completed",
            true);
    if (!terminal ||
        terminal->workerPid !=
            std::optional<int>{static_cast<int>(child.pid)})
    {
        return false;
    }

    const int exitCode =
        observed.kind == ChildStatusKind::Exited
            ? observed.exitCode
            : 128 + observed.signalNumber;
    const std::optional<int> signalNumber =
        observed.kind == ChildStatusKind::Signaled
            ? std::optional<int>{observed.signalNumber}
            : std::nullopt;
    const pqxx::result updated = transaction.exec_params(
        "UPDATE experiment_scheduler_worker_attempt a SET "
        "last_observed_at=clock_timestamp(),"
        "observed_by_scheduler_invocation_id=$1,"
        "exit_code=COALESCE(exit_code,$2),"
        "signal_number=COALESCE(signal_number,$3) "
        "WHERE a.worker_attempt_id=$4 "
        "AND a.scheduler_invocation_id=$1 "
        "AND a.scheduler_fencing_token=$5 "
        "AND a.experiment_id=$6 "
        "AND a.checkpoint_eval_id IS NULL "
        "AND a.worker_kind='experiment' "
        "AND a.lifecycle_phase='train' "
        "AND a.capacity_class='train' "
        "AND a.worker_pid=$7 "
        "AND a.lifecycle_state='completed' "
        "AND a.reconciliation_result='checkpoint_stop_completed' "
        "AND (a.exit_code IS NULL OR a.exit_code=$2) "
        "AND (a.signal_number IS NULL "
        "OR a.signal_number IS NOT DISTINCT FROM $3) "
        "RETURNING a.worker_attempt_id;",
        options.schedulerAuthority.schedulerInvocationId,
        exitCode,
        signalNumber,
        *child.workerAttemptId,
        options.schedulerAuthority.fencingToken,
        child.experimentId,
        static_cast<int>(child.pid));
    EA::SchedulerOwnership::RequireAffectedExactlyOne(
        updated,
        "observe_terminal_checkpoint_stop_attempt_exit");
    std::cout << "SCHEDULER_CHECKPOINT_STOP_EXIT_OBSERVED"
              << ",experiment_id=" << child.experimentId
              << ",worker_attempt_id=" << *child.workerAttemptId
              << ",pid=" << child.pid
              << ",exit_code=" << exitCode
              << ",lifecycle_rows_affected=0"
              << std::endl;
    return true;
}

void InjectStaleReaperReplacementForTest(
    pqxx::work& transaction,
    const SchedulerOwnedChild& child,
    const SchedulerOptions& options)
{
    constexpr const char* boundary =
        "stale_reaper_before_exact_verification";
    if (!SchedulerAuthorityTestFailpointEnabled(boundary) ||
        !child.workerAttemptId)
    {
        return;
    }

    const char* replacementPidText = std::getenv(
        "EA_SCHEDULER_OWNERSHIP_TEST_REPLACEMENT_PID");
    if (!replacementPidText || !*replacementPidText)
        throw std::runtime_error(
            "stale_reaper_test_replacement_pid_missing");
    const int replacementPid = std::stoi(replacementPidText);
    std::unique_ptr<
        EA::GlobalExperimentControl::ProcessOperations> processes =
        EA::GlobalExperimentControl::CreateNativeProcessOperations();
    const auto replacementProcess =
        processes->Observe(replacementPid);
    const std::string replacementExecutable =
        CanonicalizeObservedExecutable(
            replacementProcess.executable);
    if (!replacementProcess.inspectionSucceeded ||
        !replacementProcess.exists ||
        replacementProcess.pid != replacementPid ||
        replacementProcess.processGroupId <= 0 ||
        replacementProcess.processStartIdentity.empty() ||
        replacementExecutable.empty() ||
        replacementProcess.commandLine.empty())
    {
        throw std::runtime_error(
            "stale_reaper_test_replacement_identity_incomplete");
    }

    RequireAndRefreshSchedulerAuthority(transaction, options);
    pqxx::result retired = transaction.exec_params(
        "UPDATE experiment_scheduler_worker_attempt a SET "
        "lifecycle_state='abandoned',"
        "completed_at=clock_timestamp(),"
        "reconciliation_result='test_stale_reaper_replaced',"
        "diagnostic=$1 "
        "WHERE a.worker_attempt_id=$2 "
        "AND a.scheduler_invocation_id=$3 "
        "AND a.scheduler_fencing_token=$4 "
        "AND a.lifecycle_state IN ('spawned','running','observed') "
        "AND EXISTS ("
        " SELECT 1 FROM experiment e "
        " WHERE $5::bigint IS NULL "
        " AND e.experiment_id=$6 "
        " AND e.active_scheduler_worker_attempt_id="
        "a.worker_attempt_id "
        " UNION ALL "
        " SELECT 1 FROM experiment_checkpoint_eval ce "
        " WHERE $5::bigint IS NOT NULL "
        " AND ce.checkpoint_eval_id=$5 "
        " AND ce.active_scheduler_worker_attempt_id="
        "a.worker_attempt_id"
        ") RETURNING a.worker_attempt_id;",
        boundary,
        *child.workerAttemptId,
        options.schedulerAuthority.schedulerInvocationId,
        options.schedulerAuthority.fencingToken,
        child.checkpointEvalId,
        child.experimentId);
    EA::SchedulerOwnership::RequireAffectedExactlyOne(
        retired, "test_retire_stale_reaper_attempt");

    pqxx::result replacement = transaction.exec_params(
        "INSERT INTO experiment_scheduler_worker_attempt("
        "launch_attempt_identity,scheduler_invocation_id,"
        "scheduler_fencing_token,experiment_id,checkpoint_eval_id,"
        "worker_kind,lifecycle_phase,capacity_class,"
        "ownership_origin,lifecycle_state,worker_pid,"
        "worker_process_group_id,worker_process_start_identity,"
        "canonical_executable_path,command_line,command_identity,"
        "reserved_at,spawned_at,last_observed_at,diagnostic"
        ") SELECT "
        "'test-stale-reaper-replacement-' || "
        "worker_attempt_id::text,"
        "$1,$2,experiment_id,checkpoint_eval_id,worker_kind,"
        "lifecycle_phase,capacity_class,ownership_origin,'spawned',"
        "$4,$5,$6,$7,$8,command_identity,clock_timestamp(),"
        "clock_timestamp(),clock_timestamp(),$3 "
        "FROM experiment_scheduler_worker_attempt "
        "WHERE worker_attempt_id=$9 "
        "RETURNING worker_attempt_id;",
        options.schedulerAuthority.schedulerInvocationId,
        options.schedulerAuthority.fencingToken,
        boundary,
        replacementPid,
        replacementProcess.processGroupId,
        replacementProcess.processStartIdentity,
        replacementExecutable,
        replacementProcess.commandLine,
        *child.workerAttemptId);
    EA::SchedulerOwnership::RequireAffectedExactlyOne(
        replacement, "test_create_stale_reaper_replacement");
    const long long replacementAttemptId =
        replacement[0][0].as<long long>();

    pqxx::result rebound;
    if (child.checkpointEvalId)
    {
        rebound = transaction.exec_params(
            "UPDATE experiment_checkpoint_eval SET "
            "active_scheduler_worker_attempt_id=$1 "
            "WHERE checkpoint_eval_id=$2 "
            "AND active_scheduler_worker_attempt_id=$3 "
            "RETURNING checkpoint_eval_id;",
            replacementAttemptId,
            *child.checkpointEvalId,
            *child.workerAttemptId);
    }
    else
    {
        rebound = transaction.exec_params(
            "UPDATE experiment SET "
            "active_scheduler_worker_attempt_id=$1 "
            "WHERE experiment_id=$2 "
            "AND active_scheduler_worker_attempt_id=$3 "
            "RETURNING experiment_id;",
            replacementAttemptId,
            child.experimentId,
            *child.workerAttemptId);
    }
    EA::SchedulerOwnership::RequireAffectedExactlyOne(
        rebound, "test_bind_stale_reaper_replacement");
}

void ReapSchedulerOwnedChildren(
    pqxx::work& w,
    const SchedulerOptions& options)
{
    for (auto it = gSchedulerOwnedChildren.begin(); it != gSchedulerOwnedChildren.end();)
    {
        SchedulerOwnedChild& child = it->second;
        if (!child.observedStatus.has_value())
        {
            const ObservedChildStatus observed = ObserveChildStatusNonBlocking(child.pid);
            if (observed.kind == ChildStatusKind::Running)
            {
                ++it;
                continue;
            }
            if (observed.kind == ChildStatusKind::WaitError)
            {
                std::cout << "SCHEDULER_CHILD_WAIT_ERROR"
                          << ",experiment_id=" << child.experimentId
                          << ",phase=" << child.phase
                          << ",operation=" << child.operation
                          << ",worker_pid=" << child.pid
                          << ",pid=" << child.pid
                          << ",errno=" << observed.errorNumber
                          << ",error=waitpid_failed"
                          << ",ownership=no_longer_owned"
                          << std::endl;
                it = gSchedulerOwnedChildren.erase(it);
                continue;
            }
            child.observedStatus = observed;
            MarkChildTerminationObserved(child.diagnosticState);
        }

        const ObservedChildStatus& observed = *child.observedStatus;
        if (!child.workerAttemptId)
        {
            std::cout << "SCHEDULER_STALE_CHILD_REAP_REJECTED"
                      << ",experiment_id=" << child.experimentId
                      << ",pid=" << child.pid
                      << ",reason=worker_attempt_id_missing"
                      << std::endl;
            it = gSchedulerOwnedChildren.erase(it);
            continue;
        }
        if (ObserveTerminalCheckpointStopAttempt(
                w, child, options, observed))
        {
            it = gSchedulerOwnedChildren.erase(it);
            continue;
        }
        InjectStaleReaperReplacementForTest(
            w, child, options);
        EA::SchedulerOwnership::ExactAttemptExpectation expected;
        expected.workerAttemptId = *child.workerAttemptId;
        expected.experimentId = child.experimentId;
        expected.checkpointEvalId = child.checkpointEvalId;
        expected.workerKind = child.checkpointEvalId
            ? "checkpoint_infer"
            : "experiment";
        expected.lifecyclePhase = child.checkpointEvalId
            ? "infer"
            : child.phase;
        expected.capacityClass = child.checkpointEvalId
            ? "infer"
            : child.phase;
        expected.schedulerInvocationId =
            options.schedulerAuthority.schedulerInvocationId;
        expected.schedulerFencingToken =
            options.schedulerAuthority.fencingToken;
        expected.requireCompleteProcessIdentity = true;
        expected.allowTerminalLifecycle = true;
        const auto exact =
            EA::SchedulerOwnership::LockAndVerifyExactActiveAttempt(
                w, expected, true);
        if (!exact ||
            exact->workerPid !=
                std::optional<int>{
                    static_cast<int>(child.pid)})
        {
            std::cout << "SCHEDULER_STALE_CHILD_REAP_REJECTED"
                      << ",experiment_id=" << child.experimentId
                      << ",worker_attempt_id="
                      << *child.workerAttemptId
                      << ",pid=" << child.pid
                      << ",reason=exact_active_attempt_changed"
                      << std::endl;
            if (SchedulerAuthorityTestFailpointEnabled(
                    "stale_reaper_before_exact_verification"))
            {
                gSchedulerStopRequested = 1;
            }
            it = gSchedulerOwnedChildren.erase(it);
            continue;
        }
        int exitCode = observed.exitCode;
        std::optional<int> signalNumber;
        const bool coreDumped = observed.coreDumped;
        if (observed.kind == ChildStatusKind::Exited)
        {
            if (MarkChildExitDiagnosticEmitted(child.diagnosticState))
            {
                std::cout << "SCHEDULER_CHILD_EXITED"
                          << ",experiment_id=" << child.experimentId
                          << ",worker_pid=" << child.pid
                          << ",pid=" << child.pid
                          << ",phase=" << child.phase
                          << ",operation=" << child.operation
                          << ",exit_code=" << exitCode
                          << std::endl;
            }
        }
        else if (observed.kind == ChildStatusKind::Signaled)
        {
            signalNumber = observed.signalNumber;
            if (MarkChildExitDiagnosticEmitted(child.diagnosticState))
            {
                std::cout << "SCHEDULER_CHILD_SIGNALED"
                          << ",experiment_id=" << child.experimentId
                          << ",worker_pid=" << child.pid
                          << ",pid=" << child.pid
                          << ",phase=" << child.phase
                          << ",operation=" << child.operation
                          << ",signal_number=" << *signalNumber
                          << ",signal=" << *signalNumber
                          << ",signal_name=" << SchedulerSignalName(*signalNumber)
                          << ",core_dumped=" << (coreDumped ? 1 : 0)
                          << std::endl;
            }
        }
        else
        {
            std::cout << "SCHEDULER_CHILD_WAIT_ERROR"
                      << ",experiment_id=" << child.experimentId
                      << ",phase=" << child.phase
                      << ",operation=" << child.operation
                      << ",worker_pid=" << child.pid
                      << ",pid=" << child.pid
                      << ",errno=0,error=unexpected_wait_status"
                      << ",raw_status=" << observed.rawStatus
                      << std::endl;
            PersistUnexpectedChildStatus(w, child, observed.rawStatus);
            FinalizeObservedWorkerAttempt(
                w,
                child,
                options,
                -1,
                std::nullopt,
                "unexpected_wait_status");
            it = gSchedulerOwnedChildren.erase(it);
            continue;
        }

        if (child.checkpointEvalId.has_value())
            PersistObservedCheckpointChild(w, child, exitCode, signalNumber, coreDumped);
        else
            PersistObservedExperimentChild(w, child, exitCode, signalNumber, coreDumped);
        FinalizeObservedWorkerAttempt(
            w,
            child,
            options,
            exitCode,
            signalNumber,
            observed.kind == ChildStatusKind::Exited
                ? "child_exited"
                : "child_signaled");
        it = gSchedulerOwnedChildren.erase(it);
    }
}

void BeginSchedulerPollLogging(SchedulerEventLogState* logState)
{
    if (logState == nullptr)
        return;
    logState->currentSkipKeys.clear();
    logState->currentRunningPresentKeys.clear();
}

void FinishSchedulerPollLogging(SchedulerEventLogState* logState)
{
    if (logState == nullptr)
        return;
    logState->previousSkipKeys = logState->currentSkipKeys;
    logState->previousRunningPresentKeys = logState->currentRunningPresentKeys;
}

[[maybe_unused]] int RunTrainJobsLegacy(const SchedulerOptions& options,
                 const QueueSnapshot& snapshot,
                 SchedulerEventLogState* logState,
                 bool cancellationOnly = false)
{
    pqxx::connection c{LstmDbConnectionString()};
    pqxx::work w{c};
    if (!options.dryRun)
        SetTransactionReadWrite(w);
    RequireAndRefreshSchedulerAuthority(w, options);
    if (!RequireSchedulerTables(w))
        return 1;
    if (!SchedulerLaunchAllowed(w, "train", false, cancellationOnly))
    {
        w.commit();
        return 0;
    }

    const std::vector<ExperimentRow> jobs =
        LoadPendingExperiments(w, "train", cancellationOnly);
    PhaseSchedulingStats stats;
    stats.phase = "train";
    stats.examined = static_cast<int>(jobs.size());
    stats.freeSlots = AvailableWorkerProcessSlots(
        options.maxTrainProcs,
        RunningCountForPhase(snapshot, "train"));
    int freeSlots = stats.freeSlots;
    int rc = 0;
    std::vector<pid_t> launchedInTransaction;

    EnsureLogDir(options.schedulerLogDir);
    for (const auto& job : jobs)
    {
        const std::optional<long long> resumeFrom =
            job.resumeModelId.has_value() ? job.resumeModelId : job.lastModelId;
        if (resumeFrom.has_value() && !ModelExists(w, *resumeFrom))
        {
            ++stats.skipped;
            LogSkip("train", job.experimentId, "model_not_found", logState, options.schedulerVerbose);
            if (!options.dryRun)
            {
                if (cancellationOnly)
                    MarkCancellationCheckpointRestartFailed(
                        w, job, "cancel_checkpoint_restart_model_not_found");
                else
                    MarkExperimentFailed(w, job, "train_model_not_found");
            }
            continue;
        }
        if (const auto discovered =
                DiscoverRunningProcessForExperiment(job, "train");
            discovered)
        {
            ++stats.skipped;
            LogSkip("train", job.experimentId, "already_running", logState, options.schedulerVerbose);
            if (!options.dryRun)
            {
                MarkExperimentRunning(w, job, "train", LogPathFor(options, job, "train"));
                PersistExperimentWorkerPid(
                    w,
                    job,
                    "train",
                    discovered->pid,
                    discovered->processGroupId,
                    discovered->executable,
                    discovered->command,
                    discovered->processStartIdentity);
                if (freeSlots > 0)
                    --freeSlots;
            }
            continue;
        }
        if (freeSlots <= 0)
        {
            ++stats.skipped;
            LogSkip("train", job.experimentId, "train_slots_full", logState, options.schedulerVerbose);
            continue;
        }

        const std::string logPath = LogPathFor(options, job, "train");
        const std::vector<std::string> command = BuildTrainCommand(options, job);
        const std::string commandDisplay = CommandForDisplay(command);
        if (options.dryRun)
        {
            std::cout << "EXPERIMENT_CHILD_COMMAND"
                      << ",experiment_id=" << job.experimentId
                      << ",phase=train"
                      << ",dry_run=1"
                      << ",argv=" << commandDisplay
                      << std::endl;
            --freeSlots;
            ++stats.launched;
            continue;
        }

        MarkExperimentRunning(w, job, "train", logPath);
        if (job.lastModelId.has_value() && !job.resumeModelId.has_value())
        {
            std::cout << "SCHEDULER_RESUME_FROM_LAST_MODEL"
                      << ",experiment_id=" << job.experimentId
                      << ",model_id=" << *job.lastModelId
                      << std::endl;
        }
        std::cout << "EXPERIMENT_STARTED"
                  << ",experiment_id=" << job.experimentId
                  << ",phase=train"
                  << std::endl;
        std::cout << "EXPERIMENT_CHILD_COMMAND"
                  << ",experiment_id=" << job.experimentId
                  << ",phase=train"
                  << ",argv=" << commandDisplay
                  << std::endl;
        PrintSchedulerExec(command);
        try
        {
            const pid_t pid = LaunchChildProcess(
                command, logPath, job.experimentId, "train", job.lastModelId);
            launchedInTransaction.push_back(pid);
            try
            {
                const std::string processStartIdentity =
                    RequireProcessStartIdentity(pid);
                PersistExperimentWorkerPid(
                    w, job, "train", pid, pid,
                    command.front(), commandDisplay,
                    processStartIdentity);
            }
            catch (const std::exception& e)
            {
                w.abort();
                TerminateUncommittedSchedulerChildren(
                    launchedInTransaction);
                std::cerr << "SCHEDULER_CHILD_PID_PERSIST_FAILED"
                          << ",experiment_id=" << job.experimentId
                          << ",worker_pid=" << pid
                          << ",phase=train"
                          << ",operation=train"
                          << ",error=" << e.what()
                          << std::endl;
                throw SchedulerPidPersistenceError{e.what()};
            }
            --freeSlots;
            ++stats.launched;
        }
        catch (const SchedulerPidPersistenceError&)
        {
            throw;
        }
        catch (const std::exception& e)
        {
            const int launchError = SchedulerChildLaunchErrorNumber(e);
            if (cancellationOnly)
                MarkCancellationCheckpointRestartFailed(
                    w,
                    job,
                    "cancel_checkpoint_restart_" +
                        SchedulerLaunchFailureError(launchError));
            else
                MarkExperimentFailed(
                    w, job, SchedulerLaunchFailureError(launchError));
            std::cout << "EXPERIMENT_FAILED"
                      << ",experiment_id=" << job.experimentId
                      << ",phase=train"
                      << ",error=train_launch_failed"
                      << std::endl;
            rc = 1;
        }
    }
    PrintPhaseSchedulingStats(stats, logState, options.schedulerVerbose);
    w.commit();
    return rc;
}

int CountRows(pqxx::work& w, const std::string& sql);

[[maybe_unused]] int RunInferJobsLegacy(const SchedulerOptions& options,
                 const QueueSnapshot& snapshot,
                 SchedulerEventLogState* logState)
{
    pqxx::connection c{LstmDbConnectionString()};
    pqxx::work w{c};
    if (!options.dryRun)
        SetTransactionReadWrite(w);
    RequireAndRefreshSchedulerAuthority(w, options);
    if (!RequireSchedulerTables(w))
        return 1;
    if (!SchedulerLaunchAllowed(w, "infer"))
    {
        w.commit();
        return 0;
    }

    const std::vector<ExperimentRow> jobs = LoadPendingExperiments(w, "infer");
    PhaseSchedulingStats stats;
    stats.phase = "infer";
    stats.examined = static_cast<int>(jobs.size());
    const int runningCheckpointInfer = CountRows(
        w,
        "SELECT count(*) FROM experiment_checkpoint_eval "
        "WHERE status='running' AND phase='infer';");
    stats.freeSlots = AvailableInferProcessSlots(
        options.maxInferProcs,
        RunningCountForPhase(snapshot, "infer"),
        runningCheckpointInfer);
    int freeSlots = stats.freeSlots;
    int rc = 0;
    std::vector<pid_t> launchedInTransaction;

    EnsureLogDir(options.schedulerLogDir);
    for (const auto& job : jobs)
    {
        if (!job.lastModelId.has_value())
        {
            ++stats.skipped;
            LogSkip("infer", job.experimentId, "missing_model", logState, options.schedulerVerbose);
            if (!options.dryRun)
                MarkExperimentFailed(w, job, "infer_missing_last_model_id");
            continue;
        }
        if (!ModelExists(w, *job.lastModelId))
        {
            ++stats.skipped;
            LogSkip("infer", job.experimentId, "model_not_found", logState, options.schedulerVerbose);
            if (!options.dryRun)
                MarkExperimentFailed(w, job, "infer_model_not_found");
            continue;
        }
        const bool forcedFinalInferenceRerun =
            OperatorForcedFinalInferenceRerunRequested(
                w, job.experimentId);
        if (!forcedFinalInferenceRerun &&
            HasCompletedInferenceResult(w, job))
        {
            ++stats.skipped;
            LogSkip("infer", job.experimentId, "existing_inference", logState, options.schedulerVerbose);
            if (!options.dryRun)
            {
                std::cout << "SCHEDULER_SKIP_EXISTING_INFERENCE"
                          << ",experiment_id=" << job.experimentId
                          << ",model_id=" << *job.lastModelId
                          << std::endl;
                if (HasCompletedAnalysisResult(w, job))
                {
                    std::cout << "SCHEDULER_SKIP_EXISTING_ANALYSIS"
                              << ",experiment_id=" << job.experimentId
                              << ",model_id=" << *job.lastModelId
                              << std::endl;
                    MarkExperimentDone(w, job, "infer");
                }
                else
                {
                    MarkExperimentPendingPhase(w, job, "infer", "analyze");
                    std::cout << "SCHEDULER_ENQUEUE_ANALYZE"
                              << ",experiment_id=" << job.experimentId
                              << ",model_id=" << *job.lastModelId
                              << std::endl;
                }
            }
            continue;
        }
        if (forcedFinalInferenceRerun)
        {
            std::cout
                << "SCHEDULER_FORCED_FINAL_INFERENCE_RERUN_DISPATCH"
                << ",experiment_id=" << job.experimentId
                << ",model_id=" << *job.lastModelId
                << std::endl;
        }
        if (!forcedFinalInferenceRerun &&
            HasValidInferenceLogPath(job))
        {
            ++stats.skipped;
            LogSkip("infer", job.experimentId, "valid_infer_log_path", logState, options.schedulerVerbose);
            if (!options.dryRun)
            {
                TransitionRecoveredInferenceToAnalyze(
                    w,
                    job,
                    "SCHEDULER_ORPHAN_RECOVERED_INFER_LOG",
                    "valid_infer_log_path");
            }
            continue;
        }
        if (!forcedFinalInferenceRerun)
        {
            if (const std::optional<std::string> discoveredLog =
                    DiscoverValidInferenceLog(job);
                discoveredLog.has_value())
            {
                ++stats.skipped;
                LogSkip("infer", job.experimentId, "discovered_valid_infer_log", logState, options.schedulerVerbose);
                if (!options.dryRun)
                {
                    TransitionRecoveredInferenceToAnalyze(
                        w,
                        job,
                        "SCHEDULER_ORPHAN_RECOVERED_INFER_LOG",
                        "discovered_valid_infer_log",
                        discoveredLog);
                }
                continue;
            }
        }
        if (const auto discovered =
                DiscoverRunningProcessForExperiment(job, "infer");
            discovered)
        {
            ++stats.skipped;
            LogSkip("infer", job.experimentId, "already_running", logState, options.schedulerVerbose);
            if (!options.dryRun)
            {
                MarkExperimentRunning(w, job, "infer", LogPathFor(options, job, "infer"));
                PersistExperimentWorkerPid(
                    w,
                    job,
                    "infer",
                    discovered->pid,
                    discovered->processGroupId,
                    discovered->executable,
                    discovered->command,
                    discovered->processStartIdentity);
                if (freeSlots > 0)
                    --freeSlots;
            }
            continue;
        }
        if (freeSlots <= 0)
        {
            ++stats.skipped;
            LogSkip("infer", job.experimentId, "infer_slots_full", logState, options.schedulerVerbose);
            continue;
        }

        const std::string logPath = LogPathFor(options, job, "infer");
        const std::vector<std::string> command = BuildInferCommand(options, job);
        const std::string commandDisplay = CommandForDisplay(command);
        if (options.dryRun)
        {
            std::cout << "EXPERIMENT_CHILD_COMMAND"
                      << ",experiment_id=" << job.experimentId
                      << ",phase=infer"
                      << ",dry_run=1"
                      << ",argv=" << commandDisplay
                      << std::endl;
            --freeSlots;
            ++stats.launched;
            continue;
        }

        MarkExperimentRunning(w, job, "infer", logPath);
        std::cout << "EXPERIMENT_STARTED"
                  << ",experiment_id=" << job.experimentId
                  << ",phase=infer"
                  << std::endl;
        std::cout << "EXPERIMENT_CHILD_COMMAND"
                  << ",experiment_id=" << job.experimentId
                  << ",phase=infer"
                  << ",argv=" << commandDisplay
                  << std::endl;
        PrintSchedulerExec(command);
        try
        {
            const pid_t pid = LaunchChildProcess(
                command, logPath, job.experimentId, "infer", job.lastModelId);
            launchedInTransaction.push_back(pid);
            try
            {
                const std::string processStartIdentity =
                    RequireProcessStartIdentity(pid);
                PersistExperimentWorkerPid(
                    w, job, "infer", pid, pid,
                    command.front(), commandDisplay,
                    processStartIdentity);
            }
            catch (const std::exception& e)
            {
                w.abort();
                TerminateUncommittedSchedulerChildren(
                    launchedInTransaction);
                std::cerr << "SCHEDULER_CHILD_PID_PERSIST_FAILED"
                          << ",experiment_id=" << job.experimentId
                          << ",worker_pid=" << pid
                          << ",phase=infer"
                          << ",operation=infer"
                          << ",error=" << e.what()
                          << std::endl;
                throw SchedulerPidPersistenceError{e.what()};
            }
            --freeSlots;
            ++stats.launched;
        }
        catch (const SchedulerPidPersistenceError&)
        {
            throw;
        }
        catch (const std::exception& e)
        {
            const int launchError = SchedulerChildLaunchErrorNumber(e);
            MarkExperimentFailed(
                w, job, SchedulerLaunchFailureError(launchError));
            std::cout << "EXPERIMENT_FAILED"
                      << ",experiment_id=" << job.experimentId
                      << ",phase=infer"
                      << ",error=infer_launch_failed"
                      << std::endl;
            rc = 1;
        }
    }
    PrintPhaseSchedulingStats(stats, logState, options.schedulerVerbose);
    w.commit();
    return rc;
}

[[maybe_unused]] int RunAnalyzeJobsLegacy(const SchedulerOptions& options,
                   const QueueSnapshot& snapshot,
                   SchedulerEventLogState* logState)
{
    pqxx::connection c{LstmDbConnectionString()};
    pqxx::work w{c};
    if (!options.dryRun)
        SetTransactionReadWrite(w);
    RequireAndRefreshSchedulerAuthority(w, options);
    if (!RequireSchedulerTables(w))
        return 1;
    if (!SchedulerLaunchAllowed(w, "analyze"))
    {
        w.commit();
        return 0;
    }

    const std::vector<ExperimentRow> jobs = LoadPendingExperiments(w, "analyze");
    PhaseSchedulingStats stats;
    stats.phase = "analyze";
    stats.examined = static_cast<int>(jobs.size());
    stats.freeSlots = AvailableWorkerProcessSlots(
        options.maxAnalyzeProcs,
        RunningCountForPhase(snapshot, "analyze"));
    int freeSlots = stats.freeSlots;
    int rc = 0;
    std::vector<pid_t> launchedInTransaction;
    bool reportsNeeded = false;

    EnsureLogDir(options.schedulerLogDir);
    for (const auto& job : jobs)
    {
        if (!job.lastModelId.has_value())
        {
            ++stats.skipped;
            LogSkip("analyze", job.experimentId, "missing_model", logState, options.schedulerVerbose);
            if (!options.dryRun)
                MarkAnalyzeFailed(w, job.experimentId, "analyze_missing_last_model_id");
            continue;
        }
        if (!ModelExists(w, *job.lastModelId))
        {
            ++stats.skipped;
            LogSkip("analyze", job.experimentId, "model_not_found", logState, options.schedulerVerbose);
            if (!options.dryRun)
                MarkAnalyzeFailed(w, job.experimentId, "analyze_model_not_found");
            continue;
        }
        if (HasCompletedAnalysisResult(w, job))
        {
            ++stats.skipped;
            LogSkip("analyze", job.experimentId, "existing_analysis", logState, options.schedulerVerbose);
            if (!options.dryRun)
            {
                std::cout << "SCHEDULER_SKIP_EXISTING_ANALYSIS"
                          << ",experiment_id=" << job.experimentId
                          << ",model_id=" << *job.lastModelId
                          << std::endl;
                MarkExperimentDone(w, job, "analyze");
                reportsNeeded = true;
            }
            continue;
        }
        if (!HasCompletedInferenceResult(w, job) && !HasValidInferenceLogPath(job))
        {
            ++stats.skipped;
            LogSkip("analyze", job.experimentId, "infer_log_missing", logState, options.schedulerVerbose);
            continue;
        }
        if (const auto discovered =
                DiscoverRunningProcessForExperiment(job, "analyze");
            discovered)
        {
            ++stats.skipped;
            LogSkip("analyze", job.experimentId, "already_running", logState, options.schedulerVerbose);
            if (!options.dryRun)
            {
                MarkExperimentRunning(w, job, "analyze", LogPathFor(options, job, "analysis"));
                PersistExperimentWorkerPid(
                    w,
                    job,
                    "analyze",
                    discovered->pid,
                    discovered->processGroupId,
                    discovered->executable,
                    discovered->command,
                    discovered->processStartIdentity);
                if (freeSlots > 0)
                    --freeSlots;
            }
            continue;
        }
        if (freeSlots <= 0)
        {
            ++stats.skipped;
            LogSkip("analyze", job.experimentId, "analyze_slots_full", logState, options.schedulerVerbose);
            continue;
        }

        const std::string logPath = LogPathFor(options, job, "analysis");
        const std::vector<std::string> command = BuildAnalyzeCommand(options, job);
        const std::string commandDisplay = CommandForDisplay(command);
        if (options.dryRun)
        {
            std::cout << "EXPERIMENT_ANALYSIS_STARTED"
                      << ",experiment_id=" << job.experimentId
                      << ",dry_run=1"
                      << std::endl;
            std::cout << "EXPERIMENT_CHILD_COMMAND"
                      << ",experiment_id=" << job.experimentId
                      << ",phase=analyze"
                      << ",dry_run=1"
                      << ",argv=" << commandDisplay
                      << std::endl;
            --freeSlots;
            ++stats.launched;
            continue;
        }

        MarkExperimentRunning(w, job, "analyze", logPath);
        std::cout << "EXPERIMENT_STARTED"
                  << ",experiment_id=" << job.experimentId
                  << ",phase=analyze"
                  << std::endl;
        std::cout << "EXPERIMENT_CHILD_COMMAND"
                  << ",experiment_id=" << job.experimentId
                  << ",phase=analyze"
                  << ",argv=" << commandDisplay
                  << std::endl;
        PrintSchedulerExec(command);
        try
        {
            const pid_t pid = LaunchChildProcess(
                command, logPath, job.experimentId, "analyze", job.lastModelId);
            launchedInTransaction.push_back(pid);
            try
            {
                const std::string processStartIdentity =
                    RequireProcessStartIdentity(pid);
                PersistExperimentWorkerPid(
                    w, job, "analyze", pid, pid,
                    command.front(), commandDisplay,
                    processStartIdentity);
            }
            catch (const std::exception& e)
            {
                w.abort();
                TerminateUncommittedSchedulerChildren(
                    launchedInTransaction);
                std::cerr << "SCHEDULER_CHILD_PID_PERSIST_FAILED"
                          << ",experiment_id=" << job.experimentId
                          << ",worker_pid=" << pid
                          << ",phase=analyze"
                          << ",operation=analyze"
                          << ",error=" << e.what()
                          << std::endl;
                throw SchedulerPidPersistenceError{e.what()};
            }
            --freeSlots;
            ++stats.launched;
        }
        catch (const SchedulerPidPersistenceError&)
        {
            throw;
        }
        catch (const std::exception& e)
        {
            const int launchError = SchedulerChildLaunchErrorNumber(e);
            MarkAnalyzeFailed(
                w, job.experimentId, SchedulerLaunchFailureError(launchError));
            std::cout << "EXPERIMENT_FAILED"
                      << ",experiment_id=" << job.experimentId
                      << ",phase=analyze"
                      << ",error=analyze_launch_failed"
                      << std::endl;
            rc = 1;
        }
    }
    PrintPhaseSchedulingStats(stats, logState, options.schedulerVerbose);
    w.commit();
    if (reportsNeeded)
        TryGenerateExperimentReports(options);
    return rc;
}

bool SchedulerPidStillExists(std::optional<int> pid)
{
    if (!pid.has_value() || *pid <= 0)
        return false;
    if (::kill(static_cast<pid_t>(*pid), 0) == 0)
        return true;
    return errno == EPERM;
}

int CountRows(pqxx::work& w, const std::string& sql)
{
    return w.exec(sql).one_row()[0].as<int>();
}

void LogCheckpointEvalInferenceResultFound(const CheckpointEvalRow& eval,
                                           long long inferenceResultId)
{
    std::cout << "CHECKPOINT_EVAL_INFER_RESULT_FOUND"
              << ",checkpoint_eval_id=" << eval.checkpointEvalId
              << ",parent_experiment_id=" << eval.experiment.experimentId
              << ",checkpoint_model_id=" << eval.checkpointModelId
              << ",checkpoint_epoch=" << eval.checkpointEpoch
              << ",model_id=" << eval.checkpointModelId
              << ",inference_scope=checkpoint"
              << ",status=completed"
              << ",inference_result_id=" << inferenceResultId
              << std::endl;
}

void AdvanceCheckpointEvalToAnalyze(pqxx::work& w,
                                    const CheckpointEvalRow& eval,
                                    long long inferenceResultId,
                                    bool hasInferCompletedAt,
                                    const std::optional<long long>&
                                        workerAttemptId)
{
    LogCheckpointEvalInferenceResultFound(eval, inferenceResultId);
    std::ostringstream sql;
    sql << "UPDATE experiment_checkpoint_eval "
        << "SET status = 'pending', phase = 'analyze', worker_pid = NULL, "
        << "completed_at = NULL, error_message = NULL, updated_at = now()";
    if (hasInferCompletedAt)
        sql << ", infer_completed_at = COALESCE(infer_completed_at, now())";
    sql << " WHERE checkpoint_eval_id = $1 "
        << "AND ($2::bigint IS NULL OR "
        << "active_scheduler_worker_attempt_id=$2) "
        << "RETURNING checkpoint_eval_id;";
    pqxx::result updated = w.exec_params(
        sql.str(), eval.checkpointEvalId, workerAttemptId);
    if (workerAttemptId)
        EA::SchedulerOwnership::RequireAffectedExactlyOne(
            updated, "advance_checkpoint_exact_attempt_to_analyze");

    std::cout << "CHECKPOINT_EVAL_ADVANCED_TO_ANALYZE"
              << ",checkpoint_eval_id=" << eval.checkpointEvalId
              << ",parent_experiment_id=" << eval.experiment.experimentId
              << ",checkpoint_model_id=" << eval.checkpointModelId
              << ",checkpoint_epoch=" << eval.checkpointEpoch
              << ",model_id=" << eval.checkpointModelId
              << ",inference_scope=checkpoint"
              << ",status=pending"
              << ",inference_result_id=" << inferenceResultId
              << std::endl;
}

void LogCheckpointEvalInferenceResultMissing(const CheckpointEvalRow& eval,
                                             const std::string& error)
{
    std::cout << "CHECKPOINT_EVAL_INFER_RESULT_MISSING"
              << ",checkpoint_eval_id=" << eval.checkpointEvalId
              << ",parent_experiment_id=" << eval.experiment.experimentId
              << ",checkpoint_model_id=" << eval.checkpointModelId
              << ",checkpoint_epoch=" << eval.checkpointEpoch
              << ",model_id=" << eval.checkpointModelId
              << ",inference_scope=checkpoint"
              << ",status=missing"
              << ",error=" << error
              << std::endl;
}

[[maybe_unused]] int RunCheckpointEvalInferJobsLegacy(
    const SchedulerOptions& options)
{
    pqxx::connection c{LstmDbConnectionString()};
    pqxx::work w{c};
    if (!options.dryRun)
        SetTransactionReadWrite(w);
    RequireAndRefreshSchedulerAuthority(w, options);
    if (!CheckpointEvalTableExists(w))
        return 0;
    const auto control = LoadLockedGlobalControl(w);
    if (!control)
        return 1;
    const bool normalScheduling =
        EA::GlobalExperimentControl::NormalSchedulingAllowed(*control);
    const bool cancellationInference =
        EA::GlobalExperimentControl::CancellationInferenceAllowed(*control);
    if (!normalScheduling && !cancellationInference)
    {
        std::cout << "SCHEDULER_GLOBAL_CONTROL_BLOCK"
                  << ",phase=checkpoint_infer"
                  << ",desired_state=" << control->desiredState
                  << ",active_request_id="
                  << (control->activeRequestId
                          ? std::to_string(*control->activeRequestId)
                          : "NULL")
                  << std::endl;
        w.commit();
        return 0;
    }
    const bool hasInferStartedAt = ColumnExists(w, "experiment_checkpoint_eval", "infer_started_at");
    const bool hasInferCompletedAt = ColumnExists(w, "experiment_checkpoint_eval", "infer_completed_at");

    int rc = 0;
    std::vector<pid_t> launchedInTransaction;
    for (const auto& eval : LoadCheckpointEvalRows(w, "running", "infer"))
    {
        if (cancellationInference &&
            eval.cancellationRequestId != control->activeRequestId)
            continue;
        if (SchedulerPidStillExists(eval.workerPid))
            continue;
        const std::optional<long long> inferenceResultId =
            FindCompletedCheckpointInferenceResultIdForAttempt(
                w, eval, eval.inferStartedEpoch);
        if (inferenceResultId.has_value())
        {
            if (eval.cancellationRequestId)
            {
                std::ostringstream sql;
                sql << "UPDATE experiment_checkpoint_eval SET "
                    << "status='completed',phase='done',worker_pid=NULL,"
                    << "completed_at=now(),updated_at=now(),error_message=NULL";
                if (hasInferCompletedAt)
                    sql << ",infer_completed_at=now()";
                sql << " WHERE checkpoint_eval_id=$1;";
                w.exec_params(sql.str(), eval.checkpointEvalId);
            }
            else
            {
                AdvanceCheckpointEvalToAnalyze(
                    w, eval, *inferenceResultId, hasInferCompletedAt);
            }
        }
        else
        {
            LogCheckpointEvalInferenceResultMissing(
                eval,
                "infer_worker_exited_without_completed_result");
            w.exec_params(
                "UPDATE experiment_checkpoint_eval "
                "SET status = 'failed', worker_pid = NULL, completed_at = now(), updated_at = now(), "
                "error_message = 'infer_worker_exited_without_completed_result' "
                "WHERE checkpoint_eval_id = $1;",
                eval.checkpointEvalId);
            std::cout << "CHECKPOINT_EVAL_FAILED"
                      << " experiment_id=" << eval.experiment.experimentId
                      << " phase=infer"
                      << " epoch=" << eval.checkpointEpoch
                      << " model_id=" << eval.checkpointModelId
                      << " error=infer_worker_exited_without_completed_result"
                      << std::endl;
        }
    }

    const int pendingFinalInfer = CountRows(w, "SELECT count(*) FROM experiment WHERE status = 'pending' AND phase = 'infer';");
    if (pendingFinalInfer > 0)
    {
        w.commit();
        return 0;
    }

    const int runningFinalInfer = CountRows(w, "SELECT count(*) FROM experiment WHERE status = 'running' AND phase = 'infer';");
    const int runningCheckpointInfer = CountRows(w, "SELECT count(*) FROM experiment_checkpoint_eval WHERE status = 'running' AND phase = 'infer';");
    int freeSlots = AvailableInferProcessSlots(
        options.maxInferProcs,
        runningFinalInfer,
        runningCheckpointInfer);
    if (freeSlots <= 0)
    {
        w.commit();
        return 0;
    }

    EnsureLogDir(options.schedulerLogDir);
    for (const auto& eval : LoadCheckpointEvalRows(w, "pending", "infer"))
    {
        if (cancellationInference &&
            eval.cancellationRequestId != control->activeRequestId)
            continue;
        if (freeSlots <= 0)
            break;
        if (!eval.experiment.inferStart.has_value() || !eval.experiment.inferEnd.has_value())
        {
            w.exec_params(
                "UPDATE experiment_checkpoint_eval "
                "SET status = CASE WHEN cancellation_request_id IS NOT NULL "
                "THEN 'failed' ELSE 'skipped' END,completed_at=now(),"
                "updated_at=now(),error_message='missing_infer_range' "
                "WHERE checkpoint_eval_id = $1;",
                eval.checkpointEvalId);
            std::cout << "CHECKPOINT_EVAL_SKIPPED"
                      << " experiment_id=" << eval.experiment.experimentId
                      << " epoch=" << eval.checkpointEpoch
                      << " reason=missing_infer_range"
                      << std::endl;
            continue;
        }
        const std::optional<long long> inferenceResultId =
            FindCompletedCheckpointInferenceResultId(w, eval);
        if (inferenceResultId.has_value())
        {
            if (eval.cancellationRequestId)
            {
                std::ostringstream sql;
                sql << "UPDATE experiment_checkpoint_eval SET "
                    << "status='completed',phase='done',worker_pid=NULL,"
                    << "completed_at=now(),updated_at=now(),error_message=NULL";
                if (hasInferCompletedAt)
                    sql << ",infer_completed_at=now()";
                sql << " WHERE checkpoint_eval_id=$1;";
                w.exec_params(sql.str(), eval.checkpointEvalId);
            }
            else
            {
                AdvanceCheckpointEvalToAnalyze(
                    w, eval, *inferenceResultId, hasInferCompletedAt);
            }
            continue;
        }

        const std::string logPath = CheckpointEvalLogPathFor(options, eval, "infer");
        const std::vector<std::string> command = BuildCheckpointEvalInferCommand(options, eval);
        const std::string commandDisplay = CommandForDisplay(command);
        if (options.dryRun)
        {
            std::cout << "CHECKPOINT_EVAL_STARTED"
                      << " experiment_id=" << eval.experiment.experimentId
                      << " phase=infer"
                      << " epoch=" << eval.checkpointEpoch
                      << " model_id=" << eval.checkpointModelId
                      << " dry_run=1"
                      << std::endl;
            std::cout << "EXPERIMENT_CHILD_COMMAND"
                      << ",experiment_id=" << eval.experiment.experimentId
                      << ",phase=checkpoint_infer"
                      << ",dry_run=1"
                      << ",argv=" << commandDisplay
                      << std::endl;
            --freeSlots;
            continue;
        }

        pid_t pid = -1;
        try
        {
            pid = LaunchChildProcess(
                command,
                logPath,
                eval.experiment.experimentId,
                "checkpoint_infer",
                eval.checkpointModelId,
                eval.checkpointEvalId);
            launchedInTransaction.push_back(pid);
        }
        catch (const std::exception& e)
        {
            const int launchError = SchedulerChildLaunchErrorNumber(e);
            w.exec_params(
                "UPDATE experiment_checkpoint_eval "
                "SET status = 'failed', completed_at = now(), updated_at = now(), error_message = $1 "
                "WHERE checkpoint_eval_id = $2;",
                SchedulerLaunchFailureError(launchError),
                eval.checkpointEvalId);
            std::cout << "CHECKPOINT_EVAL_FAILED"
                      << " experiment_id=" << eval.experiment.experimentId
                      << " phase=infer"
                      << " epoch=" << eval.checkpointEpoch
                      << " model_id=" << eval.checkpointModelId
                      << " error=infer_launch_failed"
                      << std::endl;
            rc = 1;
            continue;
        }

        std::ostringstream sql;
        sql << "UPDATE experiment_checkpoint_eval "
            << "SET status = 'running', phase = 'infer', worker_pid = $1, "
            << "worker_process_group_id = $1, worker_executable = $2, "
            << "worker_command_line = $3, worker_process_start_identity = $4, "
            << "worker_control_state = 'running', infer_log_path = $5, "
            << "started_at = COALESCE(started_at, now()), updated_at = now(), error_message = NULL";
        if (hasInferStartedAt)
            sql << ", infer_started_at = COALESCE(infer_started_at, now())";
        sql << " WHERE checkpoint_eval_id = $6;";
        try
        {
            const std::string processStartIdentity =
                RequireProcessStartIdentity(pid);
            w.exec_params(sql.str(),
                          static_cast<int>(pid),
                          command.front(),
                          commandDisplay,
                          processStartIdentity,
                          logPath,
                          eval.checkpointEvalId);
        }
        catch (const std::exception& e)
        {
            w.abort();
            TerminateUncommittedSchedulerChildren(
                launchedInTransaction);
            std::cerr << "SCHEDULER_CHILD_PID_PERSIST_FAILED"
                      << ",experiment_id=" << eval.experiment.experimentId
                      << ",checkpoint_eval_id=" << eval.checkpointEvalId
                      << ",worker_pid=" << pid
                      << ",phase=checkpoint_infer"
                      << ",operation=checkpoint_infer"
                      << ",child_termination_requested="
                      << "1"
                      << ",error=" << e.what()
                      << std::endl;
            throw;
        }
        std::cout << "CHECKPOINT_EVAL_STARTED"
                  << " experiment_id=" << eval.experiment.experimentId
                  << " phase=infer"
                  << " epoch=" << eval.checkpointEpoch
                  << " model_id=" << eval.checkpointModelId
                  << std::endl;
        PrintSchedulerExec(command);
        --freeSlots;
    }
    w.commit();
    return rc;
}

struct ClaimedCheckpointAnalysis
{
    CheckpointEvalRow evaluation;
    long long workerAttemptId = -1;
    std::string launchAttemptIdentity;
};

struct CheckpointAnalysisWorkResult
{
    bool success = false;
    std::string error;
    long long inferenceResultId = -1;
    ParsedMetrics metrics;
    std::optional<double> leaderScore;
};

std::optional<ClaimedCheckpointAnalysis>
ClaimCheckpointAnalysis(
    const SchedulerOptions& options)
{
    pqxx::connection connection{LstmDbConnectionString()};
    pqxx::work transaction{connection};
    SetTransactionReadWrite(transaction);
    RequireAndRefreshSchedulerAuthority(transaction, options);
    if (!CheckpointEvalTableExists(transaction) ||
        !SchedulerLaunchAllowed(
            transaction, "checkpoint_analyze"))
    {
        transaction.commit();
        return std::nullopt;
    }
    if (!SchedulerWorkerCapacityHasSlot(
            options.maxAnalyzeProcs,
            CountGlobalWorkerCapacity(transaction, "analyze")))
    {
        transaction.commit();
        return std::nullopt;
    }
    const int pendingFinalAnalyze = CountRows(
        transaction,
        "SELECT count(*) FROM experiment "
        "WHERE status='pending' AND phase='analyze';");
    if (pendingFinalAnalyze > 0)
    {
        transaction.commit();
        return std::nullopt;
    }

    std::vector<CheckpointEvalRow> pending =
        LoadCheckpointEvalRows(
            transaction, "pending", "analyze");
    if (pending.empty())
    {
        transaction.commit();
        return std::nullopt;
    }
    ClaimedCheckpointAnalysis claim;
    claim.evaluation = pending.front();
    claim.launchAttemptIdentity =
        GenerateWorkerLaunchIdentity(
            options,
            "checkpoint_analyze:" +
                std::to_string(
                    claim.evaluation.checkpointEvalId));
    pqxx::result inserted = transaction.exec_params(
        "INSERT INTO experiment_scheduler_worker_attempt("
        "launch_attempt_identity,scheduler_invocation_id,"
        "scheduler_fencing_token,experiment_id,checkpoint_eval_id,"
        "worker_kind,lifecycle_phase,capacity_class,"
        "ownership_origin,lifecycle_state,"
        "canonical_executable_path,command_line,"
        "command_identity) "
        "VALUES($1,$2,$3,$4,$5,'checkpoint_analyze',"
        "'analyze','analyze','scheduler_in_process','running',"
        "$6,$7,$8) RETURNING worker_attempt_id;",
        claim.launchAttemptIdentity,
        options.schedulerAuthority.schedulerInvocationId,
        options.schedulerAuthority.fencingToken,
        claim.evaluation.experiment.experimentId,
        claim.evaluation.checkpointEvalId,
        options.selfPath,
        options.invocationCommandLine,
        "checkpoint_analyze:" +
            std::to_string(
                claim.evaluation.checkpointEvalId));
    EA::SchedulerOwnership::RequireAffectedExactlyOne(
        inserted, "reserve_checkpoint_analysis_attempt");
    claim.workerAttemptId =
        inserted[0][0].as<long long>();

    std::ostringstream claimSql;
    claimSql
        << "UPDATE experiment_checkpoint_eval SET "
        << "status='running',phase='analyze',"
        << "active_scheduler_worker_attempt_id=$1,"
        << "worker_pid=NULL,worker_process_group_id=NULL,"
        << "worker_process_start_identity=NULL,"
        << "worker_executable=$2,worker_command_line=$3,"
        << "updated_at=clock_timestamp(),error_message=NULL";
    if (ColumnExists(
            transaction,
            "experiment_checkpoint_eval",
            "analyze_started_at"))
    {
        claimSql
            << ",analyze_started_at="
            << "COALESCE(analyze_started_at,clock_timestamp())";
    }
    claimSql
        << " WHERE checkpoint_eval_id=$4 "
        << "AND status='pending' AND phase='analyze' "
        << "AND active_scheduler_worker_attempt_id IS NULL "
        << "RETURNING checkpoint_eval_id;";
    pqxx::result lifecycle = transaction.exec_params(
        claimSql.str(),
        claim.workerAttemptId,
        options.selfPath,
        options.invocationCommandLine,
        claim.evaluation.checkpointEvalId);
    EA::SchedulerOwnership::RequireAffectedExactlyOne(
        lifecycle, "claim_checkpoint_analysis_lifecycle");
    RequireAndRefreshSchedulerAuthority(
        transaction, options);
    transaction.commit();
    std::cout << "CHECKPOINT_ANALYSIS_CLAIMED"
              << ",checkpoint_eval_id="
              << claim.evaluation.checkpointEvalId
              << ",worker_attempt_id="
              << claim.workerAttemptId
              << ",capacity_class=analyze"
              << std::endl;
    return claim;
}

CheckpointAnalysisWorkResult ExecuteCheckpointAnalysisWork(
    const ClaimedCheckpointAnalysis& claim)
{
    CheckpointAnalysisWorkResult result;
    try
    {
        pqxx::connection connection{LstmDbConnectionString()};
        pqxx::work transaction{connection};
        SetTransactionReadOnly(transaction);
        std::vector<CheckpointEvalRow> running =
            LoadCheckpointEvalRows(
                transaction, "running", "analyze");
        const auto current = std::find_if(
            running.begin(),
            running.end(),
            [&](const CheckpointEvalRow& candidate) {
                return candidate.checkpointEvalId ==
                       claim.evaluation.checkpointEvalId;
            });
        if (current == running.end())
            throw std::runtime_error(
                "checkpoint_analysis_claim_no_longer_active");
        const std::optional<long long> inferenceResultId =
            FindCompletedCheckpointInferenceResultId(
                transaction, *current);
        if (!inferenceResultId)
            throw std::runtime_error(
                "missing_completed_checkpoint_inference");
        result.inferenceResultId = *inferenceResultId;
        result.metrics.modelId =
            current->checkpointModelId;
        ExperimentRow analysisExperiment =
            current->experiment;
        ApplyPersistedSymbolToAnalysisExperiment(
            transaction,
            analysisExperiment,
            result.metrics);
        if (!ApplyStructuredCheckpointInferenceMetrics(
                transaction, *current, result.metrics))
        {
            throw std::runtime_error(
                "checkpoint_inference_result_disappeared");
        }
        result.leaderScore =
            ComputeLeaderScore(result.metrics);
        transaction.commit();
        result.success = true;
    }
    catch (const std::exception& error)
    {
        result.error = error.what();
    }
    return result;
}

bool FinalizeCheckpointAnalysis(
    const SchedulerOptions& options,
    const ClaimedCheckpointAnalysis& claim,
    const CheckpointAnalysisWorkResult& work)
{
    pqxx::connection connection{LstmDbConnectionString()};
    pqxx::work transaction{connection};
    SetTransactionReadWrite(transaction);
    RequireAndRefreshSchedulerAuthority(transaction, options);
    EA::SchedulerOwnership::ExactAttemptExpectation expected;
    expected.workerAttemptId = claim.workerAttemptId;
    expected.experimentId =
        claim.evaluation.experiment.experimentId;
    expected.checkpointEvalId =
        claim.evaluation.checkpointEvalId;
    expected.workerKind = "checkpoint_analyze";
    expected.lifecyclePhase = "analyze";
    expected.capacityClass = "analyze";
    expected.schedulerInvocationId =
        options.schedulerAuthority.schedulerInvocationId;
    expected.schedulerFencingToken =
        options.schedulerAuthority.fencingToken;
    const auto exact =
        EA::SchedulerOwnership::LockAndVerifyExactActiveAttempt(
            transaction, expected, true);
    if (!exact)
        throw SchedulerAuthorityLost(
            "checkpoint_analysis_exact_attempt_replaced");

    const std::optional<long long> currentInferenceResult =
        FindCompletedCheckpointInferenceResultId(
            transaction, claim.evaluation);
    const bool success =
        work.success && currentInferenceResult &&
        *currentInferenceResult == work.inferenceResultId;
    if (success)
    {
        AnalysisScopeOptions scope;
        scope.scope = "checkpoint";
        scope.checkpointEvalId =
            claim.evaluation.checkpointEvalId;
        scope.checkpointEpoch =
            claim.evaluation.checkpointEpoch;
        scope.parentExperimentId =
            claim.evaluation.experiment.experimentId;
        UpsertAnalysisResult(
            transaction,
            claim.evaluation.experiment,
            work.metrics,
            work.leaderScore,
            scope);
        const std::optional<long long> analysisId =
            FindCheckpointAnalysisResultId(
                transaction,
                claim.evaluation.checkpointEvalId);
        std::ostringstream lifecycleSql;
        lifecycleSql
            << "UPDATE experiment_checkpoint_eval SET "
            << "status='completed',phase='done',"
            << "completed_at=clock_timestamp(),"
            << "updated_at=clock_timestamp(),error_message=NULL";
        if (ColumnExists(
                transaction,
                "experiment_checkpoint_eval",
                "analyze_completed_at"))
            lifecycleSql
                << ",analyze_completed_at=clock_timestamp()";
        lifecycleSql << ",analysis_id=$1";
        lifecycleSql
            << " WHERE checkpoint_eval_id=$2 "
            << "AND status='running' AND phase='analyze' "
            << "AND active_scheduler_worker_attempt_id=$3 "
            << "RETURNING checkpoint_eval_id;";
        pqxx::result lifecycle = transaction.exec_params(
            lifecycleSql.str(),
            analysisId,
            claim.evaluation.checkpointEvalId,
            claim.workerAttemptId);
        EA::SchedulerOwnership::RequireAffectedExactlyOne(
            lifecycle,
            "complete_checkpoint_analysis_exact_attempt");
        (void)EvaluateCheckpointPolicyAfterAnalysis(
            transaction, claim.evaluation);
    }

    const std::string failure =
        work.error.empty()
            ? "checkpoint_analysis_source_changed_before_finalize"
            : work.error;
    pqxx::result terminal = transaction.exec_params(
        "UPDATE experiment_scheduler_worker_attempt a SET "
        "lifecycle_state=$1,completed_at=clock_timestamp(),"
        "last_observed_at=clock_timestamp(),"
        "reconciliation_result=$2,diagnostic=$3 "
        "WHERE a.worker_attempt_id=$4 "
        "AND a.scheduler_invocation_id=$5 "
        "AND a.scheduler_fencing_token=$6 "
        "AND a.worker_kind='checkpoint_analyze' "
        "AND a.lifecycle_state='running' "
        "AND EXISTS (SELECT 1 "
        " FROM experiment_checkpoint_eval ce "
        " WHERE ce.checkpoint_eval_id=$7 "
        " AND ce.active_scheduler_worker_attempt_id="
        "a.worker_attempt_id) "
        "RETURNING a.worker_attempt_id;",
        success ? "completed" : "failed",
        success ? "checkpoint_analysis_completed"
                : "checkpoint_analysis_failed",
        success ? "result_persisted_exactly_once"
                : failure,
        claim.workerAttemptId,
        options.schedulerAuthority.schedulerInvocationId,
        options.schedulerAuthority.fencingToken,
        claim.evaluation.checkpointEvalId);
    EA::SchedulerOwnership::RequireAffectedExactlyOne(
        terminal,
        "terminalize_checkpoint_analysis_exact_attempt");

    pqxx::result cleared;
    if (success)
    {
        cleared = transaction.exec_params(
            "UPDATE experiment_checkpoint_eval SET "
            "active_scheduler_worker_attempt_id=NULL "
            "WHERE checkpoint_eval_id=$1 "
            "AND active_scheduler_worker_attempt_id=$2 "
            "AND status='completed' AND phase='done' "
            "RETURNING checkpoint_eval_id;",
            claim.evaluation.checkpointEvalId,
            claim.workerAttemptId);
    }
    else
    {
        cleared = transaction.exec_params(
            "UPDATE experiment_checkpoint_eval SET "
            "status='failed',completed_at=clock_timestamp(),"
            "error_message=$1,"
            "active_scheduler_worker_attempt_id=NULL,"
            "updated_at=clock_timestamp() "
            "WHERE checkpoint_eval_id=$2 "
            "AND active_scheduler_worker_attempt_id=$3 "
            "AND status='running' AND phase='analyze' "
            "RETURNING checkpoint_eval_id;",
            failure,
            claim.evaluation.checkpointEvalId,
            claim.workerAttemptId);
    }
    EA::SchedulerOwnership::RequireAffectedExactlyOne(
        cleared,
        "clear_checkpoint_analysis_exact_attempt_binding");
    RequireAndRefreshSchedulerAuthority(
        transaction, options);
    transaction.commit();
    return success;
}

int RunCheckpointEvalAnalyzeJobsLegacy(
    const SchedulerOptions& options)
{
    const std::optional<ClaimedCheckpointAnalysis> claim =
        ClaimCheckpointAnalysis(options);
    if (!claim)
        return 0;
    LogWorkerStarted(
        "CHECKPOINT_ANALYSIS_WORKER_STARTED",
        "checkpoint_analyze",
        claim->evaluation.experiment.experimentId,
        claim->evaluation.checkpointModelId,
        claim->evaluation.checkpointEvalId);
    if (SchedulerAuthorityTestFailpointEnabled(
            "checkpoint_analysis_crash_after_claim"))
    {
        std::cout
            << "CHECKPOINT_ANALYSIS_TEST_CRASH_AFTER_CLAIM"
            << ",checkpoint_eval_id="
            << claim->evaluation.checkpointEvalId
            << ",worker_attempt_id="
            << claim->workerAttemptId
            << std::endl;
        std::cout.flush();
        std::cerr.flush();
        ::_exit(86);
    }
    PersistSchedulerAuthorityLossForTest(
        options,
        "checkpoint_analysis_lease_loss_during_work");
    const CheckpointAnalysisWorkResult work =
        ExecuteCheckpointAnalysisWork(*claim);
    PersistSchedulerAuthorityLossForTest(
        options,
        "checkpoint_analysis_lease_loss_before_finalize");
    const bool completed =
        FinalizeCheckpointAnalysis(
            options, *claim, work);
    if (completed)
        TryGenerateExperimentReports(options);
    return completed ? 0 : 1;
}

int GlobalCapacityUsed(
    const SchedulerOptions& options,
    const std::string& capacityClass)
{
    pqxx::connection connection{LstmDbConnectionString()};
    pqxx::work transaction{connection};
    SetTransactionReadWrite(transaction);
    RequireAndRefreshSchedulerAuthority(transaction, options);
    const int used =
        CountGlobalWorkerCapacity(transaction, capacityClass);
    transaction.commit();
    return used;
}

int RunTrainJobs(
    const SchedulerOptions& options,
    const QueueSnapshot&,
    SchedulerEventLogState* logState,
    bool cancellationOnly = false)
{
    std::vector<ExperimentRow> jobs;
    int initialUsed = 0;
    {
        pqxx::connection connection{LstmDbConnectionString()};
        pqxx::work transaction{connection};
        SetTransactionReadWrite(transaction);
        RequireAndRefreshSchedulerAuthority(transaction, options);
        if (!SchedulerLaunchAllowed(
                transaction,
                "train",
                false,
                cancellationOnly))
        {
            transaction.commit();
            return 0;
        }
        jobs = LoadPendingExperiments(
            transaction, "train", cancellationOnly);
        initialUsed =
            CountGlobalWorkerCapacity(transaction, "train");
        transaction.commit();
    }

    PhaseSchedulingStats stats;
    stats.phase = "train";
    stats.examined = static_cast<int>(jobs.size());
    stats.freeSlots = AvailableWorkerProcessSlots(
        options.maxTrainProcs, initialUsed);
    EnsureLogDir(options.schedulerLogDir);
    int rc = 0;

    for (const ExperimentRow& job : jobs)
    {
        if (options.dryRun)
        {
            if (stats.launched >= stats.freeSlots)
            {
                ++stats.skipped;
                continue;
            }
            const std::vector<std::string> command =
                BuildTrainCommand(options, job);
            std::cout << "EXPERIMENT_CHILD_COMMAND"
                      << ",experiment_id=" << job.experimentId
                      << ",phase=train,dry_run=1,argv="
                      << CommandForDisplay(command)
                      << std::endl;
            ++stats.launched;
            continue;
        }

        const std::optional<long long> resumeFrom =
            job.resumeModelId ? job.resumeModelId : job.lastModelId;
        if (resumeFrom)
        {
            pqxx::connection connection{LstmDbConnectionString()};
            pqxx::work transaction{connection};
            SetTransactionReadWrite(transaction);
            RequireAndRefreshSchedulerAuthority(
                transaction, options);
            if (!ModelExists(transaction, *resumeFrom))
            {
                transaction.exec_params(
                    "UPDATE experiment SET status='failed',"
                    "completed_at=clock_timestamp(),exit_code=-1,"
                    "error_message='train_model_not_found',"
                    "updated_at=clock_timestamp() "
                    "WHERE experiment_id=$1 AND status='pending' "
                    "AND phase='train' "
                    "AND active_scheduler_worker_attempt_id IS NULL;",
                    job.experimentId);
                transaction.commit();
                ++stats.skipped;
                rc = 1;
                continue;
            }
            transaction.commit();
        }

        const std::string logPath =
            LogPathFor(options, job, "train");
        const auto attempt = ReserveExperimentWorkerAttempt(
            options,
            job,
            "train",
            logPath,
            options.maxTrainProcs,
            cancellationOnly);
        if (!attempt)
        {
            ++stats.skipped;
            const int used =
                GlobalCapacityUsed(options, "train");
            LogSkip(
                "train",
                job.experimentId,
                !SchedulerWorkerCapacityHasSlot(
                    options.maxTrainProcs, used)
                    ? "global_train_slots_full"
                    : "claim_changed",
                logState,
                options.schedulerVerbose);
            if (!SchedulerWorkerCapacityHasSlot(
                    options.maxTrainProcs, used))
                break;
            continue;
        }

        std::vector<std::string> command =
            BuildTrainCommand(options, job);
        std::cout << "EXPERIMENT_STARTED"
                  << ",experiment_id=" << job.experimentId
                  << ",phase=train,worker_attempt_id="
                  << attempt->workerAttemptId
                  << std::endl;
        try
        {
            PrintSchedulerExec(command);
            (void)LaunchReservedChildProcess(
                options, *attempt, std::move(command), resumeFrom);
            ++stats.launched;
        }
        catch (const std::exception& error)
        {
            std::cerr << "EXPERIMENT_FAILED"
                      << ",experiment_id=" << job.experimentId
                      << ",phase=train,worker_attempt_id="
                      << attempt->workerAttemptId
                      << ",error=" << error.what()
                      << std::endl;
            rc = 1;
        }
    }
    PrintPhaseSchedulingStats(
        stats, logState, options.schedulerVerbose);
    return rc;
}

int RunInferJobs(
    const SchedulerOptions& options,
    const QueueSnapshot&,
    SchedulerEventLogState* logState)
{
    std::vector<ExperimentRow> jobs;
    int initialUsed = 0;
    {
        pqxx::connection connection{LstmDbConnectionString()};
        pqxx::work transaction{connection};
        SetTransactionReadWrite(transaction);
        RequireAndRefreshSchedulerAuthority(transaction, options);
        if (!SchedulerLaunchAllowed(transaction, "infer"))
        {
            transaction.commit();
            return 0;
        }
        jobs = LoadPendingExperiments(transaction, "infer");
        initialUsed =
            CountGlobalWorkerCapacity(transaction, "infer");
        transaction.commit();
    }

    PhaseSchedulingStats stats;
    stats.phase = "infer";
    stats.examined = static_cast<int>(jobs.size());
    stats.freeSlots = AvailableWorkerProcessSlots(
        options.maxInferProcs, initialUsed);
    EnsureLogDir(options.schedulerLogDir);
    int rc = 0;

    for (const ExperimentRow& job : jobs)
    {
        bool eligible = true;
        {
            pqxx::connection connection{LstmDbConnectionString()};
            pqxx::work transaction{connection};
            SetTransactionReadWrite(transaction);
            RequireAndRefreshSchedulerAuthority(
                transaction, options);
            if (!job.lastModelId ||
                !ModelExists(transaction, *job.lastModelId))
            {
                if (!options.dryRun)
                {
                    transaction.exec_params(
                        "UPDATE experiment SET status='failed',"
                        "completed_at=clock_timestamp(),exit_code=-1,"
                        "error_message=$1,updated_at=clock_timestamp() "
                        "WHERE experiment_id=$2 AND status='pending' "
                        "AND phase='infer' "
                        "AND active_scheduler_worker_attempt_id IS NULL;",
                        job.lastModelId
                            ? "infer_model_not_found"
                            : "infer_missing_last_model_id",
                        job.experimentId);
                }
                eligible = false;
            }
            else
            {
                const bool forcedFinalInferenceRerun =
                    OperatorForcedFinalInferenceRerunRequested(
                        transaction, job.experimentId);
                if (!forcedFinalInferenceRerun &&
                    HasCompletedInferenceResult(transaction, job))
                {
                    if (!options.dryRun)
                    {
                        std::cout
                            << "SCHEDULER_SKIP_EXISTING_INFERENCE"
                            << ",experiment_id=" << job.experimentId
                            << ",model_id=" << *job.lastModelId
                            << std::endl;
                        if (HasCompletedAnalysisResult(
                                transaction, job))
                            MarkExperimentDone(
                                transaction, job, "infer");
                        else
                            MarkExperimentPendingPhase(
                                transaction, job, "infer", "analyze");
                    }
                    eligible = false;
                }
                else if (forcedFinalInferenceRerun)
                {
                    std::cout
                        << "SCHEDULER_FORCED_FINAL_INFERENCE_RERUN_DISPATCH"
                        << ",experiment_id=" << job.experimentId
                        << ",model_id=" << *job.lastModelId
                        << std::endl;
                }
            }
            transaction.commit();
        }
        if (!eligible)
        {
            ++stats.skipped;
            continue;
        }

        if (options.dryRun)
        {
            if (stats.launched >= stats.freeSlots)
            {
                ++stats.skipped;
                continue;
            }
            std::cout << "EXPERIMENT_CHILD_COMMAND"
                      << ",experiment_id=" << job.experimentId
                      << ",phase=infer,dry_run=1,argv="
                      << CommandForDisplay(
                             BuildInferCommand(options, job))
                      << std::endl;
            ++stats.launched;
            continue;
        }

        const std::string logPath =
            LogPathFor(options, job, "infer");
        const auto attempt = ReserveExperimentWorkerAttempt(
            options,
            job,
            "infer",
            logPath,
            options.maxInferProcs);
        if (!attempt)
        {
            ++stats.skipped;
            const int used =
                GlobalCapacityUsed(options, "infer");
            LogSkip(
                "infer",
                job.experimentId,
                !SchedulerWorkerCapacityHasSlot(
                    options.maxInferProcs, used)
                    ? "global_infer_slots_full"
                    : "claim_changed",
                logState,
                options.schedulerVerbose);
            if (!SchedulerWorkerCapacityHasSlot(
                    options.maxInferProcs, used))
                break;
            continue;
        }

        try
        {
            std::vector<std::string> command =
                BuildInferCommand(options, job);
            PrintSchedulerExec(command);
            (void)LaunchReservedChildProcess(
                options,
                *attempt,
                std::move(command),
                job.lastModelId);
            ++stats.launched;
        }
        catch (const std::exception& error)
        {
            std::cerr << "EXPERIMENT_FAILED"
                      << ",experiment_id=" << job.experimentId
                      << ",phase=infer,worker_attempt_id="
                      << attempt->workerAttemptId
                      << ",error=" << error.what()
                      << std::endl;
            rc = 1;
        }
    }
    PrintPhaseSchedulingStats(
        stats, logState, options.schedulerVerbose);
    return rc;
}

